_FREQ_Q = None


class _HybridTokenMetrics:
    """Streaming proper scores, rank and calibration on teacher-forced tokens.
    Chunking caps extra probability storage at 256 x vocabulary, not B*T*V.
    Equal-width ECE bins; Brier is the multiclass sum, range [0,2].
    Ranks use optimistic ties. Scores are descriptive, not selection axes.
    """
    def __init__(self):
        self.n = self.top5 = self.top10 = self.unk = 0
        self.nll = []
        self.rr = self.rank = self.brier = self.entropy = self.confidence = 0.
        self.bins = np.zeros((15, 3), dtype=np.float64)
        self.strata = {k:[0.,0] for k in ["nll_pos_0_32","nll_pos_32_128","nll_pos_128_end"]+[f"nll_freq_q{i}" for i in range(4)]}

    def add(self, flat, targets, ctx=None):
        offset=0
        for z, y in zip(flat.split(256), targets.split(256)):
            z = z.float()
            lp = F.log_softmax(z, dim=-1)
            prob = lp.exp()
            gold_lp = lp.gather(1, y[:, None]).squeeze(1)
            self.nll.extend((-gold_lp).cpu().tolist())
            if TASK.get("extra_metrics") and ctx is not None:
                positions=torch.arange(offset,offset+y.numel(),device=y.device)%ctx
                masks={"nll_pos_0_32":positions<32,"nll_pos_32_128":(positions>=32)&(positions<128),"nll_pos_128_end":positions>=128}
                if _FREQ_Q is not None:
                    freq=_FREQ_Q.to(y.device)[y]
                    masks.update({f"nll_freq_q{i}":freq==i for i in range(4)})
                for key,mask in masks.items():
                    self.strata[key][0]+=float((-gold_lp)[mask].sum())
                    self.strata[key][1]+=int(mask.sum())
            offset+=y.numel()
            k = min(10, z.size(1))
            top = z.topk(k, dim=1).indices
            self.top5 += int((top[:, :min(5,k)] == y[:, None]).any(1).sum())
            self.top10 += int((top == y[:, None]).any(1).sum())
            rank = (z > z.gather(1, y[:, None])).sum(1).double() + 1
            self.rank += float(rank.sum())
            self.rr += float(rank.reciprocal().sum())
            self.brier += float((prob.square().sum(1) - 2*gold_lp.exp() + 1).sum())
            self.entropy += float((-(prob * lp).sum(1)).sum())
            conf, pred = prob.max(1)
            correct = pred.eq(y)
            self.confidence += float(conf.sum())
            bin_id = (conf * 15).long().clamp(max=14)
            count = torch.bincount(bin_id, minlength=15)
            conf_sum = torch.bincount(bin_id, weights=conf, minlength=15)
            acc_sum = torch.bincount(bin_id, weights=correct.float(), minlength=15)
            self.bins += torch.stack([count, conf_sum, acc_sum], 1).cpu().numpy()
            self.n += y.numel()
            self.unk += int((y == 0).sum())

    def finish(self):
        n = self.n
        if not n:
            raise ValueError("Language evaluation has no target tokens")
        a = np.asarray(self.nll, dtype=np.float64)
        b = self.bins[self.bins[:,0] > 0]
        gaps = np.abs(b[:,1]-b[:,2])/b[:,0]
        result = dict(test_tokens=n, test_nll_sum=float(a.sum()),
                    bits_per_token=float(a.mean()/math.log(2)),
                    nll_std=float(a.std()),
                    **{f"nll_p{q}": float(np.percentile(a,q)) for q in [50,90,95,99]},
                    token_top5_acc=self.top5/n, token_top10_acc=self.top10/n,
                    mean_reciprocal_rank=self.rr/n, mean_target_rank=self.rank/n,
                    brier_score=self.brier/n, predictive_entropy_nats=self.entropy/n,
                    mean_confidence=self.confidence/n,
                    ece_15=float((gaps*b[:,0]).sum()/n), mce_15=float(gaps.max()),
                    calibration_bins=[dict(lower=i/15, upper=(i+1)/15,
                        count=int(row[0]), confidence_sum=float(row[1]), correct_sum=float(row[2]))
                        for i, row in enumerate(self.bins)],
                    unk_target_fraction=(self.unk/n if TASK["dataset"] in
                                         ("wikitext2", "wikitext103", "ptb") else float("nan")),
                    bits_per_byte=(float(a.mean()/math.log(2))
                                   if TASK["dataset"] == "enwik8" else float("nan")))
        if TASK.get("extra_metrics"):
            result.update({key:total/count if count else None for key,(total,count) in self.strata.items()})
            result["x_errors"]={key:"no evaluated tokens in stratum" for key,(total,count) in self.strata.items() if not count}
        return result



def estimate_fwd_flops(model, batch_size):
    """Rough forward-pass FLOPs (2*MACs): all Linear matmuls over B*T tokens,
    plus the attention score/​context matmuls. Descriptive only."""
    B, T = batch_size, TASK.get("ctx", GPT_CTX)
    flops = 0.0
    for m in model.modules():
        if isinstance(m, nn.Linear):
            flops += 2.0 * m.in_features * m.out_features * B * T
    n_layer = len(model.blocks)
    d_model = model.wte.embedding_dim
    flops += 4.0 * B * n_layer * T * T * d_model        # QK^T + softmax@V
    return flops

GPT_N_LAYER = 6
GPT_D_MODEL = 256
GPT_N_HEAD  = 8
GPT_CTX     = 256
GPT_MLP_MULT = 4
VOCAB_CAP   = 16000        # word-level cap (enwik8 overrides to 256, byte-level)


class _Block(nn.Module):
    def __init__(self, d, n_head):
        super().__init__()
        self.ln1 = nn.LayerNorm(d)
        self.qkv = nn.Linear(d, 3 * d)
        self.proj = nn.Linear(d, d)
        self.ln2 = nn.LayerNorm(d)
        self.fc1 = nn.Linear(d, GPT_MLP_MULT * d)
        self.fc2 = nn.Linear(GPT_MLP_MULT * d, d)
        self.n_head = n_head
        self.d = d

    def forward(self, x):
        B, T, C = x.shape
        h = self.ln1(x)
        q, k, v = self.qkv(h).split(self.d, dim=2)
        hd = C // self.n_head
        q = q.view(B, T, self.n_head, hd).transpose(1, 2)
        k = k.view(B, T, self.n_head, hd).transpose(1, 2)
        v = v.view(B, T, self.n_head, hd).transpose(1, 2)
        # Manual causal attention (NOT F.scaled_dot_product_attention): the fused
        # SDPA kernels do not support the DOUBLE backward that Sophia's
        # Hutchinson Hessian probe needs (fails on CPU, fragile on CUDA). This
        # plain form is double-backward-safe everywhere and is cheap at this
        # model size.
        att = (q @ k.transpose(-2, -1)) * (1.0 / math.sqrt(hd))
        causal = torch.triu(torch.ones(T, T, device=x.device, dtype=torch.bool),
                            diagonal=1)
        att = att.masked_fill(causal, float("-inf"))
        att = F.softmax(att, dim=-1)
        a = (att @ v).transpose(1, 2).contiguous().view(B, T, C)
        x = x + self.proj(a)
        h = self.ln2(x)
        x = x + self.fc2(F.gelu(self.fc1(h)))
        return x


class SmallGPT(nn.Module):
    def __init__(self, vocab_size, n_layer=GPT_N_LAYER, d_model=GPT_D_MODEL,
                 n_head=GPT_N_HEAD, ctx=GPT_CTX):
        super().__init__()
        d = d_model
        self.vocab_size = vocab_size
        self.wte = nn.Embedding(vocab_size, d)
        self.wpe = nn.Embedding(ctx, d)
        self.blocks = nn.ModuleList([_Block(d, n_head) for _ in range(n_layer)])
        self.ln_f = nn.LayerNorm(d)
        self.lm_head = nn.Linear(d, vocab_size, bias=False)
        self.lm_head.weight = self.wte.weight            # weight tying
        self.apply(self._init)
        # Muon: exclude the (tied) token embedding, positional embedding and the
        # output projection -> those go to Muon's AdamW sub-group. Everything
        # else with ndim>=2 (attn/MLP matrices) gets the Muon update.
        self._muon_exclude_names = ["wte", "wpe", "lm_head"]

    @staticmethod
    def _init(m):
        if isinstance(m, nn.Linear):
            nn.init.normal_(m.weight, std=0.02)
            if m.bias is not None:
                nn.init.zeros_(m.bias)
        elif isinstance(m, nn.Embedding):
            nn.init.normal_(m.weight, std=0.02)
        elif isinstance(m, nn.LayerNorm):
            nn.init.ones_(m.weight)
            nn.init.zeros_(m.bias)

    def forward(self, idx):
        B, T = idx.shape
        pos = torch.arange(T, device=idx.device)
        x = self.wte(idx) + self.wpe(pos)[None, :, :]
        for blk in self.blocks:
            x = blk(x)
        x = self.ln_f(x)
        return self.lm_head(x)


# ---------------------------------------------------------------------------
#  Corpora -> a single int64 token stream per split.
# ---------------------------------------------------------------------------
def _word_vocab(tokens, cap):
    from collections import Counter
    cnt = Counter(tokens)
    top = [w for w, _ in cnt.most_common(cap - 1)]
    stoi = {"<unk>": 0}
    for w in top:
        stoi[w] = len(stoi)
    return stoi


def _encode_words(tokens, stoi):
    unk = 0
    return np.fromiter((stoi.get(t, unk) for t in tokens), dtype=np.int32,
                       count=len(tokens))       # int32: 16k vocab, half the RAM


def _hf_text(name, config):
    _require("datasets")
    import datasets as hfds
    if TASK.get("opt_set") == "muonhybrid":
        for attempt in range(3):
            try:
                ds = hfds.load_dataset(name, config)
                break
            except (ConnectionError, TimeoutError, OSError) as exc:
                if attempt == 2:
                    raise RuntimeError(f"Dataset {name}/{config} unavailable after 3 attempts; "
                                       "check network or HF cache, then resume") from exc
                log(f"[data] transient load failure ({exc!r}); retry {attempt+1}/2")
                time.sleep(2 ** attempt)
    else:
        ds = hfds.load_dataset(name, config)
    return ("".join(ds["train"]["text"]),
            "".join(ds["validation"]["text"]),
            "".join(ds["test"]["text"]))


def _load_ptb():
    try:
        _require("datasets")
        import datasets as hfds
        ds = hfds.load_dataset("ptb_text_only", "penn_treebank", trust_remote_code=True)
        j = lambda s: "\n".join(x.strip() for x in ds[s]["sentence"])
        return j("train"), j("validation"), j("test")
    except Exception as e:
        log(f"[data] HF ptb_text_only failed ({e!r}); downloading raw Mikolov PTB")
        import urllib.request
        base = ("https://raw.githubusercontent.com/wojzaremba/lstm/master/data/")
        out = {}
        for split, fn in [("train", "ptb.train.txt"), ("validation", "ptb.valid.txt"),
                          ("test", "ptb.test.txt")]:
            with urllib.request.urlopen(base + fn, timeout=60) as r:
                out[split] = r.read().decode("utf-8")
        return out["train"], out["validation"], out["test"]


def _load_enwik8():
    root = os.environ.get("BENCH12_DATA_ROOT", os.path.join(CKPT_ROOT, "_data"))
    os.makedirs(root, exist_ok=True)
    path = os.path.join(root, "enwik8")
    if not os.path.exists(path):
        import urllib.request, zipfile, io
        for url in ("https://huggingface.co/datasets/enwik8/resolve/main/enwik8.zip",
                    "http://mattmahoney.net/dc/enwik8.zip"):
            try:
                log(f"[data] downloading enwik8 from {url}")
                with urllib.request.urlopen(url, timeout=120) as r:
                    raw = r.read()
                with zipfile.ZipFile(io.BytesIO(raw)) as z:
                    with z.open("enwik8") as f, open(path, "wb") as g:
                        g.write(f.read())
                break
            except Exception as e:
                log(f"[data] enwik8 source failed ({url}): {e!r}")
        if not os.path.exists(path):
            fail("could not download enwik8 from any known source; place the "
                 "decompressed 'enwik8' file at " + path)
    data = np.frombuffer(open(path, "rb").read(), dtype=np.uint8)  # bytes, cast in getitem
    n = len(data)
    n_tr = 90_000_000 if n >= 100_000_000 else int(n * 0.9)
    n_va = 5_000_000 if n >= 100_000_000 else int(n * 0.05)
    return data[:n_tr], data[n_tr:n_tr + n_va], data[n_tr + n_va:], 256


def _smoke_streams():
    rng = np.random.RandomState(0)
    V = 97
    return (rng.randint(0, V, size=20000).astype(np.int64),
            rng.randint(0, V, size=4000).astype(np.int64),
            rng.randint(0, V, size=4000).astype(np.int64), V)


# ---------------------------------------------------------------------------
#  OpenWebText (evie-scalegen-spec.md sec 3.2/4.2): GPT-2 BPE via tiktoken,
#  NOT the word-level _word_vocab/_encode_words pipeline above (real 50257-
#  token vocab, no <unk>). Streamed from Skylion007/openwebtext in HF
#  streaming mode -- never downloads the full ~40GB corpus -- and cached as
#  nanoGPT-style uint16 .bin files + meta.json under
#  {BENCH12_DATA_ROOT}/openwebtext_gpt2bpe/. A warm, verified cache loads with
#  no network at all (matches the enwik8/PTB "frozen snapshot" convention).
# ---------------------------------------------------------------------------
def _sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def _openwebtext_cache_ok(cache_dir, token_budget):
    """Returns the validated meta dict if a warm cache exists, matches the
    requested token_budget, and passes the token-count + sha256 integrity
    check (spec sec 5: never trust a cache hit without recomputing this).
    Returns None (with a logged reason) on any mismatch -- the caller
    rebuilds from scratch rather than silently continuing on a corrupt or
    truncated cache."""
    meta_path = os.path.join(cache_dir, "meta.json")
    if not os.path.exists(meta_path):
        return None
    try:
        with open(meta_path) as fh:
            meta = json.load(fh)
    except Exception as e:
        log(f"[data] openwebtext: meta.json unreadable ({e!r}); rebuilding")
        return None
    if meta.get("tokenizer") != "gpt2" or meta.get("vocab") != 50257:
        log(f"[data] openwebtext: meta.json tokenizer/vocab mismatch; rebuilding")
        return None
    for split in ("train", "val", "test"):
        p = os.path.join(cache_dir, f"{split}.bin")
        want_n = meta.get("tokens", {}).get(split)
        if not os.path.exists(p) or want_n is None:
            log(f"[data] openwebtext: {split}.bin/meta entry missing; rebuilding")
            return None
        n_tok = os.path.getsize(p) // 2                # uint16 = 2 bytes/token
        if n_tok != want_n:
            log(f"[data] openwebtext: {split}.bin has {n_tok} tokens, "
                f"meta.json says {want_n}; rebuilding")
            return None
        sha = _sha256_file(p)
        want_sha = meta.get("sha256", {}).get(split)
        if sha != want_sha:
            log(f"[data] openwebtext: {split}.bin sha256 mismatch (cache "
                f"truncated/corrupt from an interrupted prior run); rebuilding")
            return None
    if meta["tokens"]["train"] < token_budget:
        log(f"[data] openwebtext: cached train={meta['tokens']['train']} tokens "
            f"< requested token_budget={token_budget}; rebuilding")
        return None
    return meta


def _build_openwebtext_cache(cache_dir, token_budget, val_tokens=5_000_000,
                             test_tokens=5_000_000):
    _require("tiktoken")
    _require("datasets")
    import tiktoken
    import datasets as hfds

    enc = tiktoken.get_encoding("gpt2")
    EOT = 50256
    need = token_budget + val_tokens + test_tokens
    log(f"[data] openwebtext: no warm/valid cache -- streaming "
        f"Skylion007/openwebtext (HF streaming mode, never downloads the full "
        f"~40GB corpus) until {need} tokens accumulated (train={token_budget} "
        f"val={val_tokens} test={test_tokens})")

    # Retry with backoff (spec sec 5): this custom streaming/tokenize path,
    # unlike torchvision/HF datasets' own loaders for the other 4 language
    # tasks, has no retry handling upstream.
    buf, total, last_err = [], 0, None
    for attempt in range(3):
        try:
            ds = hfds.load_dataset("Skylion007/openwebtext", split="train",
                                   streaming=True, trust_remote_code=True)
            for doc in ds:
                toks = enc.encode_ordinary(doc["text"])
                toks.append(EOT)
                buf.append(np.asarray(toks, dtype=np.uint16))
                total += len(toks)
                if len(buf) % 2000 == 0:
                    log(f"[data] openwebtext: streamed {total}/{need} tokens "
                        f"({len(buf)} docs)")
                if total >= need:
                    break
            break
        except Exception as e:
            last_err = e
            wait = 2.0 ** attempt
            log(f"[data] openwebtext: streaming pull failed ({e!r}); "
                f"retrying in {wait:.0f}s")
            time.sleep(wait)
    else:
        fail(f"openwebtext: HF streaming failed after 3 attempts: {last_err!r}")

    if total < need:
        fail(f"openwebtext stream exhausted at {total} tokens, need {need} "
             f"(train={token_budget} val={val_tokens} test={test_tokens}); "
             f"lower token_budget or check the HF streaming source")

    all_tok = np.concatenate(buf)
    # Fixed, deterministic slices (spec sec 3.2): first val_tokens -> val, next
    # test_tokens -> test, remainder up to token_budget -> train. Reproducible
    # without needing to shuffle a stream.
    splits = {
        "val": all_tok[:val_tokens],
        "test": all_tok[val_tokens:val_tokens + test_tokens],
        "train": all_tok[val_tokens + test_tokens:
                         val_tokens + test_tokens + token_budget],
    }

    # Atomic write: temp file + os.replace per split, same discipline as
    # atomic_torch_save/_write_json in frag_engine.py (spec sec 5) -- a
    # process killed mid-tokenization must leave either the old good cache or
    # nothing, never a half-written file a later run mistakes for complete.
    tmp_paths = {}
    for split, arr in splits.items():
        tmp = os.path.join(cache_dir, f".{split}.bin.tmp.{os.getpid()}")
        with open(tmp, "wb") as fh:
            arr.astype(np.uint16).tofile(fh)
            fh.flush()
            os.fsync(fh.fileno())
        tmp_paths[split] = tmp

    meta = {
        "tokenizer": "gpt2", "vocab": 50257,
        "tokens": {s: int(len(a)) for s, a in splits.items()},
        "sha256": {s: _sha256_file(p) for s, p in tmp_paths.items()},
    }
    meta_tmp = os.path.join(cache_dir, f".meta.json.tmp.{os.getpid()}")
    with open(meta_tmp, "w") as fh:
        json.dump(meta, fh, indent=2)
        fh.flush()
        os.fsync(fh.fileno())

    for split, tmp in tmp_paths.items():
        os.replace(tmp, os.path.join(cache_dir, f"{split}.bin"))
    os.replace(meta_tmp, os.path.join(cache_dir, "meta.json"))
    log(f"[data] openwebtext: wrote cache at {cache_dir} "
        f"(train={meta['tokens']['train']} val={meta['tokens']['val']} "
        f"test={meta['tokens']['test']} tokens)")
    return meta


def _load_openwebtext():
    cache_dir = os.path.join(
        os.environ.get("BENCH12_DATA_ROOT", os.path.join(CKPT_ROOT, "_data")),
        "openwebtext_gpt2bpe")
    os.makedirs(cache_dir, exist_ok=True)
    token_budget = int(TASK.get("token_budget", 220_000_000))

    meta = _openwebtext_cache_ok(cache_dir, token_budget)
    if meta is not None:
        log(f"[data] openwebtext: warm cache hit at {cache_dir}, no network")
    else:
        meta = _build_openwebtext_cache(cache_dir, token_budget)

    def _memmap(split):
        return np.memmap(os.path.join(cache_dir, f"{split}.bin"), dtype=np.uint16,
                         mode="r", shape=(meta["tokens"][split],))

    train = _memmap("train")[:token_budget]
    val, test = _memmap("val"), _memmap("test")
    return train, val, test, 50257


def prepare_data():
    ds = TASK["dataset"]
    if SMOKE:
        tr, va, te, V = _smoke_streams()
    elif ds == "enwik8":
        tr, va, te, V = _load_enwik8()
    elif ds == "openwebtext":
        tr, va, te, V = _load_openwebtext()
    else:
        # "Salesforce/wikitext" is the dataset's current Hub id; huggingface_hub
        # >= ~1.3 rejects the old bare id "wikitext" (HfUriError). Same files:
        # verified 2026-11-09 that WikiText-2 gives the main run's exact token
        # counts (train 2,051,910 / val 213,886 / test 241,211).
        if ds == "wikitext2":
            train_txt, val_txt, test_txt = _hf_text("Salesforce/wikitext", "wikitext-2-raw-v1")
        elif ds == "wikitext103":
            train_txt, val_txt, test_txt = _hf_text("Salesforce/wikitext", "wikitext-103-raw-v1")
        elif ds == "ptb":
            train_txt, val_txt, test_txt = _load_ptb()
        else:
            raise ValueError(f"unknown language dataset {ds!r}")
        tr_tok = train_txt.split()
        stoi = _word_vocab(tr_tok, VOCAB_CAP)
        V = len(stoi)
        tr = _encode_words(tr_tok, stoi)
        va = _encode_words(val_txt.split(), stoi)
        te = _encode_words(test_txt.split(), stoi)

    if ds == "wikitext103" and not SMOKE:
        budget = int(TASK.get("token_budget", 120_000_000))
        if len(tr) > budget:
            log(f"[data] wikitext103: capping train stream {len(tr)} -> {budget} "
                f"tokens (token-budget cap; eval/test splits are full)")
            tr = tr[:budget]

    if ds == "openwebtext":
        # real GPT-2 BPE vocab, no <unk>/OOV concept -- the train_oov line the
        # other 4 tasks print is meaningless here, so it's skipped, not faked
        # (evie-scalegen-spec.md sec 3.2).
        log(f"[data] {ds}: vocab={V}  train_tok={len(tr)}  val_tok={len(va)}  "
            f"test_tok={len(te)}  (GPT-2 BPE vocab -- no <unk>/OOV concept, "
            f"train_oov line intentionally skipped for this dataset)")
    else:
        oov = float(np.mean(tr == 0)) if len(tr) else float("nan")
        log(f"[data] {ds}: vocab={V}  train_tok={len(tr)}  val_tok={len(va)}  "
            f"test_tok={len(te)}  train_oov(<unk>)={oov:.3f}")
    if TASK.get("extra_metrics"):
        global _FREQ_Q
        if _FREQ_Q is None:
            counts=np.bincount(np.asarray(tr,dtype=np.int64),minlength=int(V))
            order=np.argsort(-counts,kind="stable")
            before=np.cumsum(counts[order])-counts[order]
            quart=np.minimum(3,(4*before)//max(1,int(counts.sum())))
            q=np.full(int(V),3,dtype=np.int64);q[order]=quart;q[counts==0]=3
            _FREQ_Q=torch.from_numpy(q)
    return {"name": ds, "vocab": int(V), "train": tr, "val": va, "test": te}


class _LMWindows(torch.utils.data.Dataset):
    """Overlapping windows for train (stride 1), non-overlapping for eval."""

    def __init__(self, stream, ctx, stride):
        self.s = stream
        self.ctx = ctx
        self.stride = stride
        self.n = max(0, (len(stream) - ctx - 1) // stride + 1)

    def __len__(self):
        return self.n

    def __getitem__(self, i):
        j = i * self.stride
        chunk = np.asarray(self.s[j:j + self.ctx + 1], dtype=np.int64)
        return torch.from_numpy(chunk[:-1]), torch.from_numpy(chunk[1:])


def lr_search_units(data):
    return ["full"]


def main_units(data):
    return ["full"]


def build_model(data, unit):
    if SMOKE and TASK.get("extra_metrics"):
        return SmallGPT(data["vocab"],n_layer=1,d_model=16,n_head=2,ctx=TASK.get("ctx",GPT_CTX))
    ms = data.get("model_size")          # set only by the model-size sweep driver
    ctx = TASK.get("ctx", GPT_CTX)        # scalegen (language_openwebtext): 512
    if ms:
        return SmallGPT(data["vocab"], n_layer=ms["n_layer"],
                        d_model=ms["d_model"], n_head=ms["n_head"], ctx=ctx)
    n_layer = TASK.get("n_layer", GPT_N_LAYER)
    d_model = TASK.get("d_model", GPT_D_MODEL)
    n_head = TASK.get("n_head", GPT_N_HEAD)
    return SmallGPT(data["vocab"], n_layer=n_layer, d_model=d_model,
                    n_head=n_head, ctx=ctx)


def make_criterion():
    return nn.CrossEntropyLoss()


def make_loaders(data, unit, batch_size, seed):
    nw = 0 if SMOKE else 2
    g = torch.Generator().manual_seed(seed)
    ctx = TASK.get("ctx", GPT_CTX)
    tr = _LMWindows(data["train"], ctx, stride=ctx)      # non-overlap train
    va = _LMWindows(data["val"], ctx, stride=ctx)
    te = _LMWindows(data["test"], ctx, stride=ctx)
    eval_bs = max(batch_size, 64)
    if TASK.get("opt_set") == "muonhybrid" or TASK.get("extra_metrics"):
        # Keep the protocol's model/data/batch and exact token weighting; only
        # evaluation microbatching changes. In particular OWT must never build
        # a 64 x 512 x 50257 logit tensor on a 20 GB MIG slice.
        eval_bs = max(1, min(16, batch_size // 2))
        if TASK.get("extra_metrics"):
            # Final Hessian probes retain higher-order graphs from the first
            # four validation batches. Bound those graphs on the 20GB slice.
            eval_bs = min(eval_bs, 1 if TASK.get("d_model",GPT_D_MODEL)>=768 else 4)
    if TASK.get("opt_set") == "muonhybrid" and (len(tr) < batch_size or not len(va) or not len(te)):
        raise ValueError("Dataset has insufficient train/validation/test windows; refusing an empty evaluation")
    train_loader = torch.utils.data.DataLoader(
        tr, batch_size=batch_size, shuffle=True, drop_last=True, num_workers=nw,
        pin_memory=torch.cuda.is_available(), generator=g,
        persistent_workers=(nw > 0))
    val_loader = torch.utils.data.DataLoader(
        va, batch_size=eval_bs, shuffle=False, num_workers=nw,
        pin_memory=torch.cuda.is_available(), persistent_workers=(nw > 0))
    test_loader = torch.utils.data.DataLoader(
        te, batch_size=eval_bs, shuffle=False, num_workers=nw,
        pin_memory=torch.cuda.is_available(), persistent_workers=(nw > 0))
    return train_loader, val_loader, test_loader


def batch_to_device(batch):
    x, y = batch
    return x.to(DEVICE, non_blocking=True), y.to(DEVICE, non_blocking=True)


def forward_loss(model, batch, criterion):
    x, y = batch
    logits = model(x)
    return criterion(logits.reshape(-1, logits.size(-1)), y.reshape(-1))


@torch.no_grad()
def evaluate(model, loader, criterion, extended_metrics=False, extra_deadline=None):
    model.eval()
    tot_tok, ce_sum, correct = 0, 0.0, 0
    extra = _HybridTokenMetrics() if extended_metrics else None
    extra_errors={}
    for batch in loader:
        x, y = batch_to_device(batch)
        logits = model(x)
        flat = logits.reshape(-1, logits.size(-1))
        yt = y.reshape(-1)
        ce_sum += float(F.cross_entropy(flat, yt, reduction="sum").item())
        tot_tok += yt.numel()
        correct += int((flat.argmax(-1) == yt).sum().item())
        if extra is not None:
            try:
                if extra_deadline is not None and time.monotonic()>extra_deadline:
                    raise TimeoutError("end-of-run diagnostic budget exhausted")
                extra.add(flat, yt, ctx=y.size(1))
            except Exception as exc:
                if not isinstance(exc,TimeoutError) and classify_exception(exc)=="env":raise
                extra_errors["token_diagnostics"]=repr(exc);extra=None
    mean_ce = ce_sum / max(tot_tok, 1)
    aux = {
        "bpc": mean_ce / math.log(2.0),          # bits per symbol (== bpc for enwik8)
        "test_loss": mean_ce,
        "token_acc": correct / max(tot_tok, 1),  # next-token top-1, descriptive
    }
    if extra is not None:
        values=_safe_extra("token_diagnostics",extra.finish,extra_errors)
        if values is not None:aux.update(values)
    if extra_errors:
        for key in _HYBRID_TOKEN_METRICS+EXTRA_DOMAIN_KEYS.get("language",[]):
            aux.setdefault(key,None)
            extra_errors.setdefault(key,extra_errors["token_diagnostics"])
        aux["x_errors"]=extra_errors
    return math.exp(min(mean_ce, 50.0)), aux


# === SHARED OPTIMIZER BLOCK -- keep identical across all 12 files ===
# ---------------------------------------------------------------------------
# This block is the single source of truth for every baseline optimizer used
# in the ICLR benchmark harness. It is pasted BYTE-FOR-BYTE IDENTICAL into all
# 12 task files by benchmark12/_build/build.py. Do NOT hand-edit it inside a
# generated file -- edit benchmark12/_build/frag_shared_optim.py and re-run
# build.py so the change lands in all 12 at once (see benchmark protocol sec 2).
#
# Contract with the rest of the file (defined above this block, in the header):
#   - torch, torch.nn as nn, math, numpy as np  are imported
#   - WEIGHT_DECAY            : float  (decoupled weight decay, all optimizers)
#   - GRAD_CLIP_NORM          : float  (global grad-norm clip, applied by engine)
#   - HESS_FREQ, N_HUTCH      : int    (Sophia Hutchinson probe cadence / count)
#   - log(msg)                : function (stdout + logfile)
#
# Optimizers provided here: AdaBelief, SGDM (SGD+momentum+Nesterov), Sophia,
# Muon (hybrid: Newton-Schulz on >=2D params, AdamW on the rest), Lion.
# AdamW itself is torch.optim.AdamW (stdlib) and is built in build_optimizer().
#
# Weight decay convention (benchmark protocol sec 4): decoupled, applied as
#   p <- p * (1 - lr * lambda)
# BEFORE the gradient-based update, never as L2-in-loss. Every custom optimizer
# below implements it that way; torch.optim.AdamW already does.
# ---------------------------------------------------------------------------

# Optimizer-family hyperparameters (frozen 2026-09-08, benchmark protocol sec 4).
SOPHIA_BETAS      = (0.965, 0.99)   # (grad EMA, Hessian EMA)
SOPHIA_RHO        = 0.04
SOPHIA_EPS        = 1e-8
SOPHIA_BETA_H     = 0.99            # Hessian EMA used inside set_hessian()
ADABELIEF_BETAS   = (0.9, 0.999)
ADABELIEF_EPS     = 1e-16          # AdaBelief paper default
SGDM_MOMENTUM     = 0.9
SGDM_NESTEROV     = True
LION_BETAS        = (0.9, 0.99)
MUON_MOMENTUM     = 0.95
MUON_NESTEROV     = True
MUON_NS_STEPS     = 5
MUON_NS_COEFFS    = (3.4445, -4.7750, 2.0315)   # Newton-Schulz quintic (Keller Jordan)
MUON_UPDATE_SCALE = 0.2            # update <- MUON_UPDATE_SCALE * sqrt(max(fan_out, fan_in)) * orthogonalized
MUON_ADAMW_BETAS  = (0.9, 0.999)  # AdamW sub-group inside the Muon hybrid
MUON_ADAMW_EPS    = 1e-8

# --- Shampoo (per-layer, AdamW-norm-grafted) -- the "matrix vs diagonal"
#     baseline the Evie-KF ablation needs (optimizer specification sec 3). Ungrafted
#     Shampoo is unstable at this scale; we graft the AdamW update norm.
SHAMPOO_BETA        = 0.95         # preconditioner EMA (tuned jointly with LR)
SHAMPOO_EPS         = 1e-6
SHAMPOO_UPDATE_FREQ = 20           # steps between L^-1/4 / R^-1/4 refreshes
SHAMPOO_GRAFT_BETAS = (0.9, 0.999) # AdamW graft moments
SHAMPOO_MAXF        = 1024         # 2-D params with a dim > this fall to the graft
SHAMPOO_KNOB_GRID   = [0.9, 0.95, 0.99, 0.999]   # `beta`, the second tuned axis

# --- Evie-KF: Kronecker-factored risk-sensitive preconditioner
#     (optimizer specification sec 4.1; full derivation in evie-kf-full-specification.md).
#     Numerics are ground-truthed against the validated flat-vector reference in
#     "the reference optimizer" -- see
#     benchmark12/tests/test_eviekf.py::test_parity_vs_kaggle_reference.
#
#     One class, four flags, four rungs of the claim ladder:
#       gamma=0        -> AdamW, exactly (bit-identical by construction)
#       diag_only=True -> Evie-diag  (Sigma diagonal; SDProp-2017 / AdaBelief family)
#       centered=False -> Evie-KFu   (Sigma = E[gg^T], the UNCENTRED object every
#                                     published Kronecker method uses: K-FAC,
#                                     Shampoo, SOAP)  -- the C1 novelty ablation
#       per_layer_norm -> Evie-KFn   (gains rescaled to unit RMS per layer;
#                                     the WikiText-2 PoC winner, the main-table entrant)
EVIEKF_FIXED_GAMMA_M = 30.0
WD_KNOB_GRID = [1e-5, 3.162e-5, 1e-4, 3.162e-4, 1e-3, 3.162e-3, 1e-2]
EVIEKF_BETAS       = (0.9, 0.999)
EVIEKF_EPS         = 1e-8
EVIEKF_BETA_SIG    = 0.95     # frozen -- noise-covariance EMA
EVIEKF_WARMUP      = 20       # frozen -- operator off for the first WARMUP steps
EVIEKF_REFRESH     = 20       # frozen -- steps between eigendecomposition refreshes
EVIEKF_MAXF        = 1024     # frozen -- a Kronecker factor larger than this uses
                             #           a diagonal approximation (no eigh). On a
                             #           CIFAR-stem ResNet-18 the reshaped conv
                             #           factors are 576/1152/2304/4608, so at this
                             #           limit layers 2-4 -- nearly all the
                             #           parameters -- run half-diagonal. A
                             #           DIAGNOSTIC file may raise it via
                             #           TASK["eviekf_maxf"] (passed in as
                             #           build_optimizer(eviekf_maxf=...)); no
                             #           protocol task does, and the paper must
                             #           state the limit either way.
EVIEKF_GAIN_CLIP   = 5.0      # frozen -- per_layer_norm gain cap
EVIEKF_GAMMA_GRID  = [3.0, 10.0, 30.0, 100.0, 300.0, 1000.0, 3000.0]  # TUNED: the one knob
# Fixed gamma for the Phase-2 sweeps, which re-search LR per grid point but do
# NOT joint-search gamma (that would ~7x the sweep cost). build_optimizer()'s
# own default is 100.0, but kaggle_evie_v3.py's joint search -- the run whose
# numbers go in the paper -- pinned the optimum at the TOP of the grid (3000),
# ~30x higher. The batch-size sweep exists to detect the C1 gap widening at
# small batch; running Evie's arms at a gamma the evidence says is far
# off-optimum risks masking that effect, so the sweeps use 3000, not 100.
# (Top-edge-pinned even at PoC scale -- a real joint search is still the right
# fix if the compute budget allows it; see RUNBOOK sec 5 / sec 7.)
EVIEKF_SWEEP_GAMMA  = 3000.0

# Diagnostic-only gamma grid for the MEAN-NORMALISED Kronecker arm (EvieKFm,
# FUTURE_WORK FW-9). Under `/tau` the spectrum carries the absolute noise energy,
# so the tuned gamma has to absorb it and lands anywhere from 3 to 243,000 across
# the 12 tasks. Under `/mean(mu*lam)` the spectrum has mean eigenvalue 1, so
# gamma is genuinely dimensionless and should sit near O(1). Same 7-point
# half-decade discipline, re-centred -- exactly as LR_GRID_CENTRE differs per
# optimizer family.
EVIEKF_MEANNORM_GAMMA_GRID = [0.1, 0.3, 1.0, 3.0, 10.0, 30.0, 100.0]

# Optimizer registry. EvieKF (centered=True, per_layer_norm=False) fills the
# reserved slot -- it is the variant validated in kaggle_evie_v3.py (10 seeds,
# Holm-corrected: beats AdamW/AdaBelief/Lion/Muon/Shampoo/EvieDiag at p=0.0078,
# ties its own uncentred ablation EvieKFu). EvieKFn (per_layer_norm=True) stays
# defined in this file but is no longer selected anywhere -- it was the headline
# arm of an earlier 5-seed / no-Muon-no-Shampoo run and its per_layer_norm gains
# >1 are a divergence path plain EvieKF does not have.
# The ablation ladder (EvieDiag/EvieKFu/EvieKF) runs only in the generated
# benchmark12/ablation/ files (TASK["opt_set"] == "ablation"). EvieKF is
# therefore BOTH the main table's 8th arm AND one of the 3 ablation arms: the 3
# ablation hosts (wikitext2, cifar10, finance_tech) compute EvieKF twice -- once
# in the main file (5 seeds), once in the ablation file (10 seeds, a superset).
# ~15 extra cells total; a known, accepted redundancy, not de-duplicated here.
#
# ORDER MATTERS, for two reasons, and neither is cosmetic:
#  1. run_sweep() and lr_search() walk this list in order, so a run that is cut
#     short (a Kaggle session that never comes back, a cluster preemption) yields
#     a PREFIX of it. EvieKF used to be last, which meant a partial run produced
#     seven baselines and no Evie -- i.e. nothing. EvieKF and AdamW now come
#     first, so any partial result already contains the comparison the paper is
#     about. Cells are keyed by NAME ("opt|unit|seed"), never by index, so
#     reordering is safe for an in-flight run: nothing already computed is lost
#     or re-run.
#  2. AdamW must precede Muon. Muon's AdamW sub-group is built with
#     lr_used.get("AdamW"), which is None until AdamW's own LR search has
#     finished -- ordering Muon first would silently give that sub-group Muon's
#     LR instead. Asserted below so a future edit cannot reintroduce it.
OPT_NAMES          = ["EvieKF", "AdamW", "AdaBelief", "Muon", "Shampoo",
                      "Sophia", "Lion", "SGD"]
ABLATION_OPT_NAMES = ["EvieKF", "EvieKFu", "EvieDiag"]   # EvieKF's 10-seed cells
                                                         # here are a superset of
                                                         # the main run's 5
assert OPT_NAMES.index("AdamW") < OPT_NAMES.index("Muon"), \
    "AdamW must be searched before Muon (Muon's AdamW sub-group reuses its LR)"
# Scale-generalization secondary tasks (evie-scalegen-spec.md sec 1): trimmed
# 4-arm set, 3 seeds, run via benchmark12/scalegen/ (TASK["opt_set"]=="scalegen").
# Same two ordering rules as OPT_NAMES above: EvieKF/AdamW first (a cut-short
# run's prefix still contains the comparison), AdamW before Muon (its AdamW
# sub-group reuses AdamW's frozen LR). All 4 names already exist in
# build_optimizer() below -- no new optimizer code.
SCALEGEN_OPT_NAMES = ["EvieKF", "AdamW", "AdaBelief", "Muon"]
assert SCALEGEN_OPT_NAMES.index("AdamW") < SCALEGEN_OPT_NAMES.index("Muon"), \
    "AdamW must be searched before Muon (Muon's AdamW sub-group reuses its LR)"
HESSIAN_CONSUMERS = {"Sophia"}     # optimizers that need the Hutchinson probe
NOISE_CONSUMERS   = {"EvieKFmwd", "EvieKFmrb", "EvieKFlag", "EvieKFrb", "MuonEvie", "MuonEvieFix", "EvieDiag", "EvieKFu", "EvieKF", "EvieKFn",
                     "EvieDiagAbs", "EvieKFm", "EvieKFr"}       # need the
                                  # split-batch noise hook (engine calls set_noise())

# Optimizers with a SECOND tuned axis, searched JOINTLY with the LR grid (same
# 7-point discipline, same boundary-extend rule -- optimizer specification sec 4.3.2).
# Anything not listed here is LR-search only, exactly as before.
KNOB_GRID = {
    **{n: list(WD_KNOB_GRID) for n in ("AdamWwd", "AdaBeliefwd", "SGDwd", "Lionwd", "Muonwd")},
    "EvieKFlag": list(EVIEKF_GAMMA_GRID), "EvieKFrb": list(EVIEKF_GAMMA_GRID),
    "EvieKFn": list(EVIEKF_GAMMA_GRID), "EvieKF": list(EVIEKF_GAMMA_GRID),
    "EvieKFu": list(EVIEKF_GAMMA_GRID), "EvieDiag": list(EVIEKF_GAMMA_GRID),
    "Shampoo": list(SHAMPOO_KNOB_GRID),
    # diagnostic arms (DERIVATION.md sec 5.1 / sec 11, FW-9 and FW-11)
    "EvieDiagAbs": list(EVIEKF_GAMMA_GRID),      # same grid as EvieDiag, absolute gate
    "EvieKFr": list(EVIEKF_GAMMA_GRID),          # same as EvieKF, rescale disabled
    "EvieKFm": list(EVIEKF_MEANNORM_GAMMA_GRID), # re-centred: gamma is dimensionless here
    "EvieKFmrb": list(EVIEKF_MEANNORM_GAMMA_GRID), # EvieKFm with the random-basis control (pinned runs only)
}

# Per-optimizer-family LR grid centre. Every optimizer gets the SAME NUMBER of
# grid points (7, half-decade spacing); only the centre differs by family
# because effective LR scale is not comparable across families (benchmark protocol sec 5).
LR_GRID_CENTRE = {
    "AdamWwd": 1e-3, "AdaBeliefwd": 1e-3, "SGDwd": 3e-2,
    "Lionwd": 1e-4, "Muonwd": 2e-2, "EvieKFmwd": 1e-3,
    "EvieKFlag": 1e-3, "EvieKFrb": 1e-3, "EvieKFmrb": 1e-3,
    "MuonSub": 1e-3, "MuonEvie": 1e-3, "MuonEvieFix": 1e-3,
    "AdamW":     1e-3,
    "AdaBelief": 1e-3,
    "SGD":       3e-2,
    "Sophia":    1e-3,
    "Muon":      2e-2,
    "Lion":      1e-4,
    "Shampoo":   1e-3,          # AdamW-grafted -> Adam-family centring
    "EvieKFn":   1e-3,          # Evie-KF family: P^-1/2 is AdamW's own denominator,
    "EvieKF":    1e-3,          # so the effective LR scale matches the Adam family
    "EvieKFu":   1e-3,
    "EvieDiag":  1e-3,
    "EvieDiagAbs": 1e-3,        # diagnostic arms, same family centring
    "EvieKFm":   1e-3,
    "EvieKFr":   1e-3,
}


def half_decade_grid(centre, n_below=3, n_above=3):
    """7-point half-decade (sqrt(10)~=3.162x) grid centred on `centre`.
    Returns a sorted list of length n_below + 1 + n_above."""
    r = 10.0 ** 0.5
    pts = [centre * (r ** k) for k in range(-n_below, n_above + 1)]
    return [float(f"{p:.4g}") for p in pts]


def knob_grid_extend(grid, at_low):
    """Boundary-extend rule (benchmark protocol sec 5) applied to a second-axis knob grid.
    Returns up to 2 new points past the edge the search pinned to. gamma-style
    grids (all values >= 1) extend multiplicatively by 3x; a beta-style grid
    bounded in (0, 1) densifies toward the bound instead."""
    g = sorted(float(x) for x in grid)
    if g and all(0.0 < x < 1.0 for x in g):
        if at_low:
            lo, d = g[0], (g[1] - g[0] if len(g) > 1 else g[0] * 0.5)
            return [round(lo - k * d, 6) for k in (1, 2) if lo - k * d > 0.0]
        hi = g[-1]
        return [round(1.0 - (1.0 - hi) / f, 6) for f in (3.0, 10.0)
                if 0.0 < 1.0 - (1.0 - hi) / f < 1.0]
    if at_low:
        return [float(f"{g[0] / f:.4g}") for f in (3.0, 9.0)]
    return [float(f"{g[-1] * f:.4g}") for f in (3.0, 9.0)]


# ---------------------------------------------------------------------------
#  AdaBelief -- Adam with the second moment tracking (g - m)^2 ("belief" in
#  the gradient direction) instead of g^2. Decoupled weight decay, bias
#  correction, no RAdam-style rectification (plain decoupled AdaBelief).
# ---------------------------------------------------------------------------
class AdaBelief(torch.optim.Optimizer):
    def __init__(self, params, lr=1e-3, betas=ADABELIEF_BETAS, eps=ADABELIEF_EPS,
                 weight_decay=0.0):
        if lr <= 0.0:
            raise ValueError(f"AdaBelief: invalid lr {lr}")
        defaults = dict(lr=lr, beta1=betas[0], beta2=betas[1], eps=eps,
                        weight_decay=weight_decay)
        super().__init__(params, defaults)

    @torch.no_grad()
    def step(self, closure=None):
        loss = None
        if closure is not None:
            with torch.enable_grad():
                loss = closure()
        for group in self.param_groups:
            lr, b1, b2 = group["lr"], group["beta1"], group["beta2"]
            eps, wd = group["eps"], group["weight_decay"]
            for p in group["params"]:
                if p.grad is None:
                    continue
                g = p.grad
                if g.is_sparse:
                    raise RuntimeError("AdaBelief does not support sparse gradients")
                if wd != 0.0:
                    p.mul_(1.0 - lr * wd)                       # decoupled WD
                st = self.state[p]
                if len(st) == 0:
                    st["step"] = 0
                    st["m"] = torch.zeros_like(p)
                    st["s"] = torch.zeros_like(p)               # EMA of (g - m)^2
                st["step"] += 1
                t = st["step"]
                m, s = st["m"], st["s"]
                m.mul_(b1).add_(g, alpha=1.0 - b1)
                diff = g - m
                s.mul_(b2).addcmul_(diff, diff, value=1.0 - b2)
                s.add_(eps)
                m_hat = m / (1.0 - b1 ** t)
                s_hat = s / (1.0 - b2 ** t)
                p.addcdiv_(m_hat, s_hat.sqrt().add_(eps), value=-lr)
        return loss


# ---------------------------------------------------------------------------
#  SGDM -- SGD + heavy-ball momentum + Nesterov, with DECOUPLED weight decay
#  (torch.optim.SGD only offers coupled L2, hence this thin re-implementation
#  so the WD convention matches every other optimizer in the harness).
#  Cosine LR schedule is applied by the engine, same as for all optimizers.
# ---------------------------------------------------------------------------
class SGDM(torch.optim.Optimizer):
    def __init__(self, params, lr=3e-2, momentum=SGDM_MOMENTUM,
                 nesterov=SGDM_NESTEROV, weight_decay=0.0):
        if lr <= 0.0:
            raise ValueError(f"SGDM: invalid lr {lr}")
        defaults = dict(lr=lr, momentum=momentum, nesterov=nesterov,
                        weight_decay=weight_decay)
        super().__init__(params, defaults)

    @torch.no_grad()
    def step(self, closure=None):
        loss = None
        if closure is not None:
            with torch.enable_grad():
                loss = closure()
        for group in self.param_groups:
            lr, mom = group["lr"], group["momentum"]
            nesterov, wd = group["nesterov"], group["weight_decay"]
            for p in group["params"]:
                if p.grad is None:
                    continue
                g = p.grad
                if wd != 0.0:
                    p.mul_(1.0 - lr * wd)                       # decoupled WD
                st = self.state[p]
                if len(st) == 0:
                    st["buf"] = torch.zeros_like(p)
                buf = st["buf"]
                buf.mul_(mom).add_(g)
                d = g.add(buf, alpha=mom) if nesterov else buf
                p.add_(d, alpha=-lr)
        return loss


# ---------------------------------------------------------------------------
#  Sophia (SophiaH) -- clipped Newton-style update with a Hutchinson diagonal
#  Hessian EMA. Hyperparameters frozen per benchmark protocol sec 4:
#  beta1=0.965, beta2(Hessian EMA)=0.99, rho=0.04, eps=1e-8, HESS_FREQ=5,
#  N_HUTCH=4. The engine calls set_hessian() every HESS_FREQ steps with the
#  Hutchinson estimate from hutchinson_diag_hessian().
# ---------------------------------------------------------------------------
class Sophia(torch.optim.Optimizer):
    def __init__(self, params, lr=1e-3, betas=SOPHIA_BETAS, rho=SOPHIA_RHO,
                 eps=SOPHIA_EPS, weight_decay=0.0):
        if lr <= 0.0:
            raise ValueError(f"Sophia: invalid lr {lr}")
        defaults = dict(lr=lr, beta1=betas[0], beta2=betas[1], rho=rho, eps=eps,
                        weight_decay=weight_decay)
        super().__init__(params, defaults)
        self.last_h_norm = float("nan")

    @torch.no_grad()
    def set_hessian(self, param_h_pairs, beta_h=SOPHIA_BETA_H):
        sq = 0.0
        for p, h in param_h_pairs:
            st = self.state[p]
            h_new = h.detach().abs()
            if "h_hat" not in st:
                st["h_hat"] = h_new.clone()
            else:
                st["h_hat"].mul_(beta_h).add_(h_new, alpha=1.0 - beta_h)
            sq += float(h_new.pow(2).sum().item())
        self.last_h_norm = math.sqrt(sq)

    @torch.no_grad()
    def step(self, closure=None):
        loss = None
        if closure is not None:
            with torch.enable_grad():
                loss = closure()
        for group in self.param_groups:
            lr, b1 = group["lr"], group["beta1"]
            rho, eps, wd = group["rho"], group["eps"], group["weight_decay"]
            for p in group["params"]:
                if p.grad is None:
                    continue
                g = p.grad
                if wd != 0.0:
                    p.mul_(1.0 - lr * wd)                       # decoupled WD
                st = self.state[p]
                if "step" not in st:
                    st["step"] = 0
                    st["m"] = torch.zeros_like(p)
                if "h_hat" not in st:
                    st["h_hat"] = torch.ones_like(p)
                st["step"] += 1
                t = st["step"]
                m = st["m"]
                m.mul_(b1).add_(g, alpha=1.0 - b1)
                m_hat = m / (1.0 - b1 ** t)
                h = st["h_hat"].clamp(min=eps)
                update = (m_hat / (rho * h)).clamp_(-1.0, 1.0)
                p.add_(update, alpha=-lr)
        return loss


def _spatial_avg(h):
    """Per-row average for 2D, scalar average for 1D, spatial average for 4D
    (kept for parity with the historical Hutchinson pipeline)."""
    if h.dim() == 4:
        return h.mean(dim=[2, 3], keepdim=True).expand_as(h).clone()
    if h.dim() == 2:
        return h.mean(dim=1, keepdim=True).expand_as(h).clone()
    if h.dim() == 1:
        return h.mean().expand_as(h).clone()
    return h.clone()


def hutchinson_diag_hessian(model, params, compute_loss, n_hutch=N_HUTCH,
                            optimizer=None, feed_optimizer=False):
    """Hutchinson diagonal-Hessian estimator: for each of n_hutch Rademacher
    vectors v, form v (x) Hv via a double backward and accumulate; divide by
    n_hutch, take abs. Feeds Sophia via set_hessian() when feed_optimizer=True.
    `compute_loss` is a zero-arg closure that returns the (scalar) training loss
    for the current batch -- the engine passes the domain's forward_loss so the
    probe matches the real loss (e.g. the (B,T,V) reshape for language).
    Returns the list of per-parameter diagonal estimates."""
    with torch.enable_grad():
        loss_h = compute_loss()
    grads = torch.autograd.grad(loss_h, params, create_graph=True,
                                retain_graph=True, allow_unused=True)
    h_acc = [torch.zeros_like(p) for p in params]
    for k in range(n_hutch):
        vs = [(torch.randint(0, 2, p.shape, device=p.device, dtype=torch.float32)
               * 2.0 - 1.0).to(p.dtype) for p in params]
        gv = sum((g * v).sum() for g, v in zip(grads, vs) if g is not None)
        retain = (k < n_hutch - 1)
        hvps = torch.autograd.grad(gv, params, retain_graph=retain, allow_unused=True)
        for i, (v, hv) in enumerate(zip(vs, hvps)):
            if hv is not None:
                h_acc[i].add_(v * hv.detach())
        del vs, gv, hvps
    del grads
    for h in h_acc:
        h.div_(n_hutch).abs_()
    if feed_optimizer and optimizer is not None:
        optimizer.set_hessian(list(zip(params, h_acc)), beta_h=SOPHIA_BETA_H)
    return h_acc


# ---------------------------------------------------------------------------
#  Lion (EvoLved Sign Momentum) -- update = sign(b1*m + (1-b1)*g); the EMA is
#  then refreshed with b2. Decoupled weight decay. LR runs ~10x below Adam's,
#  hence the separate grid centre (LR_GRID_CENTRE["Lion"]).
# ---------------------------------------------------------------------------
class Lion(torch.optim.Optimizer):
    def __init__(self, params, lr=1e-4, betas=LION_BETAS, weight_decay=0.0):
        if lr <= 0.0:
            raise ValueError(f"Lion: invalid lr {lr}")
        defaults = dict(lr=lr, beta1=betas[0], beta2=betas[1],
                        weight_decay=weight_decay)
        super().__init__(params, defaults)

    @torch.no_grad()
    def step(self, closure=None):
        loss = None
        if closure is not None:
            with torch.enable_grad():
                loss = closure()
        for group in self.param_groups:
            lr, b1, b2, wd = (group["lr"], group["beta1"], group["beta2"],
                              group["weight_decay"])
            for p in group["params"]:
                if p.grad is None:
                    continue
                g = p.grad
                if wd != 0.0:
                    p.mul_(1.0 - lr * wd)                       # decoupled WD
                st = self.state[p]
                if len(st) == 0:
                    st["m"] = torch.zeros_like(p)
                m = st["m"]
                update = m.mul(b1).add_(g, alpha=1.0 - b1).sign_()
                p.add_(update, alpha=-lr)
                m.mul_(b2).add_(g, alpha=1.0 - b2)
        return loss


# ---------------------------------------------------------------------------
#  Muon (MomentUm Orthogonalized by Newton-schulz) -- hybrid optimizer.
#  Params with ndim >= 2 that are NOT flagged as embedding/head (see
#  split_params_for_muon) get the Muon update: heavy-ball (Nesterov) momentum
#  followed by Newton-Schulz orthogonalization of the (reshaped-to-2D) update,
#  scaled by MUON_UPDATE_SCALE * sqrt(max(fan_out, fan_in)). Every other param
#  (biases, norm params, all 1D params, token embeddings, LM head) gets a
#  standard decoupled-WD AdamW update. Both sub-groups are carried in ONE
#  Optimizer so checkpoint/resume and the cosine LR scheduler work unchanged.
#
#  Per the frozen decision (benchmark protocol sec 8.2 + user): the 7-point LR search
#  tunes ONLY the Muon (2D) sub-group's LR; the AdamW sub-group's LR is fixed
#  to this file's separately-frozen AdamW LR (passed as adamw_lr to
#  build_optimizer). Conv weights (4D) are reshaped (O, I*kH*kW) and DO go to
#  the Muon side -- the strict "2D only" reading would leave Muon == AdamW on
#  the entire vision domain, which is not a meaningful baseline. This split is
#  written once here and pasted identically into all 12 files.
# ---------------------------------------------------------------------------
def _zeropower_via_newtonschulz5(G, steps=MUON_NS_STEPS, coeffs=MUON_NS_COEFFS,
                                 eps=1e-7):
    """Quintic Newton-Schulz iteration -> approximate orthogonalization of G
    (2D). Operates in float32. Returns a matrix with the same shape as G whose
    singular values are pushed toward 1."""
    assert G.ndim == 2, "Newton-Schulz expects a 2D matrix"
    a, b, c = coeffs
    X = G.float()
    X = X / (X.norm() + eps)
    transpose = X.size(0) > X.size(1)
    if transpose:
        X = X.T
    for _ in range(steps):
        A = X @ X.T
        B = b * A + c * (A @ A)
        X = a * X + B @ X
    if transpose:
        X = X.T
    return X.to(G.dtype)


@torch.no_grad()
def _muon_matrix_step(opt, group):
    """Exact shared matrix update used by Muon and MuonEvie."""
    lr, wd = group["lr"], group["weight_decay"]
    mom, nesterov, ns_steps = (group["momentum"], group["nesterov"],
                               group["ns_steps"])
    for p in group["params"]:
        if p.grad is None:
            continue
        g = p.grad
        if g.ndim > 2:
            g = g.reshape(g.size(0), -1)
        st = opt.state[p]
        if len(st) == 0:
            st["buf"] = torch.zeros_like(g)
        buf = st["buf"]
        buf.mul_(mom).add_(g)
        d = g.add(buf, alpha=mom) if nesterov else buf
        o = _zeropower_via_newtonschulz5(d, steps=ns_steps)
        fan_out, fan_in = o.size(0), o.size(1)
        scale = MUON_UPDATE_SCALE * math.sqrt(max(fan_out, fan_in))
        if wd != 0.0:
            p.mul_(1.0 - lr * wd)                   # decoupled WD
        p.add_(o.reshape(p.shape), alpha=-lr * scale)


class Muon(torch.optim.Optimizer):
    def __init__(self, param_groups):
        # Each incoming group must set: params, lr, use_muon (bool).
        defaults = dict(
            lr=2e-2, use_muon=True,
            momentum=MUON_MOMENTUM, nesterov=MUON_NESTEROV, ns_steps=MUON_NS_STEPS,
            betas=MUON_ADAMW_BETAS, eps=MUON_ADAMW_EPS, weight_decay=WEIGHT_DECAY,
        )
        super().__init__(param_groups, defaults)

    @torch.no_grad()
    def step(self, closure=None):
        loss = None
        if closure is not None:
            with torch.enable_grad():
                loss = closure()
        for group in self.param_groups:
            lr, wd = group["lr"], group["weight_decay"]
            if group["use_muon"]:
                _muon_matrix_step(self, group)
            else:
                b1, b2 = group["betas"]
                eps = group["eps"]
                for p in group["params"]:
                    if p.grad is None:
                        continue
                    g = p.grad
                    if wd != 0.0:
                        p.mul_(1.0 - lr * wd)                   # decoupled WD
                    st = self.state[p]
                    if len(st) == 0:
                        st["step"] = 0
                        st["m"] = torch.zeros_like(p)
                        st["v"] = torch.zeros_like(p)
                    st["step"] += 1
                    t = st["step"]
                    m, v = st["m"], st["v"]
                    m.mul_(b1).add_(g, alpha=1.0 - b1)
                    v.mul_(b2).addcmul_(g, g, value=1.0 - b2)
                    m_hat = m / (1.0 - b1 ** t)
                    v_hat = v / (1.0 - b2 ** t)
                    p.addcdiv_(m_hat, v_hat.sqrt().add_(eps), value=-lr)
        return loss


def split_params_for_muon(model):
    """Returns (muon_params, adamw_params). A parameter goes to the Muon side
    iff it has ndim >= 2 AND its qualified name does not match any entry in
    model._muon_exclude_names (set by the data fragment for token embeddings /
    positional embeddings / LM head). Everything else -> AdamW side."""
    exclude = set(getattr(model, "_muon_exclude_names", []))

    def excluded(name):
        return any(name == e or name.startswith(e + ".") or name.endswith("." + e)
                   or ("." + e + ".") in ("." + name + ".") for e in exclude)

    muon_params, adamw_params = [], []
    for name, p in model.named_parameters():
        if not p.requires_grad:
            continue
        if p.ndim >= 2 and not excluded(name):
            muon_params.append(p)
        else:
            adamw_params.append(p)
    return muon_params, adamw_params


# ---------------------------------------------------------------------------
#  Shampoo -- per-layer L^{-1/4} G R^{-1/4} preconditioner with AdamW norm
#  grafting. L = EMA(G G^T), R = EMA(G^T G). Grafting the AdamW update norm
#  keeps it stable at this scale (ungrafted Shampoo is not). 1-D params
#  (biases, norms) and 2-D params with a dimension > SHAMPOO_MAXF fall through
#  to the AdamW graft alone -- the latter guard is NOT in the Kaggle reference
#  and is added here on purpose: without it a tied 16k-vocab lm_head would
#  allocate a 16000x16000 preconditioner and eigh it. Decoupled weight decay,
#  same as every optimizer in this block. `beta` is the second tuned axis
#  (KNOB_GRID["Shampoo"]); `lr` is the LR-searched value.
# ---------------------------------------------------------------------------
class Shampoo(torch.optim.Optimizer):
    def __init__(self, params, lr=1e-3, beta=SHAMPOO_BETA, eps=SHAMPOO_EPS,
                 update_freq=SHAMPOO_UPDATE_FREQ, graft_betas=SHAMPOO_GRAFT_BETAS,
                 maxf=SHAMPOO_MAXF, weight_decay=0.0):
        if lr <= 0.0:
            raise ValueError(f"Shampoo: invalid lr {lr}")
        if not 0.0 < beta < 1.0:
            raise ValueError(f"Shampoo: invalid beta {beta}")
        defaults = dict(lr=lr, beta=beta, eps=eps, update_freq=int(update_freq),
                        graft_betas=graft_betas, maxf=int(maxf),
                        weight_decay=weight_decay)
        super().__init__(params, defaults)

    @staticmethod
    def _inv_root(M, eps, power=-0.25):
        L, Q = torch.linalg.eigh(M.double())
        L = L.clamp_min(eps)
        return (Q @ torch.diag(L.pow(power)) @ Q.T).to(M.dtype)

    @torch.no_grad()
    def step(self, closure=None):
        loss = None
        if closure is not None:
            with torch.enable_grad():
                loss = closure()
        for group in self.param_groups:
            b1, b2 = group["graft_betas"]
            lr, wd, maxf = group["lr"], group["weight_decay"], group["maxf"]
            for p in group["params"]:
                if p.grad is None:
                    continue
                g = p.grad
                if g.is_sparse:
                    raise RuntimeError("Shampoo does not support sparse gradients")
                st = self.state[p]
                if "t" not in st:
                    st["t"] = 0
                    st["m"] = torch.zeros_like(p)
                    st["v"] = torch.zeros_like(p)
                    if g.ndim == 2 and max(g.shape) <= maxf:
                        st["L"] = torch.zeros(g.size(0), g.size(0), device=g.device)
                        st["R"] = torch.zeros(g.size(1), g.size(1), device=g.device)
                st["t"] += 1
                t = st["t"]
                if wd != 0.0:
                    p.mul_(1.0 - lr * wd)                       # decoupled WD
                st["m"].mul_(b1).add_(g, alpha=1.0 - b1)
                st["v"].mul_(b2).addcmul_(g, g, value=1.0 - b2)
                adam_dir = (st["m"] / (1.0 - b1 ** t)) / (
                    (st["v"] / (1.0 - b2 ** t)).sqrt().add(1e-8))
                if "L" not in st:                              # 1-D or oversized 2-D
                    p.add_(adam_dir, alpha=-lr)
                    continue
                st["L"].mul_(group["beta"]).add_(g @ g.T, alpha=1.0 - group["beta"])
                st["R"].mul_(group["beta"]).add_(g.T @ g, alpha=1.0 - group["beta"])
                if t % group["update_freq"] == 0 or "Li" not in st:
                    st["Li"] = self._inv_root(st["L"], group["eps"])
                    st["Ri"] = self._inv_root(st["R"], group["eps"])
                d = st["Li"] @ g @ st["Ri"]
                d = d * (adam_dir.norm() / (d.norm() + 1e-12))  # graft the norm
                p.add_(d, alpha=-lr)
        return loss


# ---------------------------------------------------------------------------
#  Evie-KF -- Kronecker-factored risk-sensitive preconditioner.
#
#      dtheta = -lr * P^-1/2 (I + gamma Sigma_z)^-1/2 P^-1/2 m1hat
#      P      = diag(sqrt(m2hat))                 (AdamW's own curvature proxy)
#      Sigma_z = P^-1/2 Sigma P^-1/2              (noise covariance, whitened)
#      Sigma  = Cov(g) from the split batch: delta = (gA - gB)/2, g = (gA + gB)/2
#      Sigma_z ~= (B kron A)/tr(A) per weight matrix; gain_ij = (1 + gamma mu_i lam_j/tr)^-1/2
#      Z = U_B [ (U_B^T Y U_A) * gain ] U_A^T     (exact; self-checked against the dense form)
#
#  This is a per-parameter (self.state[p]) port of the validated flat-vector
#  reference in "the reference optimizer". The port is required so the
#  optimizer state survives state_dict()/resume like every other optimizer in
#  this harness. Two structural points the port gets right (optimizer specification 4.1):
#    1. step() cannot compute the split-batch noise itself -- the engine runs the
#       two half-batch backward passes and hands the result in via set_noise(),
#       exactly mirroring Sophia's set_hessian() pattern. p.grad is (gA+gB)/2.
#    2. Algorithm step 8 (z <- z * ||y||/||z||) is a norm across ALL parameters,
#       not per-layer: two passes over the param groups per step() -- accumulate
#       ||y||^2, ||z||^2 globally, then rescale. This keeps Evie-KF's step SIZE
#       identical to AdamW's and isolates the direction change (spec sec 1).
#
#  Flags: gamma=0 -> AdamW exactly; diag_only -> Evie-diag; centered=False ->
#  Evie-KFu; per_layer_norm -> Evie-KFn. Decoupled weight decay, same convention
#  as the rest of the block.
# ---------------------------------------------------------------------------
class EvieKF(torch.optim.Optimizer):
    def __init__(self, params, lr=1e-3, betas=EVIEKF_BETAS, eps=EVIEKF_EPS,
                 weight_decay=0.0, gamma=100.0, beta_sig=EVIEKF_BETA_SIG,
                 warmup=EVIEKF_WARMUP, refresh=EVIEKF_REFRESH, maxf=EVIEKF_MAXF,
                 diag_only=False, centered=True, per_layer_norm=False,
                 gain_clip=EVIEKF_GAIN_CLIP,
                 diag_relative=True, kron_mean_norm=False, norm_preserve=True,
                 lagged=False, random_basis=False, telemetry_extra=False):
        if lr <= 0.0 or gamma < 0.0 or not 0.0 < beta_sig < 1.0:
            raise ValueError("EvieKF: invalid hyperparameters")
        defaults = dict(lr=lr, beta1=betas[0], beta2=betas[1], eps=eps,
                        weight_decay=weight_decay)
        super().__init__(params, defaults)
        self.gamma, self.beta_sig = float(gamma), float(beta_sig)
        self.warmup, self.refresh, self.maxf = int(warmup), int(refresh), int(maxf)
        self.diag_only, self.centered = bool(diag_only), bool(centered)
        self.per_layer_norm, self.gain_clip = bool(per_layer_norm), float(gain_clip)
        # --- three diagnostic switches. Every default reproduces the shipped
        # behaviour EXACTLY, so no protocol run is affected by their existence.
        #   diag_relative   False -> the diagonal gate is (1 + gamma*s)^-1/2, the
        #                   derivation's own diagonal special case, instead of the
        #                   mean-normalised (1 + gamma*s/mean(s))^-1/2. Needed to
        #                   deconfound C2 (DERIVATION.md sec 5.1, FW-11).
        #   kron_mean_norm  True -> normalise the Kronecker spectrum by its MEAN
        #                   eigenvalue instead of tr(A), which is the only form in
        #                   which gamma is actually dimensionless (FW-9).
        #   norm_preserve   False -> skip the global ||y||/||z|| rescale, so the
        #                   operator shrinks instead of rotating. Tests whether
        #                   norm preservation is load-bearing (FW-10).
        self.lagged, self.random_basis = bool(lagged), bool(random_basis)
        self.telemetry_extra = bool(telemetry_extra)
        self._param_indices = {id(p): i for i, p in enumerate(
            p for group in self.param_groups for p in group["params"])}
        self._extra = dict(c_sum=0., c_n=0, c_min=float("inf"), eig_s=0.)
        if self.telemetry_extra:
            _counts=[0,0,0]
            for _group in self.param_groups:
                if _group.get("use_muon",False):continue
                for _p in _group["params"]:
                    _branch=2 if _p.ndim<2 or diag_only else (0 if _p.size(0)<=self.maxf and _p.numel()//_p.size(0)<=self.maxf else 1)
                    _counts[_branch]+=_p.numel()
            for _key,_value in zip(("frac_params_kron","frac_params_diag_fallback","frac_params_vector"),_counts):
                setattr(self,_key,_value/max(1,sum(_counts)))
        self.diag_relative = bool(diag_relative)
        self.kron_mean_norm = bool(kron_mean_norm)
        self.norm_preserve = bool(norm_preserve)
        self._roles = {}                # {param: role_str}; set by set_param_roles()
        # descriptive diagnostics, refreshed every step(), read by the engine
        # (optimizer specification sec 4.3.4/4.3.5). NEVER significance-tested.
        self.last_cos = 1.0
        self.b_simple = 0.0
        self.tr_sigma = 0.0
        self.eff_rank = 0.0
        self.gain_lo, self.gain_hi = 1.0, 1.0
        self.n_active_steps = 0        # wiring canary: 0 at end of run => set_noise()
                                      # was never called and this WAS silently AdamW
        self.role_gain = {}           # role -> [gain_lo, gain_hi, eff_rank_sum, n]

    def state_dict(self):
        value = super().state_dict()
        if self.telemetry_extra:
            value["extra_telemetry"] = dict(self._extra)
        return value

    def load_state_dict(self, value):
        value = dict(value)
        extra = value.pop("extra_telemetry", None)
        super().load_state_dict(value)
        if extra is not None:
            self._extra = dict(extra)

    def set_param_roles(self, param_roles):
        """{param: role} with role in {embedding, attention, ffn, head, other};
        enables the per-module-category gain/effective-rank breakdown (figures
        F4/F5). Optional -- without it role_gain stays empty."""
        self._roles = dict(param_roles)

    @staticmethod
    def _eigh(M):
        Ms = (M + M.transpose(-1, -2)) * 0.5
        L, W = torch.linalg.eigh(Ms.double())          # fp64 eigh regardless of
        return L.clamp_min(0).to(M.dtype), W.to(M.dtype)   # param dtype, then cast back

    @torch.no_grad()
    def set_noise(self, param_delta_pairs):
        """Called by the engine once per step BEFORE step(), with
        param_delta_pairs = [(p, (gradA - gradB)/2), ...] and p.grad already set
        to (gradA + gradB)/2. Mirrors Sophia.set_hessian()."""
        for p, delta in param_delta_pairs:
            self.state[p]["_delta"] = delta.detach()

    def _global_step(self):
        """The global step index, derived from the per-parameter counters so it
        survives load_state_dict() (self.__dict__ is not checkpointed). Equals a
        plain monotone counter as long as every param is stepped together."""
        s = 0
        for group in self.param_groups:
            for p in group["params"]:
                st = self.state.get(p)
                if st and "step" in st:
                    s = max(s, int(st["step"]))
        return s + 1

    @torch.no_grad()
    def step(self, closure=None):
        loss = None
        if closure is not None:
            with torch.enable_grad():
                loss = closure()
        t = self._global_step()
        active_gate = (t > self.warmup) and (self.gamma > 0.0)

        cache = []                       # (p, group, y, z, pm12) for pass 2
        y_sq_total = z_sq_total = dot_total = 0.0
        tr_sigma_total = y_sq_for_bsimple = 0.0
        gains_lo, gains_hi, eff_ranks = [], [], []
        any_noise = False
        self.role_gain = {}

        if self.telemetry_extra:
            _tele = {}
        # ---- pass 1: per-parameter y (whitened Adam dir) and z (preconditioned) --
        for group in self.param_groups:
            if group.get("use_muon", False):
                continue
            b1, b2, eps = group["beta1"], group["beta2"], group["eps"]
            for p in group["params"]:
                if p.grad is None:
                    continue
                g = p.grad
                st = self.state[p]
                if "step" not in st:
                    st["step"] = 0
                    st["m"] = torch.zeros_like(p)
                    st["v"] = torch.zeros_like(p)
                st["step"] += 1
                pt = st["step"]
                st["m"].mul_(b1).add_(g, alpha=1.0 - b1)
                st["v"].mul_(b2).addcmul_(g, g, value=1.0 - b2)
                mh = st["m"] / (1.0 - b1 ** pt)
                vh = st["v"] / (1.0 - b2 ** pt)
                pm12 = vh.sqrt().add(eps).rsqrt()          # == torch AdamW's P^-1/2
                y = pm12 * mh
                z = y.clone()

                delta = st.pop("_delta", None)             # consume; never stale-reuse
                if delta is not None:
                    any_noise = True
                    src = delta if self.centered else g
                    dz = pm12 * src.detach().float()
                    tr_sigma_total += float((dz * dz).sum())
                    y_sq_for_bsimple += float((y * y).sum())

                    if p.dim() < 2 or self.diag_only:
                        if "s" not in st:
                            st["s"] = torch.zeros_like(dz)
                        if self.lagged:
                            _old_s = st["s"].clone()
                        st["s"].mul_(self.beta_sig).addcmul_(
                            dz, dz, value=1.0 - self.beta_sig)
                        if active_gate:
                            s = st["s"] / (1.0 - self.beta_sig ** pt)
                            if self.lagged:
                                s = _old_s / (1.0 - self.beta_sig ** (pt-1))
                            gsc = (1.0 + self.gamma
                                   * (s / (s.mean() + 1e-30)
                                      if self.diag_relative else s)).rsqrt()
                            if self.per_layer_norm:
                                gsc = (gsc / gsc.pow(2).mean().sqrt()
                                       .clamp_min(1e-30)).clamp(max=self.gain_clip)
                            z = y * gsc
                    else:
                        d0 = p.size(0)
                        rest = p.numel() // d0
                        D = dz.reshape(d0, rest)
                        if "A" not in st:
                            st["A"] = (torch.zeros(rest, rest, device=p.device)
                                       if rest <= self.maxf
                                       else torch.zeros(rest, device=p.device))
                            st["B"] = (torch.zeros(d0, d0, device=p.device)
                                       if d0 <= self.maxf
                                       else torch.zeros(d0, device=p.device))
                        if self.lagged:
                            _old_A, _old_B = st["A"].clone(), st["B"].clone()
                        st["A"].mul_(self.beta_sig).add_(
                            (D.T @ D) if rest <= self.maxf else (D * D).sum(0),
                            alpha=1.0 - self.beta_sig)
                        st["B"].mul_(self.beta_sig).add_(
                            (D @ D.T) if d0 <= self.maxf else (D * D).sum(1),
                            alpha=1.0 - self.beta_sig)
                        if active_gate:
                            if (pt % self.refresh == 0) or ("lam" not in st):
                                A = st["A"] / (1.0 - self.beta_sig ** pt)
                                B = st["B"] / (1.0 - self.beta_sig ** pt)
                                if self.lagged:
                                    A = _old_A / (1.0 - self.beta_sig ** (pt-1))
                                    B = _old_B / (1.0 - self.beta_sig ** (pt-1))
                                if self.telemetry_extra:
                                    if p.is_cuda:
                                        torch.cuda.synchronize()
                                    import time as _time
                                    _eig_start = _time.perf_counter()
                                st["lam"], st["UA"] = (
                                    self._eigh(A) if A.dim() == 2
                                    else (A.clamp_min(0), None))
                                st["mu"], st["UB"] = (
                                    self._eigh(B) if B.dim() == 2
                                    else (B.clamp_min(0), None))
                                if self.telemetry_extra:
                                    if p.is_cuda:
                                        torch.cuda.synchronize()
                                    self._extra["eig_s"] += _time.perf_counter() - _eig_start
                                    for _side, _F, _ev in [("A", A, st["lam"]), ("B", B, st["mu"])]:
                                        _den = float(_F.square().sum())
                                        _off = (max(0., _den-float(_F.diagonal().square().sum()))/_den
                                                if _F.ndim == 2 and _den > 0 else 0.)
                                        _tele.setdefault("offdiag_frac_"+_side,[]).append(_off)
                                        _tele.setdefault("anisotropy_"+_side,[]).append(float(_ev.max()/(_ev.mean()+1e-30)))
                                if self.random_basis:
                                    # Kronecker-only control: vector gates and diagonal
                                    # fallback sides retain their original directions.
                                    for _side, _cache, _number in [("UA", "RA", 0), ("UB", "RB", 1)]:
                                        if st[_side] is not None:
                                            if _cache not in st:
                                                _gen = torch.Generator(device="cpu").manual_seed(
                                                    1000003*self._param_indices[id(p)]+_number)
                                                _n = st[_side].size(0)
                                                _Q, _R = torch.linalg.qr(torch.randn(_n, _n, generator=_gen, dtype=torch.float32))
                                                st[_cache] = (_Q*torch.sign(torch.diagonal(_R))).to(p)
                                            st[_side] = st[_cache]
                                _tr_a = float(st["lam"].sum())
                                # /tau matches tr(B kron A) to tr(Sigma_z); it is
                                # NOT scale-free. /mean(mu*lam) is (FW-9).
                                st["tr"] = ((_tr_a * float(st["mu"].sum())
                                             / max(1, p.numel()))
                                            if self.kron_mean_norm
                                            else _tr_a) + 1e-30
                            lam, mu = st["lam"], st["mu"]
                            UA, UB, tr = st["UA"], st["UB"], st["tr"]
                            C = y.reshape(d0, rest)
                            if UB is not None:
                                C = UB.T @ C
                            if UA is not None:
                                C = C @ UA
                            gain = (1.0 + self.gamma
                                    * (mu[:, None] * lam[None, :]) / tr).rsqrt()
                            if self.per_layer_norm:
                                gain = (gain / gain.pow(2).mean().sqrt()
                                        .clamp_min(1e-30)).clamp(max=self.gain_clip)
                            g_lo, g_hi = float(gain.min()), float(gain.max())
                            ev = (mu[:, None] * lam[None, :]).reshape(-1)
                            er = float(ev.sum() ** 2 / (ev.pow(2).sum() + 1e-30))
                            gains_lo.append(g_lo)
                            gains_hi.append(g_hi)
                            eff_ranks.append(er)
                            role = self._roles.get(p, "other")
                            acc_r = self.role_gain.setdefault(
                                role, [g_lo, g_hi, 0.0, 0])
                            acc_r[0] = min(acc_r[0], g_lo)
                            acc_r[1] = max(acc_r[1], g_hi)
                            acc_r[2] += er
                            acc_r[3] += 1
                            if self.telemetry_extra and ((pt % self.refresh == 0) or pt == self.warmup+1):
                                _spectrum = (mu[:,None]*lam[None,:]).reshape(-1)
                                _idx = _spectrum.topk(max(1, math.ceil(.1*_spectrum.numel()))).indices
                                _before = C.reshape(-1).square()
                                _after = (C*gain).reshape(-1).square()
                                _tele.setdefault("energy_top_before",[]).append(float(_before[_idx].sum()/(_before.sum()+1e-30)))
                                _tele.setdefault("energy_top_after",[]).append(float(_after[_idx].sum()/(_after.sum()+1e-30)))
                            C = C * gain
                            if UB is not None:
                                C = UB @ C
                            if UA is not None:
                                C = C @ UA.T
                            z = C.reshape_as(p)

                y_sq_total += float((y * y).sum())
                z_sq_total += float((z * z).sum())
                dot_total += float((y * z).sum())
                cache.append((p, group, y, z, pm12))

        # ---- pass 2: global norm-preserving rescale, then apply the update ------
        ny = y_sq_total ** 0.5
        nz = z_sq_total ** 0.5
        # `op_active` is "the operator ran this step" and drives the telemetry and
        # the wiring canary; `do_rescale` is the separate question of whether the
        # global norm rescale is applied. They were one variable until EvieKFr
        # needed to disable the rescale WITHOUT making n_active_steps read 0,
        # which the engine treats as a silent-AdamW bug and flags as a divergence.
        op_active = active_gate and any_noise and nz > 1e-30
        do_rescale = op_active and self.norm_preserve
        scale = (ny / nz) if do_rescale else 1.0
        if self.telemetry_extra:
            if op_active:
                self._extra["c_sum"] += scale
                self._extra["c_n"] += 1
                self._extra["c_min"] = min(self._extra["c_min"], scale)
            self.last_c_mean = self._extra["c_sum"]/max(1,self._extra["c_n"])
            self.last_c_min = self._extra["c_min"] if self._extra["c_n"] else float("nan")
            self.eig_refresh_time_s = self._extra["eig_s"]
            for _key, _values in _tele.items():
                if _values:
                    setattr(self, _key, sum(_values)/len(_values))
        den = ny * nz
        self.last_cos = (dot_total / den) if (op_active and den > 1e-30) else 1.0
        self.tr_sigma = tr_sigma_total
        self.b_simple = (tr_sigma_total / (y_sq_for_bsimple + 1e-30)
                         if any_noise else 0.0)
        if gains_lo:
            self.gain_lo, self.gain_hi = min(gains_lo), max(gains_hi)
            self.eff_rank = sum(eff_ranks) / len(eff_ranks)
        if op_active:
            self.n_active_steps += 1

        for p, group, y, z, pm12 in cache:
            lr, wd = group["lr"], group["weight_decay"]
            if wd != 0.0:
                p.mul_(1.0 - lr * wd)                          # decoupled WD
            u = (pm12 * (z * scale)) if scale != 1.0 else (pm12 * z)
            p.add_(u.to(p.dtype), alpha=-lr)
        return loss


def eviekf_self_check():
    """Dense-vs-factored (B kron A)^-1/2 parity + the gamma=0 identity
    (optimizer specification sec 4.3.3 / sec 5). Ported from kaggle_evie_v3.py's
    self_check(). Raises RuntimeError on failure -- the engine turns that into a
    one-sentence abort, exactly like the CUDA preflight. A vec-ordering / eigh
    bug here produces a plausible-looking but meaningless results table."""
    gen = torch.Generator().manual_seed(0)
    n, m, gam = 5, 4, 3.7
    D = torch.randn(40, n, m, generator=gen, dtype=torch.float64)
    A = torch.einsum("bij,bik->jk", D, D) / 40.0
    B = torch.einsum("bij,bkj->ik", D, D) / 40.0
    tr = float(A.trace())
    Y = torch.randn(n, m, generator=gen, dtype=torch.float64)
    lam, UA = torch.linalg.eigh(A)
    mu, UB = torch.linalg.eigh(B)
    gain = (1.0 + gam * (mu[:, None] * lam[None, :]) / tr).rsqrt()
    fast = UB @ ((UB.T @ Y @ UA) * gain) @ UA.T
    M = torch.eye(n * m, dtype=torch.float64) + gam * torch.kron(B, A) / tr
    w, V = torch.linalg.eigh(M)
    dense = (V @ torch.diag(w.rsqrt()) @ V.T) @ Y.reshape(-1)
    e1 = float((fast.reshape(-1) - dense).abs().max())
    g1 = (1.0 + 0.0 * (mu[:, None] * lam[None, :]) / tr).rsqrt()
    e2 = float((UB @ ((UB.T @ Y @ UA) * g1) @ UA.T - Y).abs().max())
    ok3 = bool((gain <= 1.0 + 1e-12).all())
    if not (e1 < 1e-9 and e2 < 1e-9 and ok3):
        raise RuntimeError(
            f"EvieKF Kronecker self-check FAILED (factored-vs-dense max err "
            f"{e1:.2e}, gamma=0 identity err {e2:.2e}, gains<=1 {ok3}); refusing "
            f"to run -- every Evie-KF number would be meaningless.")
    return {"factored_vs_dense": e1, "gamma0_identity": e2, "gains_le_1": ok3}


class MuonEvie(EvieKF):
    """Muon matrices plus EvieKFm auxiliaries; norm preservation and all
    inherited mechanism diagnostics cover ONLY the Evie parameter group."""
    def __init__(self, muon_params, evie_params, matrix_lr, sub_lr, gamma,
                 **evie_kwargs):
        evie_params = list(evie_params)
        self._evie_ids = {id(p) for p in evie_params}
        groups = [dict(params=list(muon_params), lr=matrix_lr, use_muon=True,
                       momentum=MUON_MOMENTUM, nesterov=MUON_NESTEROV,
                       ns_steps=MUON_NS_STEPS, weight_decay=WEIGHT_DECAY),
                  dict(params=evie_params, lr=sub_lr, use_muon=False)]
        super().__init__(groups, lr=sub_lr, gamma=gamma, **evie_kwargs)

    @torch.no_grad()
    def set_noise(self, pairs):
        super().set_noise((p, d) for p, d in pairs if id(p) in self._evie_ids)

    @torch.no_grad()
    def step(self, closure=None):
        loss = None
        if closure is not None:
            with torch.enable_grad():
                loss = closure()
        for group in self.param_groups:
            if group.get("use_muon", False):
                _muon_matrix_step(self, group)
        super().step()
        return loss

    def state_dict(self):
        state = super().state_dict()
        # EvieKF derives arithmetic counters from per-parameter state. Its
        # diagnostic activity counter must also survive a mid-run resume.
        state["muonevie_active_steps"] = self.n_active_steps
        return state

    def load_state_dict(self, state_dict):
        state_dict = dict(state_dict)
        active = state_dict.pop("muonevie_active_steps", 0)
        super().load_state_dict(state_dict)
        self.n_active_steps = int(active)
        self._evie_ids = {id(p) for g in self.param_groups
                          if not g.get("use_muon", False) for p in g["params"]}


def muonevie_self_check():
    """CPU float32 nesting, gate isolation, tied split, and resume canaries."""
    import copy
    class Tiny(nn.Module):
        def __init__(self):
            super().__init__()
            self.embedding = nn.Parameter(torch.zeros(7, 4))
            self.bias = nn.Parameter(torch.zeros(4))
            self.hidden1 = nn.Parameter(torch.zeros(4, 4))
            self.hidden2 = nn.Parameter(torch.zeros(4, 5))
            self._muon_exclude_names = {"embedding"}
    gen = torch.Generator().manual_seed(1907)
    def feed(models, opts):
        for ps in zip(*(m.parameters() for m in models)):
            grad = torch.randn(ps[0].shape, generator=gen)
            delta = torch.randn(ps[0].shape, generator=gen)
            for p, opt in zip(ps, opts):
                p.grad = grad.clone()
                if hasattr(opt, "set_noise"):
                    opt.set_noise([(p, delta.clone())])
        for opt in opts:
            opt.step()
    def gap(a, b, evie=None):
        return max(float((p-q).detach().abs().max()) for (name,p),q in
                   zip(a.named_parameters(), b.parameters())
                   if evie is None or ((name in {"embedding", "bias"}) == evie))
    for gamma, steps in [(0, 8), (300, 40)]:
        a, b = Tiny(), Tiny()
        oa = build_optimizer("MuonSub", a, .001, matrix_lr=.002,
                             knob=WEIGHT_DECAY)
        ob = build_optimizer("MuonEvie", b, .001, matrix_lr=.002, knob=gamma)
        for _ in range(steps):
            feed([a,b], [oa,ob])
        if gamma == 0 and gap(a,b) > 1e-6:
            raise RuntimeError("MuonEvie gamma=0 does not nest MuonSub.")
        if gamma and (gap(a,b,True) <= 1e-5 or gap(a,b,False) > 1e-6
                      or ob.n_active_steps <= 0):
            raise RuntimeError("MuonEvie gate is inactive or modifies Muon matrices.")
        c = copy.deepcopy(b)
        oc = build_optimizer("MuonEvie", c, .001, matrix_lr=.002, knob=gamma)
        oc.load_state_dict(copy.deepcopy(ob.state_dict()))
        feed([b,c], [ob,oc])
        if gap(b,c) > 1e-6 or ob.n_active_steps != oc.n_active_steps:
            raise RuntimeError("MuonEvie checkpoint resume does not round-trip.")
    return True


def evie_controls_self_check():
    """Gamma-zero, genuinely lagged gate, Kronecker-only random basis,
    telemetry arithmetic/RNG parity, and control checkpoint round-trip."""
    import copy
    gen = torch.Generator().manual_seed(841)
    def make(**kw):
        p = nn.Parameter(torch.ones(4, 5, dtype=torch.float32))
        return p, EvieKF([p], lr=.01, weight_decay=WEIGHT_DECAY,
                         refresh=10, **kw)
    def update(p, opt, grad, delta):
        p.grad = grad.clone()
        if hasattr(opt, "set_noise"):
            opt.set_noise([(p, delta.clone())])
        opt.step()
    for flag in ["lagged", "random_basis"]:
        p, opt = make(gamma=0., **{flag:True})
        q = nn.Parameter(p.detach().clone())
        ref = torch.optim.AdamW([q], lr=.01, betas=EVIEKF_BETAS,
                               eps=EVIEKF_EPS, weight_decay=WEIGHT_DECAY)
        for _ in range(5):
            g = torch.randn(p.shape, generator=gen)
            d = torch.randn(p.shape, generator=gen)
            update(p,opt,g,d);update(q,ref,g,d)
        if float((p-q).detach().abs().max()) > 1e-6:
            raise RuntimeError("Evie control gamma-zero nesting failed")
    for lagged in [True,False]:
        p, opt = make(gamma=300., lagged=lagged)
        for _ in range(39):
            update(p,opt,torch.randn(p.shape,generator=gen),torch.randn(p.shape,generator=gen))
        q, other = make(gamma=300.,lagged=lagged)
        q.data.copy_(p.data);other.load_state_dict(copy.deepcopy(opt.state_dict()))
        grad = torch.randn(p.shape,generator=gen)
        d = torch.randn(p.shape,generator=gen)
        update(p,opt,grad,d);update(q,other,grad,50*d.flip(0))
        gap = float((p-q).detach().abs().max())
        if (lagged and gap >= 1e-7) or (not lagged and gap <= 1e-6):
            raise RuntimeError("Lagged gate canary failed to isolate current noise")
    p, opt = make(gamma=30., random_basis=True)
    q, ref = make(gamma=30.)
    a, logged = make(gamma=30., telemetry_extra=True)
    global_rng = torch.random.get_rng_state().clone()
    for _ in range(30):
        g,d = torch.randn(p.shape,generator=gen),torch.randn(p.shape,generator=gen)
        update(p,opt,g,d);update(q,ref,g,d);update(a,logged,g,d)
    if not torch.equal(global_rng,torch.random.get_rng_state()) or not torch.equal(q,a):
        raise RuntimeError("Extra Evie telemetry changed arithmetic or global RNG")
    st, sr = opt.state[p],ref.state[q]
    RA = st["RA"]
    if not torch.allclose(RA.T@RA,torch.eye(RA.size(0)),atol=1e-5):
        raise RuntimeError("Random-basis control is not orthogonal")
    # Noise whitening is gradient-only, hence shared spectra despite changed weights.
    ga=(1+30*st["mu"][:,None]*st["lam"][None,:]/st["tr"]).rsqrt()
    gb=(1+30*sr["mu"][:,None]*sr["lam"][None,:]/sr["tr"]).rsqrt()
    if not torch.equal(ga,gb):
        raise RuntimeError("Random-basis control changed the gate spectrum")
    q, restored=make(gamma=30.,random_basis=True)
    q.data.copy_(p);restored.load_state_dict(copy.deepcopy(opt.state_dict()))
    g,d=torch.randn(p.shape,generator=gen),torch.randn(p.shape,generator=gen)
    update(p,opt,g,d);update(q,restored,g,d)
    if not torch.equal(p,q):
        raise RuntimeError("Evie control checkpoint round-trip failed")
    return True


def build_optimizer(opt_name, model, lr, adamw_lr=None, knob=None,
                    eviekf_maxf=None, matrix_lr=None, telemetry_extra=False):
    """Single optimizer-selection entry point (benchmark protocol sec 1: keep this
    structured so a new optimizer pastes in as one extra branch). `lr` is the
    frozen, LR-searched value for `opt_name`. `adamw_lr` is only used by Muon
    (its AdamW sub-group). `knob` is the frozen value of the SECOND tuned axis
    for optimizers in KNOB_GRID -- gamma for the Evie-KF family, beta for
    Shampoo -- and is ignored by every other optimizer. Weight decay is
    WEIGHT_DECAY (decoupled) for every optimizer.

    `eviekf_maxf` overrides the frozen EVIEKF_MAXF Kronecker size limit and is
    passed by the engine ONLY when the task declares TASK["eviekf_maxf"] -- a
    diagnostic file, never a protocol task (see the note on EVIEKF_MAXF). It
    arrives as an argument rather than being read from TASK here so that this
    block stays free of any dependency on the task header."""
    params = [p for p in model.parameters() if p.requires_grad]
    if opt_name.endswith("wd") and opt_name in ("AdamWwd", "AdaBeliefwd", "SGDwd", "Lionwd", "Muonwd", "EvieKFmwd"):
        wd = WEIGHT_DECAY if knob is None else float(knob)
        if not math.isfinite(wd) or wd < 0:
            raise ValueError("Weight decay must be finite and nonnegative")
        if opt_name == "EvieKFmwd":
            opt = build_optimizer("EvieKFm", model, lr, knob=EVIEKF_FIXED_GAMMA_M,
                                  telemetry_extra=telemetry_extra)
        else:
            opt = build_optimizer(opt_name[:-2], model, lr, adamw_lr=adamw_lr,
                                  telemetry_extra=telemetry_extra)
        for group in opt.param_groups:
            group["weight_decay"] = wd
        return opt
    if opt_name in ("MuonSub", "MuonEvie", "MuonEvieFix"):
        if matrix_lr is None or not math.isfinite(matrix_lr) or matrix_lr <= 0:
            raise ValueError("Muon hybrid requires a positive frozen matrix_lr")
        muon_params, rest = split_params_for_muon(model)
        if not muon_params or not rest:
            raise RuntimeError("Muon hybrid needs trainable matrix and auxiliary parameters")
        if opt_name == "MuonSub":
            return Muon([dict(params=muon_params, lr=matrix_lr, use_muon=True),
                         dict(params=rest, lr=lr, use_muon=False,
                              weight_decay=WEIGHT_DECAY if knob is None else float(knob))])
        return MuonEvie(muon_params, rest, matrix_lr, lr,
                        gamma=30.0 if knob is None else float(knob),
                        betas=EVIEKF_BETAS, eps=EVIEKF_EPS,
                        weight_decay=WEIGHT_DECAY, beta_sig=EVIEKF_BETA_SIG,
                        warmup=EVIEKF_WARMUP, refresh=EVIEKF_REFRESH,
                        maxf=EVIEKF_MAXF, diag_only=False, centered=True,
                        per_layer_norm=False, gain_clip=EVIEKF_GAIN_CLIP,
                        diag_relative=True, kron_mean_norm=True, norm_preserve=True,
                        telemetry_extra=telemetry_extra)
    if opt_name == "AdamW":
        return torch.optim.AdamW(params, lr=lr, betas=(0.9, 0.999), eps=1e-8,
                                 weight_decay=WEIGHT_DECAY)
    if opt_name == "AdaBelief":
        return AdaBelief(params, lr=lr, betas=ADABELIEF_BETAS, eps=ADABELIEF_EPS,
                         weight_decay=WEIGHT_DECAY)
    if opt_name == "SGD":
        return SGDM(params, lr=lr, momentum=SGDM_MOMENTUM, nesterov=SGDM_NESTEROV,
                    weight_decay=WEIGHT_DECAY)
    if opt_name == "Sophia":
        return Sophia(params, lr=lr, betas=SOPHIA_BETAS, rho=SOPHIA_RHO,
                      eps=SOPHIA_EPS, weight_decay=WEIGHT_DECAY)
    if opt_name == "Lion":
        return Lion(params, lr=lr, betas=LION_BETAS, weight_decay=WEIGHT_DECAY)
    if opt_name == "Shampoo":
        return Shampoo(params, lr=lr,
                       beta=(float(knob) if knob is not None else SHAMPOO_BETA),
                       eps=SHAMPOO_EPS, update_freq=SHAMPOO_UPDATE_FREQ,
                       graft_betas=SHAMPOO_GRAFT_BETAS, maxf=SHAMPOO_MAXF,
                       weight_decay=WEIGHT_DECAY)
    if opt_name in ("EvieKFn", "EvieKF", "EvieKFu", "EvieDiag",
                    "EvieDiagAbs", "EvieKFm", "EvieKFr", "EvieKFlag", "EvieKFrb", "EvieKFmrb"):
        return EvieKF(params, lr=lr, betas=EVIEKF_BETAS, eps=EVIEKF_EPS,
                      weight_decay=WEIGHT_DECAY,
                      gamma=(float(knob) if knob is not None else 100.0),
                      beta_sig=EVIEKF_BETA_SIG, warmup=EVIEKF_WARMUP,
                      refresh=EVIEKF_REFRESH,
                      maxf=(EVIEKF_MAXF if eviekf_maxf is None
                            else int(eviekf_maxf)),
                      diag_only=(opt_name in ("EvieDiag", "EvieDiagAbs")),
                      centered=(opt_name != "EvieKFu"),
                      per_layer_norm=(opt_name == "EvieKFn"),
                      gain_clip=EVIEKF_GAIN_CLIP,
                      diag_relative=(opt_name != "EvieDiagAbs"),
                      kron_mean_norm=(opt_name in ("EvieKFm", "EvieKFmrb")),
                      norm_preserve=(opt_name != "EvieKFr"),
                      lagged=(opt_name == "EvieKFlag"), random_basis=(opt_name in ("EvieKFrb", "EvieKFmrb")),
                      telemetry_extra=telemetry_extra)
    if opt_name == "Muon":
        muon_params, adamw_params = split_params_for_muon(model)
        a_lr = adamw_lr if adamw_lr is not None else lr
        groups = []
        if muon_params:
            groups.append(dict(params=muon_params, lr=lr, use_muon=True))
        if adamw_params:
            groups.append(dict(params=adamw_params, lr=a_lr, use_muon=False))
        if not groups:
            raise RuntimeError("Muon: model has no trainable parameters")
        return Muon(groups)
    raise ValueError(f"unknown optimizer {opt_name!r}")


def optimizer_lr_scale(optimizer):
    """Base LRs per param-group, so the engine's cosine scheduler can be rebuilt
    on resume with the right per-group base_lrs (Muon has two)."""
    return [g["lr"] for g in optimizer.param_groups]
# === END SHARED OPTIMIZER BLOCK ===


# ==============================================================================
#  ENGINE  --  preflight, checkpoint/resume, divergence & error handling,
#  LR search (7-point half-decade + boundary rule), training loop, stats.
#  GENERATED: identical across all 12 files. Edit _build/frag_engine.py.
#
#  Domain hooks this engine calls (provided by the data fragment above):
#    prepare_data()                                  -> data handle
#    lr_search_units(data)                           -> [unit, ...]  (LR search)
#    main_units(data)                                -> [unit, ...]  (main sweep)
#    build_model(data, unit)                         -> nn.Module on DEVICE
#                                                      (._muon_exclude_names set)
#    make_loaders(data, unit, batch_size, seed)      -> (train, val, test)
#    make_criterion()                                -> loss fn
#    forward_loss(model, batch, criterion)           -> scalar loss tensor
#    evaluate(model, loader, criterion)              -> (primary_value, aux_dict)
#    AUX_METRIC_KEYS                                 -> [str, ...] (descriptive)
# ==============================================================================

# Which optimizer set this file runs: the main 8 (default), the Evie-KF
# ablation ladder for the generated benchmark12/ablation/ files
# (TASK["opt_set"] == "ablation", optimizer specification sec 2/3), or the trimmed
# scale-generalization arm set for benchmark12/scalegen/ files
# (TASK["opt_set"] == "scalegen", evie-scalegen-spec.md sec 1). Every loop
# below iterates ACTIVE_OPT_NAMES, never OPT_NAMES directly.
# A diagnostic file (TASK["opt_set"] == "diag") runs an explicit arm list from
# TASK["opt_list"] with its (lr, knob) PINNED by TASK["pinned_lr"] -- no search.
# TASK["fixed_knob"] is the weaker form: the second axis is FIXED at a stated
# value while the LR is still searched over the ordinary 7-point grid, i.e. the
# arm gets exactly the baselines' tuning budget. TASK["fixed_lr"] is its mirror:
# pin the LR and search the second axis only.
# It answers a single "was this a tuning artefact?" question about one already
# finished task and is never part of any significance table.
ACTIVE_OPT_NAMES = (list(TASK["opt_list"]) if TASK.get("opt_list")
                    else ABLATION_OPT_NAMES if TASK.get("opt_set") == "ablation"
                    else SCALEGEN_OPT_NAMES if TASK.get("opt_set") == "scalegen"
                    else OPT_NAMES)
# BENCH12_ARMS splits ONE task across several machines: each run does a subset of
# the arms, writing into the same checkpoints/<TASK_NAME>/ namespace, and the
# per-arm results are merged afterwards. Cells are keyed "opt|unit|seed", never by
# index, so a union of the parts is exactly the whole -- this is the same property
# that makes reordering OPT_NAMES safe mid-run. Used for language_openwebtext,
# where one machine cannot finish in the time available.
_ARMS_ENV = os.environ.get("BENCH12_ARMS", "").strip()
if _ARMS_ENV:
    _want = [a.strip() for a in _ARMS_ENV.split(",") if a.strip()]
    _unknown = [a for a in _want if a not in ACTIVE_OPT_NAMES]
    if _unknown:
        raise SystemExit(f"BENCH12_ARMS names {_unknown}, which this task does not "
                         f"run (its arms are {ACTIVE_OPT_NAMES})")
    ACTIVE_OPT_NAMES = [a for a in ACTIVE_OPT_NAMES if a in _want]

# ---- graceful stop: flush the in-progress cell before exiting (benchmark protocol 6) --
_STOP = {"flag": False, "sig": None}


def _on_signal(signum, frame):
    # Signal handlers must stay minimal: log() does buffered/locked stdio via
    # Python's TextIOWrapper, which is NOT safe to re-enter from a handler --
    # if the main thread is itself mid-print() (or a second signal lands before
    # the first handler returns, e.g. someone mashing Ctrl-C), that throws
    # "RuntimeError: reentrant call". The training loop already logs and
    # checkpoints cleanly once it observes the flag (see the top of the step
    # loop below); os.write() is the one signal-safe way to also ack immediately.
    _STOP["flag"] = True
    _STOP["sig"] = signum
    try:
        os.write(2, f"\n[signal] caught signal {signum}; will checkpoint and "
                    f"exit at the next safe point\n".encode())
    except Exception:
        pass


for _s in (signal.SIGTERM, signal.SIGINT):
    try:
        signal.signal(_s, _on_signal)
    except Exception:
        pass


_ENV_ERROR_MARKERS = (
    "cuda error", "cublas", "cudnn", "device-side assert", "no kernel image",
    "cuda out of memory", "illegal memory access", "misaligned address",
    "cuda runtime", "nccl", "cufft", "curand", "cusolver", "not compiled with cuda",
    "device kernel image", "invalid device function",
)


def classify_exception(e):
    """'env'  -> environment/hardware/build problem: re-raise, abort the file.
    'numerical' -> this one cell blew up (NaN/inf/shape from a bad LR): record
    it as a failed cell and keep going.  (benchmark protocol sec 6: never swallow the
    first kind as if it were the second.)"""
    txt = f"{type(e).__name__}: {e}".lower()
    if isinstance(e, (torch.cuda.OutOfMemoryError,)):
        return "env"
    if any(m in txt for m in _ENV_ERROR_MARKERS):
        return "env"
    if isinstance(e, (RuntimeError, FloatingPointError, ValueError, ArithmeticError)):
        return "numerical"
    return "env"


def _preflight_eviekf_self_check():
    # Evie-KF Kronecker self-check (optimizer specification sec 4.3.3): dense-vs-factored
    # (B kron A)^-1/2 parity + the gamma=0 identity. Cheap, CPU-only math -- runs
    # for every file regardless of CUDA/CPU/SMOKE, because a vec-ordering/eigh
    # bug here would silently produce a meaningless table, so abort in one
    # sentence now, same as the CUDA check below. (Previously this only ran on
    # the CUDA branch, so ALLOW_CPU=1/SMOKE=1 runs -- exactly the runs meant to
    # be a cheap correctness gate before spending GPU time -- never exercised it.)
    try:
        _sc = eviekf_self_check()
        if any(a in ("EvieKFlag", "EvieKFrb", "EvieKFmrb") for a in ACTIVE_OPT_NAMES):
            evie_controls_self_check()
            log("[preflight] Evie control nesting/lag/basis/telemetry/resume checks OK")
        if any(a in ("MuonEvie", "MuonEvieFix") for a in ACTIVE_OPT_NAMES):
            muonevie_self_check()
            log("[preflight] MuonEvie nesting/isolation/resume self-check OK")
        log(f"[preflight] EvieKF self-check OK  (factored-vs-dense "
            f"{_sc['factored_vs_dense']:.1e}, gamma=0 identity "
            f"{_sc['gamma0_identity']:.1e})")
    except Exception as e:
        fail(f"EvieKF self-check failed at startup: {e}")


def preflight():
    """Verify CUDA is actually usable BEFORE any real training, so a broken
    torch/GPU stack fails in one sentence now instead of 10 optimizers deep with
    a raw traceback (benchmark protocol sec 6)."""
    if os.environ.get("BENCH12_TORCH_THREADS"):
        _threads = int(os.environ["BENCH12_TORCH_THREADS"])
        if _threads < 1:
            fail("BENCH12_TORCH_THREADS must be a positive integer")
        torch.set_num_threads(_threads)
    if not torch.cuda.is_available():
        if os.environ.get("ALLOW_CPU") == "1" or SMOKE:
            log("[preflight] CUDA not available; ALLOW_CPU/SMOKE set -> running on CPU")
            _preflight_eviekf_self_check()
            return
        if TASK.get("extra_metrics"):
            fail("CUDA is not available. Use the supplied GPU server, or ALLOW_CPU=1 for a CPU correctness run.")
        fail("CUDA is not available. This harness targets a single RTX A6000. "
             "Set ALLOW_CPU=1 only for a CPU correctness smoke test.")
    try:
        cap = torch.cuda.get_device_capability()
        sm = f"sm_{cap[0]}{cap[1]}"
        arch_list = list(torch.cuda.get_arch_list())
        name = torch.cuda.get_device_name()
    except Exception as e:
        fail(f"CUDA reports available but querying the device failed ({e!r}); "
             f"the torch/driver install is broken.")
        return
    if not any(a == sm for a in arch_list):
        log(f"[preflight] WARNING: torch arch_list={arch_list} has no exact match "
            f"for this GPU ({sm}, {name}); relying on the live op check below")
    try:
        a = torch.randn(256, 256, device="cuda")
        b = torch.randn(256, 256, device="cuda")
        _ = float((a @ b).sum().item())
        torch.cuda.synchronize()
    except Exception as e:
        fail(f"CUDA is present ({name}, {sm}) but a trivial matmul failed ({e!r}). "
             f"The torch build does not match this GPU -- reinstall torch for {sm}.")
    log(f"[preflight] OK: {name}  {sm}  torch={torch.__version__}  "
        f"arch_list={arch_list}")
    _preflight_eviekf_self_check()
    _tf = os.environ.get("BENCH12_TF32")
    if _tf is not None and _tf not in ("0", "1"):
        fail("BENCH12_TF32 must be 0 or 1")
    if _tf is not None or TASK.get("allow_tf32", False):
        _enabled = (_tf == "1") if _tf is not None else True
        if _enabled and cap[0] < 8:
            log(f"[tf32] requested but GPU capability {cap[0]}.{cap[1]} does not support it; running float32")
            _enabled = False
        torch.backends.cuda.matmul.allow_tf32 = _enabled
        torch.backends.cudnn.allow_tf32 = _enabled
        log(f"[preflight] TF32={int(_enabled)} after self-checks; state fp32, eigh fp64")
    _free, _total = torch.cuda.mem_get_info()
    log(f"[preflight] device={torch.cuda.get_device_name(0)} free={_free/2**30:.2f} GiB total={_total/2**30:.2f} GiB")


# ---------------------------------------------------------------------------
#  Atomic checkpoint IO. tmp name carries PID + randomness so two processes
#  sharing a directory (e.g. a network mount) still cannot collide; the real
#  file is only ever replaced via os.replace after fsync; the previous good
#  copy is rotated to .bak first (benchmark protocol sec 6).
# ---------------------------------------------------------------------------
def atomic_torch_save(obj, path):
    d = os.path.dirname(path) or "."
    os.makedirs(d, exist_ok=True)
    tmp = os.path.join(d, f".{os.path.basename(path)}.tmp.{os.getpid()}."
                          f"{random.randint(0, 1 << 30):x}")
    with open(tmp, "wb") as fh:
        torch.save(obj, fh)
        fh.flush()
        os.fsync(fh.fileno())
    if os.path.exists(path):
        try:
            os.replace(path, path + ".bak")
        except OSError:
            pass
    os.replace(tmp, path)


def load_cell_ckpt(path):
    for p in (path, path + ".bak"):
        if os.path.exists(p):
            try:
                return torch.load(p, map_location="cpu", weights_only=False)
            except Exception as e:
                log(f"[resume] {p} is unreadable ({e!r}); trying next")
    return None


def _read_json(path, default):
    if os.path.exists(path):
        try:
            with open(path) as fh:
                return json.load(fh)
        except Exception as e:
            if TASK.get("extra_metrics"):
                raise RuntimeError(f"{path} is unreadable; preserving it instead of resetting recorded results. Restore a valid copy before resuming.") from e
            log(f"[warn] {path} unreadable ({e!r}); starting fresh")
    return default


def _write_json(path, obj):
    d = os.path.dirname(path) or "."
    tmp = os.path.join(d, f".{os.path.basename(path)}.tmp.{os.getpid()}")
    with open(tmp, "w") as fh:
        json.dump(obj, fh, indent=2, default=_json_default)
        fh.flush()
        os.fsync(fh.fileno())
    os.replace(tmp, path)


def _json_default(o):
    if isinstance(o, (np.integer,)):
        return int(o)
    if isinstance(o, (np.floating,)):
        return float(o)
    if isinstance(o, np.ndarray):
        return o.tolist()
    return str(o)


# ---------------------------------------------------------------------------
#  LR schedule -- manual cosine so it works with Muon's two param groups
#  (different base LRs) and needs no scheduler state in the checkpoint.
# ---------------------------------------------------------------------------
def _fresh_epochs(loader):
    """Endless batches that re-iterate `loader` each epoch (TASK["fresh_epochs"]).

    Unlike itertools.cycle(loader), nothing is stored: each epoch asks the
    DataLoader for a new iterator, so its sampler reshuffles and the dataset's
    random augmentation is drawn again."""
    while True:
        n = 0
        for batch in loader:
            n += 1
            yield batch
        if n == 0:
            raise RuntimeError("train loader produced no batches")


def cosine_factor(step, total):
    if total <= 1:
        return 1.0
    frac = min(max(step / float(total), 0.0), 1.0)
    return ETA_MIN_FRAC + (1.0 - ETA_MIN_FRAC) * 0.5 * (1.0 + math.cos(math.pi * frac))


def _apply_lr(optimizer, base_lrs, factor):
    for g, base in zip(optimizer.param_groups, base_lrs):
        g["lr"] = base * factor


def _power_iteration_top_eig(model, params, compute_loss, iters=10, eps=1e-8):
    """|top Hessian eigenvalue| by power iteration on Hessian-vector products
    (one batch). Descriptive only; run once per cell for Hessian-consuming
    optimizers (AdaHessian/Sophia-style)."""
    with torch.enable_grad():
        loss = compute_loss()
    grads = torch.autograd.grad(loss, params, create_graph=True)
    v = [torch.randn_like(p) for p in params]
    nrm = math.sqrt(sum(float(x.pow(2).sum().item()) for x in v)) + eps
    v = [x / nrm for x in v]
    ev = 0.0
    for _ in range(iters):
        gv = sum((g * vv).sum() for g, vv in zip(grads, v))
        hv = torch.autograd.grad(gv, params, retain_graph=True)
        ev = sum(float((h * vv).sum().item()) for h, vv in zip(hv, v))
        nrm = math.sqrt(sum(float(h.pow(2).sum().item()) for h in hv)) + eps
        v = [h.detach() / nrm for h in hv]
    return abs(ev)


def _is_finite(x):
    return x is not None and math.isfinite(float(x))


def _better(a, b):
    """True iff primary value a is strictly better than b (direction aware)."""
    if not _is_finite(a):
        return False
    if not _is_finite(b):
        return True
    return a < b if PRIMARY_LOWER_BETTER else a > b


def _absurd_primary(v, peer_median=None):
    """Absolute + peer-relative sanity (benchmark protocol sec 6: an absolute range, not
    just 'worse than this run's own best')."""
    if not _is_finite(v):
        return True
    lo, hi = PRIMARY_ABS_RANGE
    if v < lo or v > hi:
        return True
    if peer_median is not None and _is_finite(peer_median) and peer_median != 0:
        if PRIMARY_LOWER_BETTER and v > PEER_DIVERGENCE_FACTOR * peer_median:
            return True
        if (not PRIMARY_LOWER_BETTER) and peer_median > 0 and \
           v < peer_median / PEER_DIVERGENCE_FACTOR:
            return True
    return False


def _infer_param_roles(model):
    """{param: role} for the Evie-KF per-module-category gain breakdown
    (optimizer specification sec 4.3.5). Substring match on the qualified parameter
    name; checked against the actual module names in the language GPT
    (wte/wpe/qkv/proj/fc1/fc2/lm_head), the vision ResNet (conv/bn/fc) and the
    finance MLP (net.N) -- vision/finance mostly land in "other", which is fine.
    """
    roles = {}
    for nm, p in model.named_parameters():
        if not p.requires_grad:
            continue
        low = nm.lower()
        if any(k in low for k in ("wte", "wpe", "embed", "emb.", "tok_emb",
                                  "pos_emb", "embedding")):
            r = "embedding"
        elif any(k in low for k in ("attn", "qkv", ".proj", "attention", "q_proj",
                                    "k_proj", "v_proj", "out_proj")):
            r = "attention"
        elif any(k in low for k in ("mlp", "ffn", "fc1", "fc2", "feed_forward",
                                    "w1", "w2", "w3")):
            r = "ffn"
        elif any(k in low for k in ("lm_head", "head", "classifier", "fc.weight",
                                    "fc.bias", ".fc.")):
            r = "head"
        else:
            r = "other"
        roles[p] = r
    return roles


def _model_has_batchnorm(model):
    """True if any module normalises ACROSS the batch dimension.

    Why this exists (fairness, not cosmetics): the Evie-KF family needs the
    split-batch noise sample, so it runs two half-batch forward/backwards per
    step instead of one full-batch one. On a LayerNorm model (the GPT) or a
    plain MLP (finance) that is mathematically free -- (gA + gB)/2 over two
    disjoint equal halves is EXACTLY the full-batch gradient, so the baselines
    can keep the cheaper single backward with no confound.

    On a BatchNorm model (the CIFAR-stem ResNet-18, i.e. all 4 vision tasks)
    it is NOT free: BN over two halves is ghost batch norm, a real and
    well-documented regulariser, and it also updates BN's running statistics
    twice per step from half-batch estimates. Left uncorrected, the Evie arms
    would be training a DIFFERENT objective than the baselines, and any vision
    win would be uninterpretable -- "is this the preconditioner or is it GBN?"
    So where BN is present, EVERY optimizer takes the split path: identical
    training signal, identical BN behaviour, and the preconditioner is then the
    only thing that differs. FLOP-neutral (two half backwards ~= one full one).
    """
    bn_types = tuple(
        t for t in (getattr(nn, n, None) for n in
                    ("BatchNorm1d", "BatchNorm2d", "BatchNorm3d",
                     "SyncBatchNorm", "InstanceNorm1d", "InstanceNorm2d",
                     "InstanceNorm3d"))
        if t is not None)
    return any(isinstance(m, bn_types) for m in model.modules())


# ---------------------------------------------------------------------------
#  One training run: (optimizer, unit, seed) for the main sweep, or one
#  (optimizer, unit) LR-search probe. Fully resumable from ckpt_path.
# ---------------------------------------------------------------------------
def train_run(opt_name, data, unit, lr, adamw_lr, total_steps, seed,
              ckpt_path, is_lr_search=False, knob=None):
    criterion = make_criterion()
    tag = f"{opt_name}/{unit}/seed{seed}" + ("/LR" if is_lr_search else "")

    ck = load_cell_ckpt(ckpt_path) if ckpt_path else None
    if ck is not None and ck.get("complete"):
        return ck["result"]
    if ck is not None and "model" not in ck:      # slim/partial file -> restart
        ck = None

    train_loader, val_loader, test_loader = make_loaders(data, unit, BATCH_SIZE, seed)

    if ck is None:
        set_seed(seed * 100003 + (7 if is_lr_search else 0))
        model = build_model(data, unit).to(DEVICE)
        optimizer = build_optimizer(opt_name, model, lr, adamw_lr=adamw_lr,
                                    knob=knob,
                                    eviekf_maxf=TASK.get("eviekf_maxf"),
                                    matrix_lr=TASK.get("muon_matrix_lr"),
                                    telemetry_extra=bool(TASK.get("extra_metrics")))
        base_lrs = optimizer_lr_scale(optimizer)
        start_step = 0
        best_val = math.inf if PRIMARY_LOWER_BETTER else -math.inf
        best_state = None
        acc = dict(clip_events=0, step_sq_sum=0.0, step_sq_n=0, n_params=0,
                   wall=0.0, hess_norms=[], val_curve=[],
                   # --- descriptive-only diagnostics (benchmark protocol sec 9.5 dir.):
                   # recorded per cell, NEVER significance-tested. Primary stays
                   # the one pre-registered metric per domain. ---
                   grad_norms=[], theta_sq_sum=0.0, uwr_sum=0.0, uwr_n=0,
                   upcos_sum=0.0, upcos_n=0, hess_trace_samples=[],
                   train_loss_ema=None, final_train_loss=float("nan"),
                   loss_at=[None, None, None], eval_wall=[], w0_norm=None,
                   flops=0.0)
        _tp = [p for p in model.parameters() if p.requires_grad]
        acc["n_params"] = int(sum(p.numel() for p in _tp))
        with torch.no_grad():
            acc["w0_norm"] = math.sqrt(sum(float(p.detach().pow(2).sum().item())
                                           for p in _tp))
        diverged, fail_reason = False, None
    else:
        model = build_model(data, unit).to(DEVICE)
        model.load_state_dict(ck["model"])
        optimizer = build_optimizer(opt_name, model, lr, adamw_lr=adamw_lr,
                                    knob=knob,
                                    eviekf_maxf=TASK.get("eviekf_maxf"),
                                    matrix_lr=TASK.get("muon_matrix_lr"),
                                    telemetry_extra=bool(TASK.get("extra_metrics")))
        optimizer.load_state_dict(ck["optimizer"])
        base_lrs = ck["base_lrs"]
        start_step = ck["step"]
        best_val = ck["best_val"]
        best_state = ck["best_state"]
        acc = ck["acc"]
        diverged = ck.get("diverged", False)
        fail_reason = ck.get("fail_reason", None)
        load_rng_state(ck["rng"])
        log(f"[resume] {tag} from step {start_step}/{total_steps}")

    params = [p for p in model.parameters() if p.requires_grad]
    extra = bool(TASK.get("extra_metrics")) and not is_lr_search
    speed = os.environ.get("BENCH12_SPEEDTEST") == "1"
    _init = [p.detach().cpu().clone() for p in params] if extra and ck is None else None
    if extra:
        acc.setdefault("x_train_loss_curve", [])
        acc.setdefault("x_spikes", 0); acc.setdefault("x_spike_max", 0.)
        acc.setdefault("x_spike_ema", None)
        acc.setdefault("x_opt_times", []); acc.setdefault("x_fb_times", [])
    _speed_times = []
    _full_units = None
    if TASK.get("assert_param_range") and not SMOKE:
        _count = sum(p.numel() for p in params)
        log(f"[model] {_count:,} trainable parameters")
        _lo, _hi = TASK["assert_param_range"]
        if not _lo <= _count <= _hi:
            raise ValueError(f"Model has {_count} parameters outside [{_lo},{_hi}]")
    hessian_consumer = opt_name in HESSIAN_CONSUMERS
    noise_consumer = opt_name in NOISE_CONSUMERS      # split-batch noise hook
    # Every optimizer takes the split path on a BatchNorm model, so the Evie
    # family's required split cannot hand it ghost-batch-norm regularisation the
    # baselines never get. See _model_has_batchnorm() for the full argument.
    # TASK["force_split_path"] puts the baselines on the split path on a model
    # with no BatchNorm too. It is a MEMORY measure, not a fairness one: the two
    # half-batch backwards never materialise the full-batch logits tensor, which
    # on a 50k-vocab model is batch*ctx*vocab*4 bytes and is what OOM'd
    # language_openwebtext on a T4 (3.07 GiB, exactly). The gradient is unchanged
    # -- test_fairness_and_aggregation.py proves the split path reproduces the
    # full-batch gradient exactly on a BN-free model -- so no arm's arithmetic
    # moves, only its peak allocation.
    split_batch = (noise_consumer or _model_has_batchnorm(model)
                   or bool(TASK.get("force_split_path")))
    if split_batch and not noise_consumer:
        _why = ("BatchNorm model" if _model_has_batchnorm(model)
                else "force_split_path (peak-memory measure; gradient unchanged)")
        log(f"[fairness] {tag}: {_why} -> {opt_name} uses the same "
            f"split-batch forward/backward as the Evie arms (identical training "
            f"signal; preconditioner is the only difference)")
    if noise_consumer and hasattr(optimizer, "set_param_roles"):
        optimizer.set_param_roles(_infer_param_roles(model))
    prev_delta = None                     # for update_cos_sim_sampled (not persisted)
    try:
        fwd_flops = float(estimate_fwd_flops(model, BATCH_SIZE))
    except Exception:
        fwd_flops = float("nan")
    # itertools.cycle() stores the batches of its first pass and replays them,
    # so every epoch after the first reuses epoch 1's shuffle order AND its
    # augmented images (the random crops/flips are never redrawn). That is the
    # behaviour of every run up to 2026-11-11 and stays the default, so those
    # runs remain reproducible. TASK["fresh_epochs"] (opt-in, new tasks only)
    # re-iterates the DataLoader each epoch instead: a new shuffle and new
    # augmentation draws per epoch, nothing else changed.
    if TASK.get("fresh_epochs"):
        loader_iter = _fresh_epochs(train_loader)
        log(f"[data] {tag}: fresh_epochs=True -> the DataLoader is re-iterated "
            f"every epoch (new shuffle + new augmentation draws); the default "
            f"replays the first epoch's batches")
    else:
        loader_iter = itertools.cycle(train_loader)
    if start_step > 0:
        # the DataLoader shuffle order is fixed by its seeded generator, so
        # skipping (start_step mod len) batches restores the exact (x, y)
        # sequence a fresh run would see from here (a resumed run can still
        # differ at the augmentation-RNG level; an uninterrupted run is the
        # reference).
        try:
            nb = len(train_loader)
            for _ in range(start_step % max(nb, 1)):
                next(loader_iter)
        except TypeError:
            pass
    t_wall = time.time()

    def save_cell(complete=False, result=None):
        if not ckpt_path:
            return
        if complete:
            # slim terminal record (~KB): the full result lives in results.json;
            # this just lets a re-run skip the cell. Drop the big .bak too.
            atomic_torch_save({"complete": True, "result": result,
                               "opt_name": opt_name, "unit": unit, "seed": seed},
                              ckpt_path)
            for p in (ckpt_path + ".bak",):
                try:
                    os.remove(p)
                except OSError:
                    pass
            return
        atomic_torch_save({
            "step": step, "opt_name": opt_name, "unit": unit, "seed": seed,
            "lr": lr, "adamw_lr": adamw_lr, "knob": knob, "total_steps": total_steps,
            "model": model.state_dict(), "optimizer": optimizer.state_dict(),
            "base_lrs": base_lrs, "best_val": best_val, "best_state": best_state,
            "acc": acc, "diverged": diverged, "fail_reason": fail_reason,
            "rng": rng_state(), "complete": False, "result": None,
        }, ckpt_path)

    step = start_step
    inputs = targets = None
    model.train()
    while step < total_steps:
        if _STOP["flag"]:
            acc["wall"] += time.time() - t_wall
            save_cell(complete=False)
            log(f"[signal] {tag}: checkpointed at step {step}; exiting cleanly")
            _log_fh.flush()
            sys.exit(0)

        _timed = extra and step % 50 == 0
        if _timed or speed:
            if torch.cuda.is_available(): torch.cuda.synchronize()
            _step_start = time.perf_counter()
            _fb_start = _step_start
        batch = next(loader_iter)
        inputs, targets = batch_to_device(batch)

        measure_step = (step % EVAL_EVERY == 0)      # sample the step-size metric
        p_before = ([p.detach().clone() for p in params] if measure_step else None)

        optimizer.zero_grad(set_to_none=True)
        if _timed:
            if torch.cuda.is_available(): torch.cuda.synchronize()
            _fb_start=time.perf_counter()
        _ga = _gb = None
        if split_batch:
            # Split-batch (optimizer specification sec 4.3.1): two DISJOINT half batches,
            # one fwd+bwd each -- same examples, same total FLOPs as one
            # full-batch backward, no extra data. p.grad <- (gA+gB)/2. For a
            # noise consumer the noise sample delta = (gA-gB)/2 is additionally
            # clipped by the SAME coefficient as g (else the SNR the gate sees is
            # distorted, spec sec 5) and handed to the optimizer via set_noise()
            # BEFORE step(). A non-noise-consumer only lands here on a BatchNorm
            # model, purely so its BN statistics match the Evie arms' -- it needs
            # no half-gradient copies, so it accumulates both halves in place
            # instead (same result, no extra memory).
            _n = inputs.size(0)
            _nh = _n // 2
            if _nh >= 1:
                _xa, _xb = inputs[:_nh], inputs[_nh:2 * _nh]
                _ya, _yb = targets[:_nh], targets[_nh:2 * _nh]
                _la = forward_loss(model, (_xa, _ya), criterion)
                _la.backward()
                if noise_consumer:
                    _ga = [(p.grad.detach().clone() if p.grad is not None else None)
                           for p in params]
                    optimizer.zero_grad(set_to_none=True)
                _lb = forward_loss(model, (_xb, _yb), criterion)
                _lb.backward()
                loss_v = 0.5 * (float(_la.detach().item())
                                + float(_lb.detach().item()))
                if noise_consumer:
                    _gb = [(p.grad.detach().clone() if p.grad is not None else None)
                           for p in params]
                    for p, a, b in zip(params, _ga, _gb):
                        if a is not None and b is not None:
                            p.grad = 0.5 * (a + b)
                        elif a is not None:
                            p.grad = a.clone()
                        elif b is not None:
                            p.grad = b.clone()
                else:
                    # grads were accumulated over both halves, i.e. gA + gB; the
                    # quantity we want is their mean, so halve in place.
                    for p in params:
                        if p.grad is not None:
                            p.grad.mul_(0.5)
            else:                                   # batch too small to split
                loss = forward_loss(model, (inputs, targets), criterion)
                loss.backward()
                loss_v = float(loss.detach().item())
        else:
            loss = forward_loss(model, (inputs, targets), criterion)
            loss.backward()
            loss_v = float(loss.detach().item())

        if _timed:
            if torch.cuda.is_available(): torch.cuda.synchronize()
            acc["x_fb_times"].append(time.perf_counter()-_fb_start)
        if not math.isfinite(loss_v):
            diverged, fail_reason = True, f"non-finite loss at step {step}"
            log(f"[diverge] {tag}: {fail_reason}")
            break

        pre_clip = torch.nn.utils.clip_grad_norm_(params, GRAD_CLIP_NORM)
        acc["grad_norms"].append(float(pre_clip))          # descriptive
        if float(pre_clip) > CLIP_METRIC_THRESHOLD:
            acc["clip_events"] += 1

        if noise_consumer:
            _pc = float(pre_clip)
            _coef = (GRAD_CLIP_NORM / (_pc + 1e-6)
                     if (math.isfinite(_pc) and _pc > GRAD_CLIP_NORM) else 1.0)
            if _ga is not None:
                _pairs = []
                for p, a, b in zip(params, _ga, _gb):
                    if a is not None and b is not None:
                        _pairs.append((p, (0.5 * (a - b)) * _coef))
                    else:
                        _pairs.append((p, torch.zeros_like(p)))
                optimizer.set_noise(_pairs)
            else:
                optimizer.set_noise([(p, torch.zeros_like(p)) for p in params])
            _ga = _gb = None

        # descriptive: EMA of the train loss + snapshots at 25/50/75% of budget
        if extra:
            _ema = acc["x_spike_ema"]
            _ratio = loss_v / max(abs(_ema), 1e-30) if _ema is not None else 1.
            if step >= 100:
                acc["x_spikes"] += int(_ratio > 3.)
                acc["x_spike_max"] = max(acc["x_spike_max"], _ratio)
            acc["x_spike_ema"] = loss_v if _ema is None else .99*_ema+.01*loss_v
        b = 0.98
        acc["train_loss_ema"] = (loss_v if acc["train_loss_ema"] is None
                                 else b * acc["train_loss_ema"] + (1 - b) * loss_v)
        acc["final_train_loss"] = loss_v
        for _i, _f in enumerate((0.25, 0.5, 0.75)):
            if acc["loss_at"][_i] is None and step + 1 >= int(_f * total_steps):
                acc["loss_at"][_i] = acc["train_loss_ema"]

        if hessian_consumer and (step % HESS_FREQ == 0):
            try:
                _h = hutchinson_diag_hessian(
                    model, params,
                    lambda: forward_loss(model, (inputs, targets), criterion),
                    N_HUTCH, optimizer=optimizer, feed_optimizer=True)
                if _is_finite(optimizer.last_h_norm):
                    acc["hess_norms"].append(float(optimizer.last_h_norm))
                acc["hess_trace_samples"].append(
                    sum(float(h.sum().item()) for h in _h))          # descriptive
            except Exception as e:
                if classify_exception(e) == "env":
                    raise
                log(f"[warn] {tag}: Hutchinson probe failed at step {step} ({e!r})")

        _apply_lr(optimizer, base_lrs, cosine_factor(step, total_steps))
        if _timed:
            if torch.cuda.is_available(): torch.cuda.synchronize()
            _opt_start = time.perf_counter()
        optimizer.step()
        if _timed:
            if torch.cuda.is_available(): torch.cuda.synchronize()
            acc["x_opt_times"].append(time.perf_counter()-_opt_start)
        if speed:
            if torch.cuda.is_available(): torch.cuda.synchronize()
            if step >= 20:
                _speed_times.append(time.perf_counter()-_step_start)
        step += 1
        if math.isfinite(fwd_flops):
            acc["flops"] += 3.0 * fwd_flops + (
                N_HUTCH * 2.0 * fwd_flops
                if (hessian_consumer and (step - 1) % HESS_FREQ == 0) else 0.0)

        if p_before is not None:
            with torch.no_grad():
                dts = [(p.detach() - pb) for p, pb in zip(params, p_before)]
                d_sq = sum(float(x.pow(2).sum().item()) for x in dts)
                th_sq = sum(float(p.detach().pow(2).sum().item()) for p in params)
                flat = torch.cat([x.reshape(-1) for x in dts]).float().cpu()
            acc["step_sq_sum"] += d_sq
            acc["step_sq_n"] = acc.get("step_sq_n", 0) + 1
            acc["theta_sq_sum"] += th_sq
            if d_sq > 0 and th_sq > 0:                     # ||dtheta|| / ||theta||
                acc["uwr_sum"] += math.sqrt(d_sq / th_sq)
                acc["uwr_n"] += 1
            if (prev_delta is not None and prev_delta.numel() == flat.numel()
                    and flat.norm() > 0 and prev_delta.norm() > 0):
                acc["upcos_sum"] += float(torch.dot(flat, prev_delta).item()) / (
                    float(flat.norm()) * float(prev_delta.norm()))
                acc["upcos_n"] += 1
            prev_delta = flat
        p_before = None

        if (step % EVAL_EVERY == 0) or (step == total_steps):
            acc["eval_wall"].append([step, acc["wall"] + (time.time() - t_wall)])
            if extra:
                acc["x_train_loss_curve"].append([step, acc["train_loss_ema"]])
            val_primary, _ = evaluate(model, val_loader, criterion)
            acc["val_curve"].append([step, val_primary])
            if _better(val_primary, best_val):
                best_val = val_primary
                best_state = {k: v.detach().cpu().clone()
                              for k, v in model.state_dict().items()}
            if noise_consumer:
                # Evie-KF mechanism telemetry (optimizer specification sec 4.3.4/4.3.5):
                # descriptive ONLY -- never enters the Wilcoxon/Holm pipeline.
                acc.setdefault("eviekf_diag", []).append({
                    "step": step,
                    "cos": float(getattr(optimizer, "last_cos", float("nan"))),
                    "b_simple": float(getattr(optimizer, "b_simple", float("nan"))),
                    "tr_sigma": float(getattr(optimizer, "tr_sigma", float("nan"))),
                    "eff_rank": float(getattr(optimizer, "eff_rank", float("nan"))),
                    "gain_lo": float(getattr(optimizer, "gain_lo", float("nan"))),
                    "gain_hi": float(getattr(optimizer, "gain_hi", float("nan"))),
                    "n_active_steps": int(getattr(optimizer, "n_active_steps", 0)),
                })
                if extra:
                    for _name in EVIE_EXTRA_KEYS:
                        acc["eviekf_diag"][-1][_name] = float(getattr(optimizer, _name, float("nan")))
                _rg = getattr(optimizer, "role_gain", {}) or {}
                if _rg:
                    acc["eviekf_role_gain"] = {
                        r: [float(v[0]), float(v[1]), float(v[2]), int(v[3])]
                        for r, v in _rg.items()}
            model.train()

        if (step % CKPT_EVERY == 0) and not is_lr_search:
            acc["wall"] += time.time() - t_wall
            save_cell(complete=False)
            t_wall = time.time()

    acc["wall"] += time.time() - t_wall

    if best_state is not None:
        model.load_state_dict(best_state)
    _extra_start=time.monotonic() if extra else None
    _extra_deadline=(_extra_start+(5. if DOMAIN=="finance" else 90.)) if extra else None
    if is_lr_search:
        test_primary, test_aux = float("nan"), {}     # LR pick uses best_val only
    else:
        try:
            if TASK.get("extra_metrics") or TASK.get("opt_set") == "muonhybrid":
                _test_start = time.monotonic()
                test_primary, test_aux = evaluate(model, test_loader, criterion,
                                                  extended_metrics=True, extra_deadline=_extra_deadline)
                test_aux["test_eval_wall_s"] = time.monotonic() - _test_start
            else:
                test_primary, test_aux = evaluate(model, test_loader, criterion)
        except Exception as e:
            if classify_exception(e) == "env":
                raise
            test_primary, test_aux = float("nan"), {}
            diverged, fail_reason = True, f"test eval failed: {e!r}"

    n_params = max(acc["n_params"], 1)
    step_sq_n = max(acc.get("step_sq_n", 0), 1)

    # -------- descriptive-only derived diagnostics (NO significance tests) -----
    vc = acc["val_curve"]
    steps_to_best_val = steps_to_90 = frac_90 = wall_to_90 = auc_val = float("nan")
    if len(vc) >= 2:
        vs = [v for _, v in vc]
        ss = [s for s, _ in vc]
        bi = (min(range(len(vs)), key=lambda i: vs[i]) if PRIMARY_LOWER_BETTER
              else max(range(len(vs)), key=lambda i: vs[i]))
        steps_to_best_val = ss[bi]
        first_v, best_v = vs[0], vs[bi]
        if best_v != first_v:
            for s, v in vc:
                if (v - first_v) / (best_v - first_v) >= 0.9:
                    steps_to_90 = s
                    break
            if _is_finite(steps_to_90):
                frac_90 = steps_to_90 / max(total_steps, 1)
                wall_to_90 = dict((s, w) for s, w in acc["eval_wall"]).get(
                    steps_to_90, float("nan"))
        area = sum(0.5 * (vs[i] + vs[i - 1]) * (ss[i] - ss[i - 1])
                   for i in range(1, len(vc)))
        auc_val = area / max(ss[-1] - ss[0], 1)

    with torch.no_grad():
        w_end = math.sqrt(sum(float(p.detach().pow(2).sum().item())
                              for p in params))
    w0 = acc.get("w0_norm") or w_end
    gn = acc.get("grad_norms", [])
    hts = acc.get("hess_trace_samples", [])
    final_tl = acc.get("final_train_loss", float("nan"))

    hess_top_eig = float("nan")
    if hessian_consumer and not is_lr_search and inputs is not None:
        try:
            hess_top_eig = _power_iteration_top_eig(
                model, params,
                lambda: forward_loss(model, (inputs, targets), criterion), iters=10)
        except Exception as e:
            if classify_exception(e) == "env":
                raise

    result = {
        "opt": opt_name, "unit": unit, "seed": seed, "lr_used": lr,
        "knob_used": knob,
        "primary": test_primary, "best_val_primary": best_val,
        "steps_run": step, "diverged": bool(diverged), "fail_reason": fail_reason,
        "wall_s": acc["wall"],
        "sec_per_step": acc["wall"] / max(step, 1),        # cost column (spec 4.3.6)
        "mean_step_size": math.sqrt(acc["step_sq_sum"] / step_sq_n / n_params),
        "clip_freq": acc["clip_events"] / max(step, 1),
        "peak_mem_mb": (torch.cuda.max_memory_allocated() / 1024 ** 2
                        if torch.cuda.is_available() else float("nan")),
        "hess_norm": (float(np.mean(acc["hess_norms"])) if acc["hess_norms"]
                      else float("nan")),
        "hess_cv": (float(np.std(acc["hess_norms"]) / np.mean(acc["hess_norms"]))
                    if acc["hess_norms"] and np.mean(acc["hess_norms"]) > 0
                    else float("nan")),
        "n_params": n_params,
        "val_curve": acc["val_curve"],
        # ---- descriptive-only diagnostics (see benchmark protocol sec 5: primary metric
        # per domain is the ONLY thing significance-tested; these are appendix /
        # behaviour telemetry, no p-values) ----
        "steps_to_best_val": steps_to_best_val,
        "steps_to_90pct_best": steps_to_90,
        "frac_budget_to_90pct_best": frac_90,
        "wallclock_to_90pct_best_s": wall_to_90,
        "train_loss_at_25pct": acc["loss_at"][0] if acc["loss_at"][0] is not None
                               else float("nan"),
        "train_loss_at_50pct": acc["loss_at"][1] if acc["loss_at"][1] is not None
                               else float("nan"),
        "train_loss_at_75pct": acc["loss_at"][2] if acc["loss_at"][2] is not None
                               else float("nan"),
        "final_train_loss": final_tl,
        "gen_gap_loss": (test_aux.get("test_loss", float("nan")) - final_tl
                         if _is_finite(final_tl) else float("nan")),
        "auc_val_curve": auc_val,
        "update_weight_ratio": (acc["uwr_sum"] / acc["uwr_n"]
                                if acc.get("uwr_n") else float("nan")),
        "update_cos_sim_sampled": (acc["upcos_sum"] / acc["upcos_n"]
                                   if acc.get("upcos_n") else float("nan")),
        "grad_norm_mean": float(np.mean(gn)) if gn else float("nan"),
        "grad_norm_p95": float(np.percentile(gn, 95)) if gn else float("nan"),
        "weight_norm_start": w0,
        "weight_norm_end": w_end,
        "weight_norm_growth": (w_end / w0) if w0 > 0 else float("nan"),
        "throughput_samples_per_s": (step * BATCH_SIZE) / max(acc["wall"], 1e-9),
        "flops_per_step_est": acc.get("flops", 0.0) / max(step, 1),
        "total_flops_est": acc.get("flops", float("nan")),
        "hess_trace": float(np.mean(hts)) if hts else float("nan"),
        "hess_top_eig": hess_top_eig,
    }
    for k in AUX_METRIC_KEYS:
        result[k] = test_aux.get(k, float("nan"))

    # ---- Evie-KF mechanism telemetry (descriptive only, spec sec 4.3.4/4.3.5) --
    _edg = acc.get("eviekf_diag", [])

    def _dstat(key, fn=np.mean):
        _vs = [d[key] for d in _edg if _is_finite(d.get(key))]
        return float(fn(_vs)) if _vs else float("nan")

    _n_active = int(_edg[-1]["n_active_steps"]) if _edg else 0
    result.update({
        "eviekf_cos_mean": _dstat("cos"),
        "eviekf_cos_min": _dstat("cos", np.min),
        "eviekf_b_simple_mean": _dstat("b_simple"),
        "eviekf_tr_sigma_mean": _dstat("tr_sigma"),
        "eviekf_eff_rank_mean": _dstat("eff_rank"),
        "eviekf_gain_lo_min": _dstat("gain_lo", np.min),
        "eviekf_gain_hi_max": _dstat("gain_hi", np.max),
        "eviekf_n_active_steps": _n_active,
        "eviekf_role_gain": acc.get("eviekf_role_gain", {}),
        # The full trace, not just the reductions above. The spec
        # (evie-kf-full-specification.md sec 8.2/sec 12) is explicit: "log raw,
        # analyse afterwards -- never log only a summary statistic", because the
        # mechanism figures (F4: gain spectrum and cos(step, Adam) over training;
        # F5: noise anisotropy) need the trajectory and it cannot be
        # reconstructed from a mean. One dict per eval point (~20-40 per cell),
        # EvieKF-family cells only -- a few KB.
        "eviekf_diag_trace": _edg,
    })
    # n_active_steps == 0 at the end of a real run means set_noise() never fired
    # and Evie-KF silently ran as AdamW -- same severity class as a divergence
    # flag (optimizer specification sec 4.3.4), not a silent zero.
    if (noise_consumer and not is_lr_search
            and step > int(getattr(optimizer, "warmup", EVIEKF_WARMUP)) + 1
            and _n_active == 0):
        diverged = True
        fail_reason = (fail_reason or
                       "Evie-KF noise hook never fired (n_active_steps=0): "
                       "set_noise() wiring bug -- this run was silently AdamW")
        result["diverged"] = True
        result["fail_reason"] = fail_reason
        log(f"[diverge] {tag}: {fail_reason}")

    if TASK.get("opt_set") == "muonhybrid":
        result.update(matrix_lr=TASK["muon_matrix_lr"],
                      tokens_processed=step * BATCH_SIZE * int(TASK.get("ctx", GPT_CTX)),
                      tuning_seed=(seed == LR_SEARCH_SEED),
                      allow_tf32=bool(TASK.get("allow_tf32")),
                      cuda_device=(torch.cuda.get_device_name() if torch.cuda.is_available() else "CPU"),
                      peak_reserved_mem_mb=(torch.cuda.max_memory_reserved() / 1024**2
                                            if torch.cuda.is_available() else float("nan")))
        result["tokens_per_s"] = result["tokens_processed"] / max(result["wall_s"], 1e-9)
        result["eval_wall_curve"] = acc["eval_wall"]
        result["test_eval_wall_s"] = test_aux.get("test_eval_wall_s", float("nan"))
        result["test_perplexity"] = test_primary
        result["optimizer_state_bytes"] = sum(v.numel()*v.element_size()
            for state in optimizer.state.values() for v in state.values() if torch.is_tensor(v))
        result["model_parameter_bytes"] = sum(p.numel()*p.element_size() for p in params)
        mp, ep = split_params_for_muon(model)
        result["muon_parameter_count"] = sum(p.numel() for p in mp)
        result["aux_parameter_count"] = sum(p.numel() for p in ep)
        result["aux_parameter_fraction"] = result["aux_parameter_count"] / n_params
        result["metric_notes"] = {"bits_per_byte": "available only for byte-level enwik8; no evaluated byte denominator for other tokenizers",
                                  "hessian": "unavailable: hybrid arms do not run the Sophia Hessian probe",
                                  "bpc": "legacy field: bits per token, only bits per byte/character for enwik8"}
    if speed:
        result["speed_sec_per_step"] = (sum(_speed_times)/len(_speed_times) if _speed_times else None)
    if extra:
        result.update(eval_wall_curve=acc["eval_wall"], x_train_loss_curve=acc["x_train_loss_curve"],
                      x_resumed=ck is not None, x_loss_spike_count=acc["x_spikes"],
                      x_loss_spike_max_ratio=acc["x_spike_max"],
                      x_grad_norm_max=max(gn) if gn else None,
                      x_grad_norm_p50=float(np.median(gn)) if gn else None,
                      x_grad_norm_cv=float(np.std(gn)/np.mean(gn)) if gn and np.mean(gn)>0 else None,
                      x_opt_time_s=float(np.mean(acc["x_opt_times"])) if acc["x_opt_times"] else None,
                      x_fwdbwd_time_s=float(np.mean(acc["x_fb_times"])) if acc["x_fb_times"] else None,
                      x_opt_state_mb=_tensor_bytes(optimizer.state)/2**20,
                      x_param_mb=4*n_params/2**20, x_errors={})
        _a, _b = result["x_opt_time_s"], result["x_fwdbwd_time_s"]
        result["x_opt_time_frac"] = _a/(_a+_b) if _a is not None and _b is not None and _a+_b>0 else None
        for _k, _v in test_aux.items():
            result[_k] = _v
        result["x_errors"].update(test_aux.get("x_errors", {}))
        result.update(landscape_extras(model, val_loader, criterion, params, _init,
                                      _infer_param_roles(model), result["x_errors"], deadline=_extra_deadline))
        if DOMAIN == "vision":
            _extra_train_accuracy(model, data, criterion, result, deadline=_extra_deadline)
        result["x_end_eval_and_extra_wall_s"]=time.monotonic()-_extra_start
        if DOMAIN == "language":
            result["tokens_per_s"] = step*BATCH_SIZE*int(TASK.get("ctx",GPT_CTX))/max(acc["wall"],1e-9)
        for _name in EVIE_EXTRA_KEYS:
            result["eviekf_"+_name+"_mean"] = _dstat(_name,
                (lambda v:v[-1]) if _name=="eig_refresh_time_s" else np.min if _name=="last_c_min" else np.mean)
        result["eviekf_c_mean"] = result["eviekf_last_c_mean_mean"]
        if ck is not None:
            for _name in ["x_train_loss_curve","x_loss_spike_count","x_loss_spike_max_ratio","x_grad_norm_max", "x_grad_norm_p50", "x_grad_norm_cv", "x_opt_time_s", "x_fwdbwd_time_s", "x_opt_time_frac"]:
                result[_name] = None
                result["x_errors"][_name] = "resumed cell: full-run measurement unavailable"
        for _key, _value in list(result.items()):
            if (_key.startswith("x_") or _key in EXTRA_DOMAIN_KEYS.get(DOMAIN, [])
                    or _key in {"eviekf_"+n+"_mean" for n in EVIE_EXTRA_KEYS} or _key=="eviekf_c_mean") and isinstance(_value, float) and not math.isfinite(_value):
                result[_key] = None
                result["x_errors"].setdefault(_key,"undefined for this sample")
    if is_lr_search:
        # LR selection uses the BEST-checkpoint val metric, never the last step
        # (benchmark protocol sec 6).
        result["lr_search_score"] = best_val
    save_cell(complete=True, result=result)
    return result


# ---------------------------------------------------------------------------
#  LR search: 7-point half-decade grid per optimizer family, tuned at
#  LR_SEARCH_STEPS (~25% of budget), 1 seed; boundary rule -> extend & re-search
#  if the pick lands on a grid edge; then freeze (benchmark protocol sec 5). Optimizers
#  in KNOB_GRID (the Evie-KF family: gamma; Shampoo: beta) get a SECOND axis
#  searched jointly with LR, same discipline (optimizer specification sec 4.3.2).
# ---------------------------------------------------------------------------
def _score_lr(opt_name, data, units, lr, adamw_lr, knob=None):
    # LR-search runs are short (25% budget) and write NO checkpoint -- a full
    # per-probe .pt would be ~100s of MB x dozens of probes. If interrupted, the
    # in-flight grid point is simply re-run; completed points are cached in
    # LR_JSON (see lr_search()).
    scores = []
    for unit in units:
        if TASK.get("extra_metrics") or TASK.get("opt_set") == "muonhybrid":
            try:
                r = train_run(opt_name, data, unit, lr, adamw_lr, LR_SEARCH_STEPS,
                              LR_SEARCH_SEED, ckpt_path=None, is_lr_search=True, knob=knob)
            except Exception as e:
                if classify_exception(e) == "env":
                    raise
                log(f"[lr-search] failed trial {opt_name}/{unit}: {e!r}; continuing grid")
                r = dict(lr_search_score=float("nan"), diverged=True, fail_reason=repr(e))
            audit_path = os.path.join(TASK_DIR, "search_audit.json")
            audit = _read_json(audit_path, {})
            audit[f"{opt_name}|{unit}|{lr:.6e}|{knob}"] = r
            _write_json(audit_path, audit)
        else:
            r = train_run(opt_name, data, unit, lr, adamw_lr, LR_SEARCH_STEPS,
                          LR_SEARCH_SEED, ckpt_path=None, is_lr_search=True, knob=knob)
        s = (float("nan") if TASK.get("extra_metrics") and r.get("diverged") else r["lr_search_score"])
        if _is_finite(s) and not _absurd_primary(s):
            scores.append(s)
    if not scores:
        return math.inf if PRIMARY_LOWER_BETTER else -math.inf
    return float(np.median(scores))


def _safe(s):
    return "".join(c if c.isalnum() or c in "-._" else "_" for c in str(s))


def search_lr_for(opt_name, data, units, adamw_lr, log_prefix="", knob=None):
    """One optimizer's 7-point half-decade LR grid + boundary-extend rule
    (benchmark protocol sec 5). Returns (best_lr, tried_scores, boundary_checks). Used by
    lr_search() below and by the batch/model-size sweep drivers. `knob` (if
    given) is the fixed second-axis value the cells will run at -- the sweeps
    pass it so the LR is tuned at the SAME knob the sweep cell uses, not at
    build_optimizer()'s default. Writes no state -- the caller persists."""
    tried = {}

    def _eval(lrs):
        for lr in lrs:
            if lr in tried and _is_finite(tried[lr]):
                continue
            tried[lr] = _score_lr(opt_name, data, units, lr, adamw_lr, knob=knob)
            log(f"{log_prefix}[lr-search] {opt_name}  lr={lr:.3e}  "
                f"score={tried[lr]:.6g}")

    def _pick():
        return (min(tried, key=tried.get) if PRIMARY_LOWER_BETTER
                else max(tried, key=tried.get))

    grid = sorted(half_decade_grid(LR_GRID_CENTRE[opt_name]))
    _eval(grid)
    best = _pick()
    bchecks = 0
    while best in (grid[0], grid[-1]) and bchecks < 3:
        bchecks += 1
        r = 10.0 ** 0.5
        ext = [float(f"{(best / r ** k) if best == grid[0] else (best * r ** k):.4g}")
               for k in (1, 2)]
        log(f"{log_prefix}[lr-search] {opt_name}: pick {best:.3e} at grid edge -> "
            f"extend with {ext} and re-search (boundary check #{bchecks})")
        _eval(ext)
        grid = sorted(tried)
        best = _pick()
    return float(best), tried, bchecks


def _joint_lr_knob_search(opt_name, data, units, adamw_lr, prior, persist):
    """LR grid x optional knob grid (KNOB_GRID). Scored at LR_SEARCH_STEPS / 1
    seed on the best-checkpoint val metric (benchmark protocol sec 6). Boundary-extend on
    BOTH axes: if the LR pick lands on a grid edge, extend the LR grid at the
    chosen knob and re-search; likewise extend the knob grid at the chosen LR
    (optimizer specification sec 4.3.2 -- gamma=100 was edge-pinned once already at PoC
    scale). Returns (best_lr, best_knob, b_lr, b_knob)."""
    explicit = (TASK.get("search_grid") or {}).get(opt_name)
    if opt_name in ("MuonSub", "MuonEvie") and not explicit:
        raise ValueError(f"{opt_name} requires an explicit fixed search grid")
    knobs = KNOB_GRID.get(opt_name)
    # FIXED knob (TASK["fixed_knob"]): search the LR grid ONLY, at a stated
    # second-axis value. This is the "same tuning budget as the baselines" arm
    # -- 7 LR points and a default gamma, instead of the joint 49-99-point
    # search -- so the knob grid collapses to one value and the knob
    # boundary-extend rule does not apply (there is no grid to be at the edge
    # of). Written into lr_search.json via knob_grid so the provenance travels.
    knob_fixed = (TASK.get("fixed_knob") or {}).get(opt_name)
    if knob_fixed is not None:
        knobs = [float(knob_fixed)]
    knob_vals = [None] if knobs is None else [float(k) for k in knobs]
    # FIXED lr (TASK["fixed_lr"]): the mirror image -- pin the learning rate at a
    # stated value and search the second axis only. Used where the question is
    # about the knob itself (does gamma transfer across tasks?) and re-tuning lr
    # would confound the answer. The LR boundary rule does not apply for the same
    # reason it does not under fixed_knob: there is no grid to sit at the edge of.
    lr_fixed = (TASK.get("fixed_lr") or {}).get(opt_name)
    lr_vals = ([float(lr_fixed)] if lr_fixed is not None
               else sorted(half_decade_grid(LR_GRID_CENTRE[opt_name])))
    if explicit:
        lr_vals = [float(v) for v in explicit["lr"]]
        knob_vals = [None if v is None else float(v) for v in explicit["knob"]]
        if not lr_vals or not knob_vals or any(not math.isfinite(v) or v <= 0
                                               for v in lr_vals + [k for k in knob_vals if k is not None]):
            raise ValueError("Hybrid search grid must contain finite positive values")
    scored = dict(prior.get("scored", {}))              # "lr|knob" -> median score
    b_lr = int(prior.get("boundary_checks_lr", 0))
    b_knob = int(prior.get("boundary_checks_knob", 0))

    def _key(lr, kn):
        return f"{lr:.6e}|{'none' if kn is None else format(kn, '.6e')}"

    def _ensure():
        for lr in lr_vals:
            for kn in knob_vals:
                k = _key(lr, kn)
                if k in scored and (explicit or TASK.get("budget_no_extend") or _is_finite(scored[k])):
                    continue
                scored[k] = _score_lr(opt_name, data, units, float(lr), adamw_lr,
                                      knob=kn)
                log(f"[lr-search] {opt_name}  lr={lr:.3e}  "
                    f"knob={'-' if kn is None else format(kn, 'g')}  "
                    f"score={scored[k]:.6g}")
                persist(scored, b_lr, b_knob, lr_vals, knob_vals, complete=False)

    def _best():
        pick, pv = None, (math.inf if PRIMARY_LOWER_BETTER else -math.inf)
        for lr in lr_vals:
            for kn in knob_vals:
                s = scored.get(_key(lr, kn))
                if not _is_finite(s):
                    continue
                if (s < pv) if PRIMARY_LOWER_BETTER else (s > pv):
                    pv, pick = s, (lr, kn)
        return pick or (lr_vals[len(lr_vals) // 2], knob_vals[0])

    _ensure()
    bl, bk = _best()
    if (explicit or TASK.get("budget_no_extend")) and not any(_is_finite(v) for v in scored.values()):
        raise RuntimeError(f"{opt_name}: all fixed-grid trials failed; no frozen choice is valid")
    while not explicit and not TASK.get("budget_no_extend") and lr_fixed is None and bl in (lr_vals[0], lr_vals[-1]) and b_lr < 3:
        b_lr += 1
        r = 10.0 ** 0.5
        at_low = (bl == lr_vals[0])
        ext = [float(f"{(bl / r ** k) if at_low else (bl * r ** k):.4g}")
               for k in (1, 2)]
        log(f"[lr-search] {opt_name}: LR pick {bl:.3e} at grid edge -> extend "
            f"{ext} and re-search (boundary check #{b_lr})")
        lr_vals = sorted(set(lr_vals) | set(ext))
        _ensure()
        bl, bk = _best()
    if not explicit and not TASK.get("budget_no_extend") and knobs is not None and knob_fixed is None:
        while bk in (knob_vals[0], knob_vals[-1]) and b_knob < 3:
            b_knob += 1
            ext = knob_grid_extend(knob_vals, at_low=(bk == knob_vals[0]))
            if not ext:
                break
            log(f"[lr-search] {opt_name}: knob pick {bk:g} at grid edge -> extend "
                f"{ext} and re-search (boundary check #{b_knob})")
            knob_vals = sorted(set(knob_vals) | set(ext))
            _ensure()
            bl, bk = _best()
    persist(scored, b_lr, b_knob, lr_vals, knob_vals, complete=True,
            lr=bl, knob=bk)
    return float(bl), (None if bk is None else float(bk)), b_lr, b_knob


def _adamw_lr(lr_used):
    return lr_used.get("AdamW") if "AdamW" in lr_used else lr_used.get("AdamWwd")


def lr_search(data):
    cached = _read_json(LR_JSON, {})
    lr_used, knob_used = {}, {}
    for k, v in cached.items():
        if isinstance(v, dict) and v.get("complete") and "lr" in v:
            lr_used[k] = float(v["lr"])
            knob_used[k] = (None if v.get("knob") is None else float(v["knob"]))
    units = lr_search_units(data)
    log_sep("-")

    # PINNED (lr, knob): a diagnostic file states the hyper-parameters instead of
    # searching for them, so the question it asks ("does this arm behave
    # differently at THIS lr?") is not re-contaminated by another noisy search.
    # Pinned values are written into lr_search.json with pinned=true so the
    # provenance travels with the results.
    for opt_name, pin in (TASK.get("pinned_lr") or {}).items():
        if opt_name not in ACTIVE_OPT_NAMES:
            continue
        lr_used[opt_name] = float(pin["lr"])
        knob_used[opt_name] = (None if pin.get("knob") is None
                               else float(pin["knob"]))
        cached[opt_name] = {"lr": lr_used[opt_name], "knob": knob_used[opt_name],
                            "grid": {}, "complete": True, "pinned": True,
                            "pinned_note": pin.get("note", "")}
        _write_json(LR_JSON, cached)
        log(f"[lr-search] {opt_name}: PINNED lr={lr_used[opt_name]:.3e}"
            + ("" if knob_used[opt_name] is None
               else f"  knob={knob_used[opt_name]:g}")
            + "  (no search on this arm)"
            + (f"  -- {pin['note']}" if pin.get("note") else ""))

    log(f"[lr-search] units={units}  steps={LR_SEARCH_STEPS}  seed={LR_SEARCH_SEED}"
        f"  optimizers={ACTIVE_OPT_NAMES}")

    # Muon's AdamW sub-group runs at AdamW's frozen lr, so Muon cannot be searched
    # until AdamW has been. In a single whole-task run that is guaranteed by
    # OPT_NAMES' order. When the task is split across machines with BENCH12_ARMS,
    # it is not -- so Muon's machine must be given a checkpoint in which AdamW's
    # search is already complete, and this is where that is checked. Failing here
    # with a sentence beats silently training Muon's AdamW group at Muon's own lr,
    # which is a ~20x wrong learning rate and would look like a divergence.
    if ((not TASK.get("extra_metrics") and "Muon" in ACTIVE_OPT_NAMES and lr_used.get("AdamW") is None)
            or (TASK.get("extra_metrics") and any(a in ACTIVE_OPT_NAMES for a in ("Muon", "Muonwd"))
                and _adamw_lr(lr_used) is None and not any(a in ACTIVE_OPT_NAMES for a in ("AdamW", "AdamWwd")))):
        raise SystemExit(
            "Muon needs AdamW's frozen lr and this run does not have it. Either "
            "run AdamW in the same job (BENCH12_ARMS=AdamW,Muon), or attach a "
            "checkpoint whose lr_search.json already has AdamW complete -- the "
            "AdamW machine's PAUSED/DONE archive does exactly that.")

    for opt_name in ACTIVE_OPT_NAMES:
        if opt_name == "MuonEvieFix" and opt_name not in lr_used:
            source = cached.get("MuonEvie", {})
            if not source.get("complete"):
                raise ValueError("MuonEvieFix requires completed MuonEvie search; run MuonEvie first")
            trials = [(float(v), float(k.split("|")[0]))
                      for k, v in source.get("grid", {}).items()
                      if float(k.split("|")[1]) == 30.0 and _is_finite(v)]
            if not trials:
                raise ValueError("MuonEvieFix: no valid gamma=30 search trials")
            selected = (min if PRIMARY_LOWER_BETTER else max)(trials, key=lambda x: x[0])
            lr_used[opt_name], knob_used[opt_name] = selected[1], 30.0
            cached[opt_name] = dict(lr=selected[1], knob=30.0, complete=True,
                                    derived_from="MuonEvie", grid={})
            _write_json(LR_JSON, cached)
        if opt_name in lr_used:
            log(f"[lr-search] {opt_name}: cached lr={lr_used[opt_name]:.3e}"
                + ("" if knob_used.get(opt_name) is None
                   else f"  knob={knob_used[opt_name]:g}"))
            continue
        adamw_lr = _adamw_lr(lr_used)            # Muon reuses frozen AdamW lr
        entry = (cached.get(opt_name) if isinstance(cached.get(opt_name), dict)
                 else {})
        prior = {
            "scored": entry.get("grid", {}) or {},
            "boundary_checks_lr": entry.get("boundary_checks_lr", 0),
            "boundary_checks_knob": entry.get("boundary_checks_knob", 0),
        }

        def _persist(scored, blr, bknob, lrv, knv, complete, lr=None, knob=None):
            cached[opt_name] = {
                "grid": scored,
                "boundary_checks_lr": blr, "boundary_checks_knob": bknob,
                "centre": LR_GRID_CENTRE[opt_name],
                "lr_grid": [float(x) for x in lrv],
                "knob_grid": (None if knv == [None] else [float(x) for x in knv]),
                "complete": bool(complete),
            }
            if complete:
                cached[opt_name]["lr"] = float(lr)
                cached[opt_name]["knob"] = (None if knob is None else float(knob))
            _write_json(LR_JSON, cached)

        best_lr, best_knob, blr, bknob = _joint_lr_knob_search(
            opt_name, data, units, adamw_lr, prior, _persist)
        lr_used[opt_name] = best_lr
        knob_used[opt_name] = best_knob
        log(f"[lr-search] {opt_name}: FROZEN lr={best_lr:.3e}"
            + ("" if best_knob is None else f"  knob={best_knob:g}")
            + f"  (LR boundary checks: {blr}, knob boundary checks: {bknob})")
    log("[lr-search] frozen: " + ", ".join(
        f"{k}={lr_used[k]:.3e}" + ("" if knob_used.get(k) is None
                                   else f"/k={knob_used[k]:g}")
        for k in ACTIVE_OPT_NAMES))
    return lr_used, knob_used


# ---------------------------------------------------------------------------
#  Main sweep
# ---------------------------------------------------------------------------
def run_sweep(data, lr_used, knob_used=None):
    knob_used = knob_used or {}
    results = _read_json(RESULTS_JSON, {"cells": {}, "meta": {}})
    cells = results["cells"]
    units = main_units(data)
    _all_units = list(units)
    _slice = os.environ.get("BENCH12_UNIT_SLICE")
    if _slice:
        try:
            _k,_n = map(int,_slice.split("/"))
            if not (0 <= _k < _n): raise ValueError()
        except ValueError:
            fail("BENCH12_UNIT_SLICE must be k/n with 0 <= k < n")
        units = units[_k::_n]
    if TASK.get("opt_set") == "muonhybrid":
        results["meta"].update(task_name=TASK_NAME, units=units, seeds=SEEDS,
                               opt_names=list(ACTIVE_OPT_NAMES), opt_set="muonhybrid",
                               primary_metric=PRIMARY_METRIC, lr_used=lr_used,
                               knob_used=knob_used, ref_opt="MuonSub",
                               expected_tasks=4, task_config=TASK, smoke=SMOKE,
                               data_provenance=data.get("provenance"))
        _write_json(RESULTS_JSON, results)
    total = len(ACTIVE_OPT_NAMES) * len(units) * len(SEEDS)
    log_sep("-")
    log(f"[sweep] {len(ACTIVE_OPT_NAMES)} optimizers x {len(units)} units x "
        f"{len(SEEDS)} seeds = {total} cells")

    done = 0
    alias_logged = False
    planned = [(a,u,s) for a in ACTIVE_OPT_NAMES for u in units for s in SEEDS]
    cell_slice = os.environ.get("BENCH12_CELL_SLICE")
    if cell_slice:
        _ck,_cn = _parse_slice(cell_slice,"BENCH12_CELL_SLICE")
        planned.sort(key=lambda c:(c[2],ACTIVE_OPT_NAMES.index(c[0]),str(c[1])))
        planned = [c for i,c in enumerate(planned) if i % _cn == _ck]
        total=len(planned)
        log(f"[cell-shard] {cell_slice}: {total} assigned cells")
    results["meta"].update(task_name=TASK_NAME, domain=DOMAIN, units=units, all_units=_all_units,
        seeds=SEEDS,opt_names=list(ACTIVE_OPT_NAMES),cell_slice=cell_slice,
        shard_tag=os.environ.get("BENCH12_SHARD_TAG",""),lr_used=lr_used,knob_used=knob_used,
        expected_cell_keys=[f"{a}|{u}|{s}" for a in ACTIVE_OPT_NAMES for u in _all_units for s in SEEDS],
        task_config=TASK,smoke=SMOKE,opt_set=TASK.get("opt_set","main"))
    if cell_slice or os.environ.get("BENCH12_SHARD_TAG"):
        _write_json(RESULTS_JSON,results)
    for opt_name, unit, seed in planned:
        ckey = f"{opt_name}|{unit}|{seed}"
        if ckey in cells and cells[ckey].get("recorded"):
            done += 1
            continue
        source_key = f"MuonEvie|{unit}|{seed}"
        if (opt_name == "MuonEvieFix"
                and lr_used.get(opt_name) == lr_used.get("MuonEvie")
                and knob_used.get(opt_name) == knob_used.get("MuonEvie")
                and cells.get(source_key, {}).get("recorded")):
            cells[ckey] = copy.deepcopy(cells[source_key])
            cells[ckey].update(opt=opt_name, aliased_from=source_key, recorded=True)
            if not alias_logged:
                log("[alias] MuonEvieFix reuses identical MuonEvie cells; paired difference is zero by construction")
                alias_logged = True
            done += 1
            _write_json(RESULTS_JSON, results)
            continue
        if (cell_slice and opt_name == "MuonEvieFix"
                and lr_used.get(opt_name)==lr_used.get("MuonEvie")
                and knob_used.get(opt_name)==knob_used.get("MuonEvie")):
            cells[ckey]=dict(opt=opt_name,unit=unit,seed=seed,deferred=True,
                aliased_from=source_key,recorded=False)
            log(f"[deferred] {ckey}: source {source_key} belongs to another shard")
            _write_json(RESULTS_JSON,results)
            continue
        if torch.cuda.is_available():
            torch.cuda.reset_peak_memory_stats()
        ckpt = os.path.join(CELL_DIR,
                            f"{_safe(opt_name)}__{_safe(unit)}__seed{seed}.pt")
        cell_started = time.monotonic()
        try:
            r = train_run(opt_name, data, unit, lr_used[opt_name],
                          _adamw_lr(lr_used), MAX_STEPS, seed, ckpt,
                          is_lr_search=False, knob=knob_used.get(opt_name))
            r["recorded"] = True
            if _absurd_primary(r["primary"]):
                r["diverged"] = True
                r["fail_reason"] = (r.get("fail_reason")
                                    or "primary outside absolute sane range")
            cells[ckey] = r
        except SystemExit:
            raise
        except Exception as e:
            kind = classify_exception(e)
            if kind == "env":
                log(f"[sweep] ENVIRONMENT error in {ckey}: {e!r}")
                log(traceback.format_exc())
                fail(f"environment/CUDA error while running {ckey}: {e!r}. "
                     f"This is NOT a diverged run -- fix the environment. "
                     f"Completed cells are safe; re-run to resume.")
            log(f"[sweep] numerical failure in {ckey}: {e!r} -> marking "
                f"cell failed, continuing")
            log(traceback.format_exc())
            cells[ckey] = {
                "opt": opt_name, "unit": unit, "seed": seed,
                "lr_used": lr_used[opt_name],
                "knob_used": knob_used.get(opt_name),
                "primary": float("nan"),
                "diverged": True, "fail_reason": f"exception: {e!r}",
                "recorded": True,
            }
            if TASK.get("finance_holdout"):
                cells[ckey]["wall_s"] = time.monotonic() - cell_started
        done += 1
        _write_json(RESULTS_JSON, results)
        if TASK.get("opt_set") == "muonhybrid":
            write_metrics([RESULTS_JSON], os.path.join(TASK_DIR, "metrics.csv"))
        log(f"[sweep] {done}/{total}  {ckey}  "
            f"primary={cells[ckey].get('primary')}  "
            f"diverged={cells[ckey].get('diverged')}")

    # ---- peer-relative divergence pass (benchmark protocol sec 6): a cell broken from
    # early on has no 'own best' to compare against, so compare to peers. ----
    healthy = [c["primary"] for c in cells.values()
               if not c.get("deferred") and not c.get("diverged") and _is_finite(c.get("primary"))]
    peer_median = float(np.median(healthy)) if healthy else None
    if peer_median is not None and not TASK.get("finance_holdout"):
        for ckey, c in cells.items():
            if not c.get("deferred") and not c.get("diverged") and _absurd_primary(c.get("primary"), peer_median):
                c["diverged"] = True
                c["fail_reason"] = (c.get("fail_reason")
                                    or f"primary {c.get('primary'):.4g} is "
                                       f">{PEER_DIVERGENCE_FACTOR}x off the task "
                                       f"peer median {peer_median:.4g}")
                log(f"[diverge] {ckey}: {c['fail_reason']}")
    results["meta"] = {
        "task_name": TASK_NAME, "domain": DOMAIN, "primary_metric": PRIMARY_METRIC,
        "primary_lower_better": PRIMARY_LOWER_BETTER, "lr_used": lr_used,
        "knob_used": knob_used, "opt_names": list(ACTIVE_OPT_NAMES),
        "opt_set": TASK.get("opt_set", "main"),
        "seeds": SEEDS, "max_steps": MAX_STEPS, "units": units,
        "all_units": _all_units, "unit_slice": _slice,
        "cell_slice": cell_slice, "shard_tag": os.environ.get("BENCH12_SHARD_TAG",""),
        "expected_cell_keys": [f"{a}|{u}|{s}" for a in ACTIVE_OPT_NAMES for u in _all_units for s in SEEDS],
        "peer_median_primary": peer_median,
        "nonstandard_ppl_caveat": TASK.get("nonstandard_ppl_caveat"),
        "torch": torch.__version__, "device": str(DEVICE),
        "timestamp": datetime.now().isoformat(),
    }
    if TASK.get("extra_metrics"):
        results["meta"].update(task_config=TASK,smoke=SMOKE,extra_metrics=True,
                               data_provenance=data.get("provenance"), dropped_tickers=data.get("dropped_tickers",[]),
                               effective_tf32=bool(torch.backends.cuda.matmul.allow_tf32),
                               extra_metrics_label="EXPLORATORY: no secondary-metric p-values")
    if TASK.get("opt_set") == "muonhybrid":
        results["meta"].update(ref_opt="MuonSub", task_config=TASK, smoke=SMOKE,
                               data_provenance=data.get("provenance"),
                               expected_tasks=4,
                               cuda_device=(torch.cuda.get_device_name() if torch.cuda.is_available() else "CPU"),
                               cuda_total_memory_mb=(torch.cuda.get_device_properties(0).total_memory / 1024**2
                                                     if torch.cuda.is_available() else None))
    _write_json(RESULTS_JSON, results)
    if TASK.get("opt_set") == "muonhybrid":
        write_metrics([RESULTS_JSON], os.path.join(TASK_DIR, "metrics.csv"))
    return results


# ---------------------------------------------------------------------------
#  Aggregation + per-task descriptive report. Cross-12-task Wilcoxon lives in
#  benchmark12/aggregate.py; per file we still print the one-task picture and a
#  paired Wilcoxon across UNITS when a task has >=6 of them (finance panels).
# ---------------------------------------------------------------------------
def _cell_ok(cells, opt_name, unit, seed):
    c = cells.get(f"{opt_name}|{unit}|{seed}")
    return bool(c) and not c.get("diverged") and _is_finite(c.get("primary"))


def _complete_units(cells, units):
    """The PAIRED complete-case unit set: a unit survives only if every
    optimizer produced a finite, non-diverged cell there at every seed.

    Why, and why this is not fussiness: the old behaviour reduced over whatever
    cells happened to be healthy, per optimizer independently. That silently
    REWARDS instability -- an optimizer that blows up on the 15 hardest tickers
    of a 49-ticker panel gets its panel number computed over the 34 easy ones it
    survived, and then looks better than an optimizer that finished all 49. It
    is the same class of bug benchmark protocol sec 6 flags twice. Dropping a unit for
    EVERY optimizer whenever ANY optimizer failed there keeps the comparison
    paired, which is what the whole design rests on.
    """
    return [u for u in units
            if all(_cell_ok(cells, o, u, s)
                   for o in ACTIVE_OPT_NAMES for s in SEEDS)]


def _cell_value_by_seed(cells, opt_name, units, how="median"):
    """Reduction over units of the test primary, per seed -> {seed: value}.

    Default reduction is the MEDIAN, not the mean. Finance panel MSE is in raw
    squared-log-return units -- _build_ticker_arrays() standardises X but never
    the target y -- so per-ticker scale spans an order of magnitude by
    volatility, and a mean over ~49 tickers is dominated by the handful of most
    volatile ones. Vision and language have a single unit ("full"), where median
    and mean are identical, so this changes nothing outside finance. The mean is
    still computed and reported, descriptively.
    """
    red = np.median if how == "median" else np.mean
    out = {}
    for seed in SEEDS:
        vals = [cells[f"{opt_name}|{unit}|{seed}"]["primary"]
                for unit in units if _cell_ok(cells, opt_name, unit, seed)]
        out[seed] = float(red(vals)) if vals else float("nan")
    return out


def aggregate_and_report(results):
    cells = results["cells"]
    units = results["meta"]["units"]
    lr_used = results["meta"]["lr_used"]
    knob_used = results["meta"].get("knob_used", {}) or {}

    log_sep("=")
    log(f"  RESULTS  --  {TASK_NAME}   primary = {PRIMARY_METRIC} "
        f"({'lower' if PRIMARY_LOWER_BETTER else 'higher'} is better)")
    if TASK.get("nonstandard_ppl_caveat"):
        log(f"  [CAVEAT] {TASK['nonstandard_ppl_caveat']}")
    log_sep("-")

    # ---- paired complete-case unit set (see _complete_units) ---------------
    units_c = _complete_units(cells, units)
    dropped = [u for u in units if u not in units_c]
    biased_fallback = False
    if not units_c:
        biased_fallback = True
        units_c = units
        log("  [WARNING] no unit survived the paired complete-case filter -- "
            "EVERY unit had at least one diverged/failed cell. Falling back to "
            "per-optimizer healthy cells, which is SURVIVORSHIP-BIASED in favour "
            "of whichever optimizer failed most. Do not report these numbers "
            "without saying so; go read the divergence reasons first.")
    elif dropped:
        log(f"  [complete-case] using {len(units_c)}/{len(units)} units; dropped "
            f"{len(dropped)} where some optimizer diverged or failed: "
            f"{dropped[:12]}{' ...' if len(dropped) > 12 else ''}")
        log("  (dropped for ALL optimizers, not just the failing one -- keeps the "
            "comparison paired; see benchmark protocol sec 6)")

    task_number = {}
    task_number_mean = {}
    per_seed = {}
    for opt_name in ACTIVE_OPT_NAMES:
        by_seed = _cell_value_by_seed(cells, opt_name, units_c, how="median")
        per_seed[opt_name] = by_seed
        finite = [v for v in by_seed.values() if _is_finite(v)]
        task_number[opt_name] = float(np.median(finite)) if finite else float("nan")
        _mn = [v for v in _cell_value_by_seed(cells, opt_name, units_c,
                                              how="mean").values() if _is_finite(v)]
        task_number_mean[opt_name] = float(np.median(_mn)) if _mn else float("nan")
        n_div = sum(1 for u in units for s in SEEDS
                    if cells.get(f"{opt_name}|{u}|{s}", {}).get("diverged"))
        aux_bits = []
        for k in ("wall_s", "mean_step_size", "clip_freq", "peak_mem_mb"):
            vs = [cells[f"{opt_name}|{u}|{s}"].get(k) for u in units for s in SEEDS
                  if f"{opt_name}|{u}|{s}" in cells]
            vs = [v for v in vs if _is_finite(v)]
            if vs:
                aux_bits.append(f"{k}={np.mean(vs):.4g}")
        _kb = knob_used.get(opt_name)
        log(f"  {opt_name:<10}  lr={lr_used.get(opt_name, float('nan')):.2e}"
            + ("" if _kb is None else f"  knob={_kb:g}") + "  "
            f"{PRIMARY_METRIC}(task median over {len(SEEDS)} seeds)="
            f"{task_number[opt_name]:.6g}   "
            f"seed spread={_fmt_spread(finite)}   diverged_cells={n_div}/"
            f"{len(units) * len(SEEDS)}")
        if len(units) > 1:
            log(f"             descriptive: unit-MEAN variant="
                f"{task_number_mean[opt_name]:.6g}  (primary uses the unit-MEDIAN; "
                f"y is not target-standardised, so a mean over units is dominated "
                f"by the highest-variance ones)")
        log(f"             descriptive: " + "  ".join(aux_bits))

    finite_task = {k: v for k, v in task_number.items() if _is_finite(v)}
    if finite_task:
        best_opt = (min(finite_task, key=finite_task.get) if PRIMARY_LOWER_BETTER
                    else max(finite_task, key=finite_task.get))
        log_sep("-")
        log(f"  best optimizer on this task: {best_opt}  "
            f"({PRIMARY_METRIC}={finite_task[best_opt]:.6g})")

    # optional within-task paired test across units (finance panels: ~30 tickers)
    ref = TASK.get("ref_opt") or ("AdamW" if "AdamW" in ACTIVE_OPT_NAMES else ACTIVE_OPT_NAMES[0])
    if len(units_c) >= 6:
        log_sep("-")
        log(f"  within-task paired Wilcoxon across {len(units_c)} complete-case "
            f"units (seed-median per unit), reference = {ref}:")
        ref_by_unit = _unit_medians(cells, ref, units_c)
        for opt_name in ACTIVE_OPT_NAMES:
            if opt_name == ref:
                continue
            opt_by_unit = _unit_medians(cells, opt_name, units_c)
            pairs = [(a, b) for a, b in zip(opt_by_unit, ref_by_unit)
                     if _is_finite(a) and _is_finite(b)]
            if len(pairs) < 6:
                log(f"    {opt_name:<10} vs {ref}: too few paired units")
                continue
            a = np.array([p[0] for p in pairs]); b = np.array([p[1] for p in pairs])
            try:
                w_p = wilcoxon(a, b).pvalue
            except ValueError:
                w_p = float("nan")
            better = int(np.sum((a < b) if PRIMARY_LOWER_BETTER else (a > b)))
            med_delta = float(np.median(a - b))
            log(f"    {opt_name:<10} vs {ref}: median Δ={med_delta:+.4g}  "
                f"wins {better}/{len(pairs)}  wilcoxon p={w_p:.3g}  "
                f"(descriptive; the confirmatory test is the 12-task one)")

    _write_csv(cells, units)
    summary = {
        "task_name": TASK_NAME, "primary_metric": PRIMARY_METRIC,
        "primary_lower_better": PRIMARY_LOWER_BETTER,
        "opt_set": TASK.get("opt_set", "main"),
        "opt_names": list(ACTIVE_OPT_NAMES),
        "task_number_by_optimizer": task_number,
        "task_number_unit_mean_by_optimizer": task_number_mean,   # descriptive
        "per_seed_value_by_optimizer": per_seed,
        "lr_used": lr_used, "knob_used": knob_used, "units": units, "seeds": SEEDS,
        # complete-case bookkeeping -- report these in the paper, they are the
        # audit trail for how divergences were handled (benchmark protocol sec 6)
        "unit_reduction": "median",
        "units_complete_case": units_c,
        "n_units_total": len(units),
        "n_units_complete_case": len(units_c),
        "units_dropped_incomplete": dropped,
        "complete_case_fallback_biased": biased_fallback,
        "nonstandard_ppl_caveat": TASK.get("nonstandard_ppl_caveat"),
        # deviations a diagnostic file may declare -- None on every protocol
        # task, so a reader can tell a pinned/limit-raised re-run apart from a
        # protocol number without reading the file's docstring
        "pinned_lr": TASK.get("pinned_lr"),
        "fixed_knob": TASK.get("fixed_knob"),
        "eviekf_maxf": TASK.get("eviekf_maxf"),
    }
    _write_json(os.path.join(TASK_DIR, "summary.json"), summary)
    log_sep("=")
    log(f"  wrote {os.path.join(TASK_DIR, 'summary.json')} "
        f"(consumed by benchmark12/aggregate.py for the 12-task test)")
    log_sep("=")
    return summary


def _unit_medians(cells, opt_name, units):
    out = []
    for unit in units:
        vs = [cells[f"{opt_name}|{unit}|{s}"]["primary"] for s in SEEDS
              if f"{opt_name}|{unit}|{s}" in cells
              and not cells[f"{opt_name}|{unit}|{s}"].get("diverged")
              and _is_finite(cells[f"{opt_name}|{unit}|{s}"].get("primary"))]
        out.append(float(np.median(vs)) if vs else float("nan"))
    return out


def _fmt_spread(vals):
    if not vals:
        return "n/a"
    return f"[{min(vals):.5g}, {max(vals):.5g}]"


def _write_csv(cells, units):
    import csv
    cols = ["opt", "unit", "seed", "lr_used", "knob_used", "primary",
            "best_val_primary",
            "diverged", "fail_reason", "steps_run", "wall_s", "sec_per_step",
            "mean_step_size",
            "clip_freq", "peak_mem_mb", "hess_norm", "hess_cv", "n_params",
            # descriptive-only diagnostics (no p-values -- benchmark protocol sec 5)
            "steps_to_best_val", "steps_to_90pct_best",
            "frac_budget_to_90pct_best", "wallclock_to_90pct_best_s",
            "train_loss_at_25pct", "train_loss_at_50pct", "train_loss_at_75pct",
            "final_train_loss", "gen_gap_loss", "auc_val_curve",
            "update_weight_ratio", "update_cos_sim_sampled",
            "grad_norm_mean", "grad_norm_p95",
            "weight_norm_start", "weight_norm_end", "weight_norm_growth",
            "throughput_samples_per_s", "flops_per_step_est", "total_flops_est",
            "hess_trace", "hess_top_eig",
            # Evie-KF mechanism telemetry (descriptive -- optimizer specification 4.3.4/5)
            "eviekf_cos_mean", "eviekf_cos_min", "eviekf_b_simple_mean",
            "eviekf_tr_sigma_mean", "eviekf_eff_rank_mean", "eviekf_gain_lo_min",
            "eviekf_gain_hi_max", "eviekf_n_active_steps"] \
        + list(AUX_METRIC_KEYS)
    with open(CSV_PATH, "w", newline="") as fh:
        w = csv.DictWriter(fh, fieldnames=cols, extrasaction="ignore")
        w.writeheader()
        for opt_name in ACTIVE_OPT_NAMES:
            for unit in units:
                for seed in SEEDS:
                    c = cells.get(f"{opt_name}|{unit}|{seed}")
                    if c:
                        w.writerow(c)
    log(f"  wrote {CSV_PATH}")


def _hybrid_manifest(data):
    """Pin data and protocol to prevent accidentally resuming different runs."""
    provenance = {}
    arrays = []
    if DOMAIN == "finance":
        arrays = [(str(unit)+"/"+str(i), arr) for unit,values in sorted(data["cache"].items()) for i,arr in enumerate(values)]
    else:
        for split in ("train", "val", "test"):
            values=data[split] if DOMAIN == "vision" else [data[split]]
            arrays.extend((split+"/"+str(i),arr) for i,arr in enumerate(values))
    for split, values in arrays:
        arr = np.ascontiguousarray(values)
        view = memoryview(arr).cast("B")
        sha = hashlib.sha256()
        for start in range(0, len(view), 8*1024*1024):
            sha.update(view[start:start+8*1024*1024])
        provenance[split] = dict(shape=list(arr.shape), dtype=str(arr.dtype), sha256=sha.hexdigest())
    data["provenance"] = provenance
    manifest = dict(task=TASK, smoke=SMOKE, batch_size=BATCH_SIZE,
                    max_steps=MAX_STEPS, search_steps=LR_SEARCH_STEPS,
                    seeds=SEEDS, data=provenance)
    path = os.path.join(TASK_DIR, "run_manifest.json")
    if os.path.exists(path) and _read_json(path, None) != manifest:
        raise ValueError("Hybrid checkpoint data/protocol differs from this run; use a fresh BENCH12_CKPT_ROOT")
    _write_json(path, manifest)


def _parse_slice(value,name):
    try:
        k,n=map(int,value.split("/"))
        if not 0<=k<n:raise ValueError()
        return k,n
    except (ValueError,AttributeError):
        fail(f"{name} must be k/n with 0 <= k < n and n >= 1")


def _stage_finished(stage):
    if os.environ.get("BENCH12_STAGE") or os.environ.get("BENCH12_CELL_SLICE") or os.environ.get("BENCH12_SHARD_TAG"):
        _write_json(os.path.join(TASK_DIR,"stage_complete.json"),dict(stage=stage,
            shard_tag=os.environ.get("BENCH12_SHARD_TAG",""),cell_slice=os.environ.get("BENCH12_CELL_SLICE"),
            arms=list(ACTIVE_OPT_NAMES)))


def main():
    if os.environ.get("BENCH12_CELL_SLICE"):
        _parse_slice(os.environ["BENCH12_CELL_SLICE"],"BENCH12_CELL_SLICE")
    if os.environ.get("BENCH12_SHARD_TAG"):
        _write_json(os.path.join(TASK_DIR,"shard_info.json"),dict(shard_tag=os.environ["BENCH12_SHARD_TAG"]))
    log_sep("=")
    log(f"  {TASK_NAME}  |  domain={DOMAIN}  device={DEVICE}  torch={torch.__version__}")
    log(f"  primary={PRIMARY_METRIC}  seeds={SEEDS}  max_steps={MAX_STEPS}  "
        f"lr_search_steps={LR_SEARCH_STEPS}  batch={BATCH_SIZE}")
    if TASK.get("nonstandard_ppl_caveat"):
        log(f"  [CAVEAT] {TASK['nonstandard_ppl_caveat']}")
    log_sep("=")
    preflight()
    data = prepare_data()
    if TASK.get("opt_set") == "muonhybrid" or TASK.get("extra_metrics"):
        _hybrid_manifest(data)
    if os.environ.get("BENCH12_SPEEDTEST") == "1":
        _speedtest(data)
        return
    stage = os.environ.get("BENCH12_STAGE", "all")
    if stage not in ("all", "search", "sweep"):
        fail("BENCH12_STAGE must be all, search, or sweep")
    if stage == "sweep":
        _cached = _read_json(LR_JSON, {})
        if any(not isinstance(_cached.get(a),dict) or not _cached[a].get("complete") or not _is_finite(_cached[a].get("lr")) for a in ACTIVE_OPT_NAMES):
            fail("sweep stage requires lr_search.json with every active arm complete")
        lr_used={a:float(_cached[a]["lr"]) for a in _cached if isinstance(_cached[a],dict) and _cached[a].get("complete") and "lr" in _cached[a]}
        knob_used={a:_cached[a].get("knob") for a in lr_used}
    else:
        lr_used, knob_used = lr_search(data)
    if stage == "search":
        log("[stage] search complete; no sweep cells trained")
        _stage_finished("search")
        return
    results = run_sweep(data, lr_used, knob_used)
    if os.environ.get("BENCH12_UNIT_SLICE") or os.environ.get("BENCH12_CELL_SLICE"):
        log("sharded run: aggregate with merge_shards.py")
    else:
        aggregate_and_report(results)
    _stage_finished(stage)
    log(f"  DONE {datetime.now().isoformat()}")
    _log_fh.flush()


