def _tensor_bytes(value):
    if torch.is_tensor(value):
        return value.numel()*value.element_size()
    if isinstance(value,dict):
        return sum(_tensor_bytes(v) for v in value.values())
    if isinstance(value,(tuple,list)):
        return sum(_tensor_bytes(v) for v in value)
    return 0


def _safe_extra(name, fn, errors):
    try:
        value = fn()
        if isinstance(value, (float,np.floating)) and not math.isfinite(value):
            raise ValueError("undefined/nonfinite value")
        return value
    except Exception as exc:
        if not isinstance(exc,TimeoutError) and classify_exception(exc) == "env":
            raise
        errors[name] = repr(exc)
        return None


def _sync_time():
    if torch.cuda.is_available():
        torch.cuda.synchronize()
    return time.perf_counter()


def landscape_extras(model, loader, criterion, params, initial, roles, errors, deadline=None):
    """Validation-only, fixed local RNG; a signed Rayleigh estimate from power
    iteration may converge to the largest-magnitude Hessian eigenpair.
    Runtime budget is checked between operations; a single kernel is not preempted.
    """
    import contextlib
    model.eval()
    started = time.monotonic()
    budget = 5. if DOMAIN == "finance" else 90.
    result = dict.fromkeys(["x_role_dist_from_init","x_role_weight_norm","x_dist_from_init"])
    # Local generators never alter training or checkpoint RNG streams.
    gen = torch.Generator(device=DEVICE).manual_seed(0)
    def within():
        if time.monotonic()-started > budget or (deadline is not None and time.monotonic()>deadline):
            raise TimeoutError(f"diagnostic budget {budget:g}s exhausted; used deterministic first validation batches")
    def role_dist():
        within()
        out = {}
        for index,p in enumerate(params):
            role = roles.get(p,"other")
            v=out.setdefault(role,[0.,0.])
            v[1]+=float(p.detach().double().square().sum())
            if initial is not None:
                v[0]+=float((p.detach().cpu().double()-initial[index].double()).square().sum())
        result["x_role_weight_norm"]={r:math.sqrt(v[1]) for r,v in out.items()}
        result["x_role_dist_from_init"]={r:math.sqrt(v[0]/max(1e-30,sum(float(initial[i].double().square().sum()) for i,p in enumerate(params) if roles.get(p,"other")==r))) for r,v in out.items()} if initial is not None else None
        result["x_dist_from_init"] = math.sqrt(sum(v[0] for v in out.values())/max(1e-30,sum(float(t.double().square().sum()) for t in initial))) if initial is not None else None
    _safe_extra("x_role_dist_from_init",role_dist,errors)
    if initial is None:
        errors["x_dist_from_init"]="resumed cell: initial weights unavailable"
        errors["x_role_dist_from_init"]="resumed cell: initial weights unavailable"
    def rank_stats():
        ranks=[]; byrole={}
        with torch.no_grad():
            for p in params:
                within()
                if p.ndim!=2 or max(p.shape)>4096: continue
                v=torch.randn(p.size(1),device=p.device,dtype=p.dtype,generator=gen)
                for _ in range(10):
                    v=p.T@(p@v);v=v/v.norm().clamp_min(1e-30)
                sigma=(p@v).norm()
                value=float(p.square().sum()/sigma.square().clamp_min(1e-30))
                ranks.append(value);byrole.setdefault(roles.get(p,"other"),[]).append(value)
        return ranks,byrole
    rank=_safe_extra("x_stable_rank_mean",rank_stats,errors)
    result.update(x_stable_rank_mean=float(np.mean(rank[0])) if rank and rank[0] else None,
                  x_stable_rank_min=min(rank[0]) if rank and rank[0] else None,
                  x_stable_rank_by_role={r:float(np.mean(v)) for r,v in rank[1].items()} if rank else None)
    def kurtosis():
        within()
        # Sample uniformly from the pooled vector without copying all weights.
        total=sum(p.numel() for p in params)
        if total<=1000000:
            values=torch.cat([p.detach().reshape(-1).cpu().double() for p in params])
        else:
            rng=np.random.default_rng(0)
            indices=np.sort(rng.choice(total,1000000,replace=False))
            parts=[];offset=0
            for p in params:
                idx=indices[(indices>=offset)&(indices<offset+p.numel())]-offset
                if len(idx):parts.append(p.detach().reshape(-1)[torch.as_tensor(idx,device=p.device)].cpu().double())
                offset+=p.numel()
            values=torch.cat(parts)
        centered=values-values.mean();v=centered.square().mean()
        return float(centered.pow(4).mean()/v.square()-3) if v>0 else float("nan")
    result["x_weight_kurtosis"]=_safe_extra("x_weight_kurtosis",kurtosis,errors)
    # Keep CPU/GPU loader seeding isolated, including DataLoader base seeds.
    rng_state_before=rng_state()
    try:
        batches=[]
        for batch in itertools.islice(loader,2 if DOMAIN=="finance" else 4):
            within();batches.append(batch_to_device(batch))
        if not batches:raise ValueError("empty validation loader")
    except Exception as exc:
        if not isinstance(exc,TimeoutError) and classify_exception(exc)=="env":raise
        errors["landscape_batches"]=repr(exc);batches=[]
    finally:
        load_rng_state(rng_state_before)
    result["x_landscape_batches"]=len(batches)
    result["x_landscape_examples"]=sum(int(b[0].size(0)) for b in batches)
    def loss():
        within()
        if not batches:raise ValueError("no diagnostic validation batches")
        return sum(forward_loss(model,b,criterion) for b in batches)/len(batches)
    try:
        from torch.nn.attention import sdpa_kernel, SDPBackend
        ctx=sdpa_kernel(SDPBackend.MATH)
    except ImportError:
        ctx=contextlib.nullcontext()
    with ctx:
        def hessian_metrics():
            with torch.enable_grad():
                L=loss()
                grads=torch.autograd.grad(L,params,create_graph=True,allow_unused=True)
                def hvp(v):
                    within()
                    dot=sum((g*x).sum() for g,x in zip(grads,v) if g is not None)
                    h=torch.autograd.grad(dot,params,retain_graph=True,allow_unused=True)
                    return [torch.zeros_like(p) if t is None else t.detach() for p,t in zip(params,h)]
                v=[torch.randn(p.shape,device=p.device,dtype=p.dtype,generator=gen) for p in params]
                for _ in range(20):
                    norm=sum(float(t.square().sum()) for t in v)**.5
                    v=[t/max(norm,1e-30) for t in v];h=hvp(v)
                    eigen=sum(float((a*b).sum()) for a,b in zip(v,h));v=h
                trace=[]
                for _ in range(8):
                    v=[torch.randint(0,2,p.shape,device=p.device,generator=gen).to(p.dtype)*2-1 for p in params]
                    h=hvp(v);trace.append(sum(float((a*b).sum()) for a,b in zip(v,h)))
            return eigen,float(np.mean(trace))
        hess=_safe_extra("x_sharp_top_eig",hessian_metrics,errors)
        result["x_sharp_top_eig"]=hess[0] if hess else None
        result["x_hess_trace_hutch"]=hess[1] if hess else None
        if hess is None:errors.setdefault("x_hess_trace_hutch",errors.get("x_sharp_top_eig","unavailable"))
        if deadline is not None and time.monotonic()>deadline:
            for name in ["x_flat_rho001","x_flat_rho003","x_flat_rho010"]:
                result[name]=None;errors[name]="end-of-run diagnostic budget exhausted"
            for name,value in result.items():
                if value is None:errors.setdefault(name,"unavailable for this cell")
            return result
        snapshot={k:v.detach().cpu().clone() for k,v in model.state_dict().items()}
        # Exclude normalization parameters by module membership, including names
        # like downsample.1 that do not spell out 'bn'.
        excluded={id(p) for mod in model.modules() if isinstance(mod,(nn.LayerNorm,nn.modules.batchnorm._BatchNorm)) for p in mod.parameters(recurse=False)}
        def flatness(rho):
            base=float(loss().detach())
            values=[]
            try:
                for _ in range(5):
                    within();model.load_state_dict(snapshot)
                    with torch.no_grad():
                        for p in params:
                            if id(p) in excluded:continue
                            d=torch.randn(p.shape,device=p.device,dtype=p.dtype,generator=gen)
                            p.add_(d,alpha=rho*float(p.norm())/max(float(d.norm()),1e-30))
                    values.append(float(loss().detach())-base)
                return float(np.mean(values))
            finally:
                model.load_state_dict(snapshot)
                key=next(iter(snapshot))
                if not torch.equal(model.state_dict()[key].detach().cpu(),snapshot[key]):
                    raise RuntimeError("flatness probe did not restore weights exactly")
        for name,rho in [("x_flat_rho001",.01),("x_flat_rho003",.03),("x_flat_rho010",.1)]:
            result[name]=_safe_extra(name,lambda r=rho:flatness(r),errors)
    for name,value in result.items():
        if value is None:errors.setdefault(name,"unavailable for this cell")
    return result


def _extra_train_accuracy(model,data,criterion,result,deadline=None):
    def measure():
        dataset=_VisionDataset(*data["train"],data["mean"],data["std"],train=False,hflip=False)
        selected=torch.utils.data.Subset(dataset,range(min(10000,len(dataset))))
        loader=torch.utils.data.DataLoader(selected,batch_size=BATCH_SIZE,
            generator=torch.Generator().manual_seed(0))
        hit=total=0
        for batch in loader:
            if deadline is not None and time.monotonic()>deadline:
                raise TimeoutError("end-of-run diagnostic budget exhausted")
            x,y=batch_to_device(batch)
            with torch.no_grad():hit+=int((model(x).argmax(1)==y).sum())
            total+=len(y)
        return 100*hit/max(total,1)
    result["train_acc_subsample"]=_safe_extra("train_acc_subsample",measure,result["x_errors"])
    result["train_acc_augmented"]=False
    result["gen_gap_acc"]=(result["train_acc_subsample"]-result["primary"]
                           if result["train_acc_subsample"] is not None else None)


def _speedtest(data):
    steps=int(os.environ.get("BENCH12_SPEEDTEST_STEPS","200"))
    if steps<=20:fail("BENCH12_SPEEDTEST_STEPS must exceed 20 warm-up steps")
    output={};lrs={}
    unit=lr_search_units(data)[0]
    for arm in ACTIVE_OPT_NAMES:
        pin=(TASK.get("pinned_lr") or {}).get(arm,{})
        grid=(TASK.get("search_grid") or {}).get(arm,{})
        lr=pin.get("lr",(grid.get("lr") or [LR_GRID_CENTRE[arm]])[0] if grid else LR_GRID_CENTRE[arm])
        knob=pin.get("knob",(TASK.get("fixed_knob") or {}).get(arm,(grid.get("knob") or KNOB_GRID.get(arm) or [None])[0]))
        lrs[arm]=lr
        if torch.cuda.is_available():torch.cuda.reset_peak_memory_stats()
        r=train_run(arm,data,unit,lr,_adamw_lr(lrs),steps,42,None,is_lr_search=True,knob=knob)
        output[arm]=dict(sec_per_step=r["speed_sec_per_step"],peak_mem_mb=r["peak_mem_mb"],
            steps=r["steps_run"],tf32=bool(torch.backends.cuda.matmul.allow_tf32),
            device=torch.cuda.get_device_name() if torch.cuda.is_available() else "CPU",
            primary_after=(r["val_curve"][-1][1] if r.get("val_curve") else r["best_val_primary"]),warmup_steps_excluded=20)
    _write_json(os.path.join(TASK_DIR,"speedtest.json"),output)

"""Dependency-light tabular Muon-hybrid readout (stdlib + numpy).

The long-form CSV is the single deliverable. Every raw scalar, diagnostic
trace point, tuning trial, metadata field and registered contrast has a row.
Internal JSON/checkpoints remain necessary for crash recovery and auditing.
"""
import csv
import json
import math
import os
import tempfile
from pathlib import Path

import numpy as np


COLUMNS = ["record_type", "task", "arm", "unit", "seed", "subset", "metric",
           "value", "status", "note", "source"]


def finite(value):
    return isinstance(value, (int, float)) and math.isfinite(value)


def flatten(value, prefix=""):
    if isinstance(value, dict):
        for key, item in value.items():
            yield from flatten(item, f"{prefix}.{key}" if prefix else str(key))
    elif isinstance(value, (list, tuple)):
        for index, item in enumerate(value):
            yield from flatten(item, f"{prefix}[{index}]")
    else:
        yield prefix, value


def collect_rows(paths):
    rows, pooled = [], {}
    seen_tasks = set()
    expected_tasks = 4
    smoke_modes = set()
    for path in map(Path, paths):
        results = json.loads(path.read_text())
        meta, cells = results.get("meta", {}), results.get("cells", {})
        if meta.get("opt_set") != "muonhybrid":
            raise ValueError(f"{path}: expected muonhybrid results, got {meta.get('opt_set')!r}")
        smoke_modes.add(bool(meta.get("smoke")))
        if len(smoke_modes) > 1:
            raise ValueError("Refusing to pool SMOKE and production runs")
        task = meta.get("task_name") or path.parent.name
        if task in seen_tasks:
            raise ValueError(f"Duplicate task {task}; merge split-arm JSON files before reporting")
        seen_tasks.add(task)
        source = str(path)

        def emit(kind, arm, unit, seed, subset, metric, value, status="ok", note=""):
            if value is None or (isinstance(value, float) and not math.isfinite(value)):
                value, status = "", "unavailable" if status == "ok" else status
            rows.append(dict(zip(COLUMNS, [kind, task, arm, unit, seed, subset,
                                          metric, value, status, note, source])))

        for metric, value in flatten(meta):
            emit("metadata", "", "", "", "", metric, value)
        for key, cell in cells.items():
            parts = key.split("|")
            arm, unit, seed = parts if len(parts) == 3 else (
                cell.get("opt", ""), cell.get("unit", ""), cell.get("seed", ""))
            status = "failed" if cell.get("diverged") else "aliased" if cell.get("aliased_from") else "ok"
            note = cell.get("fail_reason") or cell.get("aliased_from") or ""
            for metric, value in flatten(cell):
                emit("cell", arm, unit, seed, "tuning_seed" if str(seed) == "42" else "heldout_seeds",
                     metric, value, status, note)

        search_path = path.with_name("lr_search.json")
        if search_path.exists():
            for arm, entry in json.loads(search_path.read_text()).items():
                for metric, value in flatten(entry):
                    emit("search", arm, "", 42, "tuning", metric, value,
                         note="validation only; fixed grid; no boundary extension")
                emit("search", arm, "", 42, "tuning", "trials_scored", len(entry.get("grid", {})),
                     note="derived arm reuses four gamma=30 trials" if entry.get("derived_from") else "")
        audit_path = path.with_name("search_audit.json")
        if audit_path.exists():
            audit = json.loads(audit_path.read_text())
            for key, cell in audit.items():
                arm = key.split("|")[0]
                for metric, value in flatten(cell):
                    emit("search_trial", arm, key, 42, "tuning", metric, value,
                         "failed" if cell.get("diverged") else "ok")
            for arm in {k.split("|")[0] for k in audit}:
                elapsed = [c["wall_s"] for k,c in audit.items()
                           if k.split("|")[0] == arm and finite(c.get("wall_s"))]
                emit("search", arm, "", 42, "tuning", "search_training_wall_s", sum(elapsed),
                     note="successful measured trials; excludes setup and unmeasured failed-trial cost")

        for metric, definition in {
            "perplexity": "exp(token-weighted NLL); within-task tokenizer only; capped-vocabulary WikiText is not a literature leaderboard",
            "bits_per_token": "NLL / ln(2); legacy bpc has this meaning for non-byte tokenizers",
            "bits_per_byte": "NLL / ln(2) only on enwik8 byte tokens; unavailable elsewhere without evaluated byte counts; https://arxiv.org/abs/2101.00027",
            "ece_15": "15 equal-width confidence bins; weighted absolute accuracy-confidence gap; https://proceedings.mlr.press/v70/guo17a.html",
            "mce_15": "maximum accuracy-confidence gap among occupied ECE bins; descriptive, bin-sensitive",
            "brier_score": "mean sum_v (p_v - onehot(y)_v)^2; range [0,2]; multiclass proper score; https://doi.org/10.1198/016214506000001437",
            "mean_target_rank": "1 + number of logits strictly exceeding gold; optimistic ties",
            "mean_reciprocal_rank": "mean reciprocal target rank across teacher-forced tokens; descriptive",
            "mean_log_ratio_ci95": "10000 paired seed-bootstrap samples, RNG 20261109; no CI for fewer than 2 pairs; very few seeds implies coarse uncertainty",
            "tuning": "12 vs 12 trials (OWT 4 vs 4); fixed gamma reuses 4 trials; no boundary extension; https://arxiv.org/abs/1910.05446",
            "time_to_reference_val": "first observed validation checkpoint meeting paired MuonSub best validation; no interpolation; unreached is blank+censored; post-hoc descriptive; https://mlcommons.org/benchmarks/algorithms/",
            "gen_gap_loss": "best-val-selected test loss minus final-step training loss; different checkpoints/batches, descriptive only",
            "cost": "wall_s is training+validation, excludes final detailed test diagnostics; alias cost is copied, not a second measured run",
            "hessian": "unavailable for hybrid arms: existing Hessian telemetry is Sophia-only; missing is not zero",
        }.items():
            emit("definition", "", "", "", "", metric, definition)
        arms = meta.get("opt_names") or sorted({k.split("|")[0] for k in cells})
        seeds = meta.get("seeds", sorted({int(k.split("|")[-1]) for k in cells}))
        units = meta.get("units", sorted({k.split("|")[1] for k in cells}))
        ref = "MuonSub"
        for subset, selected in [("all_seeds", seeds), ("heldout_seeds", [s for s in seeds if s != 42]),
                                 ("tuning_seed", [s for s in seeds if s == 42])]:
            by_arm = {}
            for arm in arms:
                expected = [cells.get(f"{arm}|{u}|{s}") for u in units for s in selected]
                healthy = [c for c in expected if c and not c.get("diverged")
                           and finite(c.get("primary")) and c["primary"] > 0]
                by_arm[arm] = {s: float(np.median([c["primary"] for u in units
                               if (c := cells.get(f"{arm}|{u}|{s}")) and not c.get("diverged")
                               and finite(c.get("primary")) and c["primary"] > 0]))
                               for s in selected if all(
                                   (c := cells.get(f"{arm}|{u}|{s}")) and not c.get("diverged")
                                   and finite(c.get("primary")) and c["primary"] > 0 for u in units)}
                emit("summary", arm, "", "", subset, "expected_cells", len(expected))
                emit("summary", arm, "", "", subset, "missing_cells", sum(c is None for c in expected))
                emit("summary", arm, "", "", subset, "divergences", sum(bool(c and c.get("diverged")) for c in expected))
                emit("summary", arm, "", "", subset, "aliased_cells", sum(bool(c and c.get("aliased_from")) for c in expected))
                emit("summary", arm, "", "", subset, "healthy_cells", len(healthy))
                # All observed-arm statistics are marked so failures cannot disappear
                # behind a favourable complete-case number.
                numeric = {k for c in healthy for k,v in c.items() if finite(v) and not isinstance(v, bool)}
                for metric in sorted(numeric):
                    values = np.array([c[metric] for c in healthy if finite(c.get(metric))])
                    for stat, value in [("mean", values.mean()), ("median", np.median(values)),
                                        ("std", values.std(ddof=1) if len(values)>1 else float("nan")),
                                        ("min", values.min()), ("max", values.max()),
                                        ("q25", np.percentile(values,25)), ("q75", np.percentile(values,75))]:
                        emit("summary", arm, "", "", subset, f"{metric}.{stat}", float(value),
                             note=f"observed healthy cells only; n={len(values)}; inspect missing/divergences")
            baseline = by_arm.get(ref, {})
            for arm in arms:
                if arm == ref:
                    continue
                paired = sorted(set(baseline) & set(by_arm[arm]))
                n_expected = len(selected)
                note = ("SMOKE correctness data; " if meta.get("smoke") else "") + f"vs {ref}; paired seeds={paired}; expected={n_expected}; losses/ties retained"
                emit("paired", arm, "", "", subset, "n_paired_seeds", len(paired), note=note)
                emit("paired", arm, "", "", subset, "n_unpaired_seeds", n_expected-len(paired), note=note)
                if not paired:
                    emit("paired", arm, "", "", subset, "mean_log_ratio", None, note=note)
                    continue
                a = np.array([by_arm[arm][s] for s in paired])
                b = np.array([baseline[s] for s in paired])
                ratio = a/b
                logs = np.log(ratio)
                med_a = float(np.median(list(by_arm[arm].values())))
                med_b = float(np.median(list(baseline.values())))
                stats = dict(median_test_perplexity=float(np.median(a)),
                             median_reference_perplexity=float(np.median(b)),
                             median_seed_ratio=float(np.median(ratio)),
                             median_seed_ratio_pct=100*(float(np.median(ratio))-1),
                             ratio_of_arm_medians_pct=100*(med_a/med_b-1),
                             mean_log_ratio=float(logs.mean()),
                             geometric_mean_ratio=float(np.exp(logs.mean())),
                             seeds_won=int((a<b).sum()), seeds_tied=int((a==b).sum()),
                             seeds_lost=int((a>b).sum()),
                             mean_paired_perplexity_difference=float((a-b).mean()))
                if len(paired) >= 2:
                    rng = np.random.default_rng(20261109)
                    boot = logs[rng.integers(0,len(logs),size=(10000,len(logs)))].mean(1)
                    lo, hi = np.quantile(boot,[.025,.975])
                    stats.update(mean_log_ratio_ci95_low=float(lo), mean_log_ratio_ci95_high=float(hi),
                                 geometric_ratio_ci95_low=float(np.exp(lo)), geometric_ratio_ci95_high=float(np.exp(hi)))
                else:
                    stats.update(mean_log_ratio_ci95_low=None, mean_log_ratio_ci95_high=None)
                # Cost ratios use the same seed+unit pairing; aliases are excluded:
                # their copied wall time is a counterfactual, not measured compute.
                for metric in ["wall_s", "sec_per_step", "peak_mem_mb", "tokens_per_s", "test_eval_wall_s"]:
                    ratios = []
                    for seed in paired:
                        for unit in units:
                            ca, cb = cells[f"{arm}|{unit}|{seed}"], cells[f"{ref}|{unit}|{seed}"]
                            if (not ca.get("aliased_from") and finite(ca.get(metric))
                                    and finite(cb.get(metric)) and cb[metric] > 0):
                                ratios.append(ca[metric]/cb[metric])
                    stats[metric+".median_ratio"] = float(np.median(ratios)) if ratios else None
                for seed in paired:
                    for unit in units:
                        ca, cb = cells[f"{arm}|{unit}|{seed}"], cells[f"{ref}|{unit}|{seed}"]
                        target = cb.get("best_val_primary")
                        if finite(target):
                            for which, cell in [(arm, ca), (ref, cb)]:
                                hits = [(step,val) for step,val in cell.get("val_curve", [])
                                        if finite(val) and val <= target]
                                step = hits[0][0] if hits else None
                                wall = dict(cell.get("eval_wall_curve", [])).get(step)
                                emit("time_to_target", which, unit, seed, subset,
                                     "reference_best_val_target", target, note="post-hoc baseline validation target")
                                for metric, value in [("time_to_reference_val_steps", step),
                                                      ("time_to_reference_val_wall_s", wall)]:
                                    emit("time_to_target", which, unit, seed, subset, metric, value,
                                         "aliased" if cell.get("aliased_from") else "ok" if hits else "censored",
                                         note="observed evaluation grid only; never use test scores for selection")
                for metric, value in stats.items():
                    emit("paired", arm, "", "", subset, metric, value, note=note)
                if subset == "heldout_seeds":
                    pooled.setdefault(arm, []).append((task, float(logs.mean()), len(paired) == n_expected))
    for arm, values in pooled.items():
        complete = len(values) == expected_tasks and all(v[2] for v in values)
        rows.append(dict(zip(COLUMNS, ["pooled", "ALL", arm, "", "", "heldout_seeds",
                    "equal_task_mean_log_ratio", float(np.mean([v[1] for v in values])),
                    "ok" if complete else "incomplete", "equal task weights; tasks="+
                    ",".join(v[0] for v in values)+"; descriptive only, no p-values", ""])))
    return rows


def write_metrics(paths, output, extra_rows=()):
    rows = collect_rows(paths) + list(extra_rows)
    output = Path(output)
    output.parent.mkdir(parents=True, exist_ok=True)
    fd, temp = tempfile.mkstemp(prefix=".metrics-", suffix=".csv", dir=output.parent)
    try:
        with os.fdopen(fd, "w", newline="") as f:
            writer = csv.DictWriter(f, fieldnames=COLUMNS)
            writer.writeheader()
            writer.writerows(rows)
            f.flush()
            os.fsync(f.fileno())
        os.replace(temp, output)
    finally:
        if os.path.exists(temp):
            os.unlink(temp)
    return rows


def readout_main():
    import argparse
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("results", nargs="+", help="results.json from one or more hybrid tasks")
    parser.add_argument("--output", default="muonhybrid_metrics.csv")
    args = parser.parse_args()
    rows = write_metrics(args.results, args.output)
    for row in rows:
        if row["record_type"] in ("paired", "pooled") and row["metric"] in (
                "median_seed_ratio_pct", "mean_log_ratio_ci95_low", "mean_log_ratio_ci95_high",
                "seeds_won", "wall_s.median_ratio", "equal_task_mean_log_ratio"):
            print(" | ".join(str(row[k]) for k in ["task","arm","subset","metric","value","status"]))
    print(f"Wrote {len(rows)} metric rows to {args.output}")

# === END ENGINE BLOCK ===
# (the `if __name__ == "__main__": main()` / `sweep_main()` entry point is
#  appended per-file by benchmark12/_build/build.py)


# ==============================================================================
#  SWEEP DRIVER  --  batch-size OR model-size sweep over one host task
#  (benchmark protocol sec 9). GENERATED only into benchmark12/sweeps/<type>/<task>.py.
#  Reuses the shared optimizer block + the engine helpers above UNCHANGED and
#  adds only this outer grid loop. Entry point: sweep_main().
#
#  Key rules (benchmark protocol sec 9.2 / 9.3):
#   - fixed step budget per grid point (MAX_STEPS, not samples-seen-matched);
#     absolute metric values are therefore NOT comparable across grid points --
#     only the WITHIN-grid-point delta between arms is fair. Logged below.
#   - LR search re-run per (grid point, arm); the reused-baseline point instead
#     reads the main run's frozen LR + its already-computed [42,43,44] cells
#     from checkpoints/<BASE_TASK_NAME>/.
#   - seeds [42,43,44] (first 3 of the main run's 5) so the baseline point IS
#     the main run's own cell.
#   - Evie-KF arms (EvieKF in _BATCH_ARMS/_MODEL_ARMS; EvieKFu in _BATCH_ARMS
#     for the C1 test) run at a FIXED gamma = EVIEKF_SWEEP_GAMMA at the new
#     grid points (the sweeps re-search LR only, not gamma -- see _sweep_knob).
#     The reused baseline point keeps whatever gamma the MAIN run's joint
#     search froze for EvieKF (EvieKFu has no baseline cell -- the main table
#     never runs it). So EvieKF's baseline column may sit at a different gamma
#     than its new-point columns; that is inside the existing "absolute values
#     not comparable across grid points" caveat, and the C1 spearman
#     (EvieKFu vs EvieKF) is computed over the new points only, all at the same
#     gamma, so it is unaffected.
# ==============================================================================
from scipy.stats import spearmanr

SWEEP_TYPE     = TASK["sweep_type"]            # "batchsize" | "modelsize"
BASE_TASK_NAME = TASK["base_task_name"]
SWEEP_GRID     = TASK["sweep_grid"]
SWEEP_ARMS_CFG = TASK["sweep_arms"]
BASE_BATCH     = int(TASK["batch_size"])
SWEEP_SEEDS    = [42] if SMOKE else list(TASK.get("seeds", [42, 43, 44]))

SWEEP_LR_JSON = os.path.join(TASK_DIR, "sweep_lr.json")
SWEEP_RESULTS = os.path.join(TASK_DIR, "sweep_results.json")
SWEEP_SUMMARY = os.path.join(TASK_DIR, "summary.json")
SWEEP_CSV     = os.path.join(TASK_DIR, "results_raw.csv")


def _sweep_arms():
    # Accept any arm build_optimizer() can construct -- the main-table 8 PLUS
    # the ablation-ladder names (EvieKFu / EvieDiag). _BATCH_ARMS carries
    # "EvieKFu" for the C1 test even though it is not in OPT_NAMES.
    _buildable = set(OPT_NAMES) | set(ABLATION_OPT_NAMES)
    arms = [o for o in SWEEP_ARMS_CFG if o in _buildable]
    dropped = [o for o in SWEEP_ARMS_CFG if o not in _buildable]
    if dropped:
        log(f"[sweep] WARNING: sweep arms {dropped} are not buildable "
            f"(not in OPT_NAMES or ABLATION_OPT_NAMES) -- skipped")
    # NOTE: the sweeps re-search LR per (grid point, arm) but do NOT joint-search
    # the second axis. Evie-KF-family arms are pinned to EVIEKF_SWEEP_GAMMA
    # (=3000, the PoC v3 optimum -- see _sweep_knob); Shampoo (not currently a
    # sweep arm) would use its build_optimizer() default beta.
    return arms


def _sweep_knob(arm):
    """Fixed second-axis value the sweep pins `arm` to (LR is still re-searched
    at this value). Evie-KF family -> EVIEKF_SWEEP_GAMMA; everything else ->
    None, i.e. build_optimizer()'s own default."""
    if arm in ("EvieKF", "EvieKFu", "EvieDiag", "EvieKFn"):
        return EVIEKF_SWEEP_GAMMA
    return None


def _grid_points():
    """[(label, cfg), ...] with the reused-baseline point LAST."""
    g = SWEEP_GRID
    if SWEEP_TYPE == "batchsize":
        pts = [(f"batch{int(b)}", {"batch": int(b)}) for b in g["new"]]
        pts.append((f"batch{int(g['baseline'])}",
                    {"batch": int(g["baseline"]), "baseline": True}))
    else:
        pts = [(k, {"model_size": v}) for k, v in g["points"].items()]
        pts.append(("baseline", {"model_size": g["baseline_spec"], "baseline": True}))
    if SMOKE:
        pts = pts[:2] + [p for p in pts if p[1].get("baseline")]
    return pts


def _grid_x(label, cfg):
    """numeric x-axis for a grid point: batch size, or a param-count proxy."""
    if SWEEP_TYPE == "batchsize":
        return float(cfg["batch"])
    ms = cfg["model_size"]
    if isinstance(ms, dict):                       # language: L * d * heads
        return float(ms["n_layer"] * ms["d_model"] * ms["n_head"])
    return float(ms[0] * ms[-1])                   # vision widths / finance dims


def _configure(cfg, data):
    global BATCH_SIZE
    data.pop("model_size", None)
    BATCH_SIZE = int(cfg["batch"]) if "batch" in cfg else BASE_BATCH
    if "model_size" in cfg:
        data["model_size"] = cfg["model_size"]


def _baseline_from_main(data, arms):
    base_dir = os.path.join(CKPT_ROOT, BASE_TASK_NAME)
    lr_j = _read_json(os.path.join(base_dir, "lr_search.json"), {})
    res_j = _read_json(os.path.join(base_dir, "results.json"), {"cells": {}})
    got_lr, got_cells, missing = {}, {}, []
    for arm in arms:
        e = lr_j.get(arm)
        if isinstance(e, dict) and "lr" in e:
            got_lr[arm] = float(e["lr"])
        else:
            missing.append(f"lr[{arm}]")
    for arm in arms:
        for unit in main_units(data):
            for seed in SWEEP_SEEDS:
                c = (res_j.get("cells", {}) or {}).get(f"{arm}|{unit}|{seed}")
                if c:
                    got_cells[f"{arm}|{unit}|{seed}"] = c
                else:
                    missing.append(f"cell[{arm}|{unit}|{seed}]")
    if missing:
        log(f"[sweep] baseline point: {len(missing)} pieces NOT found under "
            f"checkpoints/{BASE_TASK_NAME}/ -- run that main task first for a "
            f"complete baseline column. Missing e.g. {missing[:6]}"
            + (" ..." if len(missing) > 6 else ""))
    return got_lr, got_cells


def _grid_lr(label, arm, data, adamw_lr, cache):
    key = f"{label}|{arm}"
    e = cache.get(key)
    if isinstance(e, dict) and "lr" in e:
        return float(e["lr"])
    knob = _sweep_knob(arm)
    best, tried, bchecks = search_lr_for(arm, data, lr_search_units(data),
                                         adamw_lr, log_prefix=f"[{label}] ",
                                         knob=knob)
    cache[key] = {"lr": best, "knob": knob, "boundary_checks": bchecks,
                  "grid": {f"{k:.6e}": tried[k] for k in sorted(tried)}}
    _write_json(SWEEP_LR_JSON, cache)
    log(f"[{label}] [lr-search] {arm}: FROZEN lr={best:.3e}"
        + ("" if knob is None else f"  (fixed knob={knob:g})")
        + f"  (boundary checks: {bchecks})")
    return best


def sweep_main():
    log_sep("=")
    log(f"  {TASK_NAME}  |  {SWEEP_TYPE} sweep on {BASE_TASK_NAME}  "
        f"device={DEVICE}  torch={torch.__version__}")
    log(f"  NOTE: fixed {MAX_STEPS}-step budget at every grid point -- absolute "
        f"{PRIMARY_METRIC} is NOT comparable across grid points; only the "
        f"within-grid-point arm delta is (benchmark protocol sec 9.2).")
    if TASK.get("nonstandard_ppl_caveat"):
        log(f"  [CAVEAT] {TASK['nonstandard_ppl_caveat']}")
    log_sep("=")
    preflight()
    data = prepare_data()
    arms = _sweep_arms()
    points = _grid_points()
    ordered = (["AdamW"] if "AdamW" in arms else []) + \
              [a for a in arms if a != "AdamW"]
    log(f"  arms={arms}  seeds={SWEEP_SEEDS}  grid={[p[0] for p in points]}")

    lr_cache = _read_json(SWEEP_LR_JSON, {})
    results = _read_json(SWEEP_RESULTS, {"cells": {}, "meta": {}})
    cells = results["cells"]

    for label, cfg in points:
        _configure(cfg, data)

        if cfg.get("baseline"):
            log_sep("-")
            log(f"[{label}] reusing the main run's frozen LR + "
                f"seed {SWEEP_SEEDS} cells from checkpoints/{BASE_TASK_NAME}/")
            got_lr, got_cells = _baseline_from_main(data, arms)
            for arm, v in got_lr.items():
                lr_cache[f"{label}|{arm}"] = {"lr": v, "reused_from_main": True}
            for ck, c in got_cells.items():
                arm, unit, seed = ck.split("|")
                cells[f"{label}|{arm}|{unit}|{seed}"] = dict(
                    c, reused_from_main=True, recorded=True, label=label)
            _write_json(SWEEP_LR_JSON, lr_cache)
            _write_json(SWEEP_RESULTS, results)
            continue

        log_sep("-")
        log(f"[{label}] LR search  ({SWEEP_TYPE} = "
            f"{cfg.get('batch', cfg.get('model_size'))})")
        frozen = {}
        for arm in ordered:
            frozen[arm] = _grid_lr(label, arm, data, frozen.get("AdamW"), lr_cache)

        log(f"[{label}] sweep cells")
        for arm in ordered:
            for unit in main_units(data):
                for seed in SWEEP_SEEDS:
                    key = f"{label}|{arm}|{unit}|{seed}"
                    if key in cells and cells[key].get("recorded"):
                        continue
                    if torch.cuda.is_available():
                        torch.cuda.reset_peak_memory_stats()
                    ckpt = os.path.join(
                        CELL_DIR, f"{_safe(label)}__{_safe(arm)}__{_safe(unit)}"
                                  f"__seed{seed}.pt")
                    try:
                        r = train_run(arm, data, unit, frozen[arm],
                                      frozen.get("AdamW"), MAX_STEPS, seed, ckpt,
                                      is_lr_search=False, knob=_sweep_knob(arm))
                        r["recorded"] = True
                        r["label"] = label
                        if _absurd_primary(r["primary"]):
                            r["diverged"] = True
                            r["fail_reason"] = (r.get("fail_reason")
                                                or "primary outside absolute range")
                        cells[key] = r
                    except SystemExit:
                        raise
                    except Exception as e:
                        if classify_exception(e) == "env":
                            log(f"[sweep] ENVIRONMENT error in {key}: {e!r}")
                            log(traceback.format_exc())
                            fail(f"environment/CUDA error at {key}: {e!r}. This is "
                                 f"NOT a diverged run -- fix the environment; "
                                 f"finished cells are safe, re-run to resume.")
                        log(f"[sweep] numerical failure in {key}: {e!r} -> cell "
                            f"marked failed, continuing")
                        log(traceback.format_exc())
                        cells[key] = {"label": label, "opt": arm, "unit": unit,
                                      "seed": seed, "lr_used": frozen[arm],
                                      "knob_used": _sweep_knob(arm),
                                      "primary": float("nan"), "diverged": True,
                                      "fail_reason": f"exception: {e!r}",
                                      "recorded": True}
                    _write_json(SWEEP_RESULTS, results)
                    log(f"[{label}] {key}  primary={cells[key].get('primary')}  "
                        f"diverged={cells[key].get('diverged')}")

        # peer-relative divergence WITHIN this grid point only (scale differs
        # across grid points by design -- benchmark protocol sec 9.2)
        healthy = [c["primary"] for k, c in cells.items()
                   if k.startswith(label + "|") and not c.get("diverged")
                   and _is_finite(c.get("primary"))]
        pm = float(np.median(healthy)) if healthy else None
        if pm is not None:
            for k, c in cells.items():
                if (k.startswith(label + "|") and not c.get("diverged")
                        and _absurd_primary(c.get("primary"), pm)):
                    c["diverged"] = True
                    c["fail_reason"] = (c.get("fail_reason")
                                        or f"{c['primary']:.4g} is "
                                           f">{PEER_DIVERGENCE_FACTOR}x off the "
                                           f"grid-point peer median {pm:.4g}")
                    log(f"[diverge] {k}: {c['fail_reason']}")
        _write_json(SWEEP_RESULTS, results)

    results["meta"] = {
        "task_name": TASK_NAME, "sweep_type": SWEEP_TYPE,
        "base_task_name": BASE_TASK_NAME, "arms": arms, "seeds": SWEEP_SEEDS,
        "primary_metric": PRIMARY_METRIC, "max_steps": MAX_STEPS,
        "grid": [p[0] for p in points], "torch": torch.__version__,
        "nonstandard_ppl_caveat": TASK.get("nonstandard_ppl_caveat"),
        "timestamp": datetime.now().isoformat(),
    }
    _write_json(SWEEP_RESULTS, results)
    _sweep_aggregate(results, points, arms, data)


def _sweep_number(cells, label, arm, units):
    per_seed = []
    for seed in SWEEP_SEEDS:
        vs = [cells[f"{label}|{arm}|{u}|{seed}"]["primary"] for u in units
              if f"{label}|{arm}|{u}|{seed}" in cells
              and not cells[f"{label}|{arm}|{u}|{seed}"].get("diverged")
              and _is_finite(cells[f"{label}|{arm}|{u}|{seed}"].get("primary"))]
        if vs:
            per_seed.append(float(np.mean(vs)))
    return (float(np.median(per_seed)) if per_seed else float("nan")), per_seed


def _sweep_write_csv(cells, labels, arms, units):
    import csv
    cols = ["label", "opt", "unit", "seed", "lr_used", "knob_used", "primary",
            "best_val_primary", "diverged", "fail_reason", "reused_from_main",
            "steps_run", "wall_s", "sec_per_step", "mean_step_size", "clip_freq",
            "peak_mem_mb",
            "steps_to_90pct_best", "frac_budget_to_90pct_best",
            "final_train_loss", "gen_gap_loss", "auc_val_curve",
            "update_weight_ratio", "update_cos_sim_sampled",
            "grad_norm_mean", "grad_norm_p95", "weight_norm_growth",
            "throughput_samples_per_s", "flops_per_step_est",
            "hess_trace", "hess_top_eig",
            "eviekf_cos_mean", "eviekf_cos_min", "eviekf_b_simple_mean",
            "eviekf_eff_rank_mean", "eviekf_gain_lo_min", "eviekf_gain_hi_max",
            "eviekf_n_active_steps"] + list(AUX_METRIC_KEYS)
    with open(SWEEP_CSV, "w", newline="") as fh:
        w = csv.DictWriter(fh, fieldnames=cols, extrasaction="ignore")
        w.writeheader()
        for label in labels:
            for arm in arms:
                for unit in units:
                    for seed in SWEEP_SEEDS:
                        c = cells.get(f"{label}|{arm}|{unit}|{seed}")
                        if c:
                            w.writerow(dict(c, label=label, opt=arm, unit=unit,
                                            seed=seed))
    log(f"  wrote {SWEEP_CSV}")


def _sweep_aggregate(results, points, arms, data):
    cells = results["cells"]
    units = main_units(data)
    labels = [p[0] for p in points]
    is_base = {p[0]: bool(p[1].get("baseline")) for p in points}
    xvals = {p[0]: _grid_x(*p) for p in points}
    # batch-size sweep: reference is EvieKF, so `delta vs ref` for the EvieKFu
    # arm IS the pre-registered C1 quantity -- does the centred-vs-uncentred gap
    # widen with batch size (benchmark protocol sec 9.2). model-size sweep: reference
    # stays AdamW (a fixed external baseline is the right question there, not a
    # KF-vs-KF contrast).
    if SWEEP_TYPE == "batchsize" and "EvieKF" in arms:
        ref = "EvieKF"
    else:
        ref = "AdamW"

    table, per_seed = {}, {}
    for label in labels:
        table[label], per_seed[label] = {}, {}
        for arm in arms:
            n, ps = _sweep_number(cells, label, arm, units)
            table[label][arm] = n
            per_seed[label][arm] = ps

    log_sep("=")
    log(f"  {SWEEP_TYPE.upper()} SWEEP -- {TASK_NAME}   primary={PRIMARY_METRIC} "
        f"({'lower' if PRIMARY_LOWER_BETTER else 'higher'} is better)")
    if TASK.get("nonstandard_ppl_caveat"):
        log(f"  [CAVEAT] {TASK['nonstandard_ppl_caveat']}")
    log_sep("-")
    log(f"  {'grid point':<16}{'x':>11}  " + "".join(f"{a:>13}" for a in arms))
    for label in labels:
        row = f"  {label:<16}{xvals[label]:>11.4g}  "
        for arm in arms:
            v = table[label][arm]
            row += f"{v:>13.5g}" if _is_finite(v) else f"{'nan':>13}"
        log(row + ("   [reused baseline]" if is_base[label] else ""))

    log_sep("-")
    log(f"  delta vs {ref}  (d>0 => arm beats {ref} at that grid point; "
        f"direction-normalised relative)")
    deltas = {a: {} for a in arms if a != ref}
    for label in labels:
        rv = table[label].get(ref, float("nan"))
        bits = []
        for arm in deltas:
            av = table[label][arm]
            if _is_finite(rv) and rv != 0 and _is_finite(av):
                d = ((rv - av) / abs(rv) if PRIMARY_LOWER_BETTER
                     else (av - rv) / abs(rv))
            else:
                d = float("nan")
            deltas[arm][label] = d
            bits.append(f"{arm}:{d:+.3f}")
        log(f"    {label:<16} " + "  ".join(bits))

    spearman = {}
    if SWEEP_TYPE == "batchsize":
        log_sep("-")
        log(f"  pre-registered quantity (benchmark protocol sec 9.2): "
            f"Spearman(batch size, delta vs {ref}) per arm.")
        if ref == "EvieKF":
            log(f"  -> the EvieKFu row is the C1 test: rho < 0 (with d = "
                f"normalised EvieKF-minus-EvieKFu) means the centred edge grows "
                f"as batch size shrinks.")
        else:
            log(f"  NOTE: reference is {ref} (EvieKF not among the sweep arms) -- "
                f"this trends each arm's edge over {ref}, not the C1 gap.")
        for arm in deltas:
            xy = [(xvals[l], deltas[arm][l]) for l in labels
                  if _is_finite(deltas[arm][l])]
            if len(xy) >= 3:
                rho, p = spearmanr([a for a, _ in xy], [b for _, b in xy])
                spearman[arm] = {"rho": float(rho), "p": float(p), "n": len(xy)}
                log(f"    {arm:<12} rho={rho:+.3f}  p={p:.3g}  n={len(xy)}")
            else:
                spearman[arm] = None
                log(f"    {arm:<12} too few finite points")

    _sweep_write_csv(cells, labels, arms, units)
    summary = {
        "task_name": TASK_NAME, "sweep_type": SWEEP_TYPE,
        "base_task_name": BASE_TASK_NAME, "primary_metric": PRIMARY_METRIC,
        "primary_lower_better": PRIMARY_LOWER_BETTER, "reference": ref,
        "grid_labels": labels, "grid_x": xvals, "grid_is_baseline": is_base,
        "arms": arms, "seeds": SWEEP_SEEDS,
        "eviekf_sweep_gamma": (EVIEKF_SWEEP_GAMMA
                               if any(a in ("EvieKF", "EvieKFu", "EvieDiag")
                                      for a in arms) else None),
        "c1_row": ("EvieKFu" if ref == "EvieKF" and "EvieKFu" in arms else None),
        "table": table, "per_seed": per_seed, "deltas": deltas,
        "spearman_batch_vs_delta": spearman,
        "nonstandard_ppl_caveat": TASK.get("nonstandard_ppl_caveat"),
        "note": ("fixed step budget per grid point; absolute values not "
                 "comparable across grid points, only within-grid-point arm "
                 "deltas (benchmark protocol sec 9.2/9.3)"),
    }
    _write_json(SWEEP_SUMMARY, summary)
    log_sep("=")
    log(f"  wrote {SWEEP_SUMMARY}  and  {SWEEP_RESULTS}")
    log(f"  DONE {datetime.now().isoformat()}")
    _log_fh.flush()


if __name__ == "__main__":
    sweep_main()
